export const HELP_ARTICLES: Record<string, HelpArticle[]> = {"en":[{"slug":"after-you-graduate","title":"What you keep after you graduate","summary":"What changes when your school moves you to its alumni, what you can still use, and where to find it.","roles":["alumni"],"group":"Getting started","features":["career-core","mentoring"],"checked":"2026-11-12","order":1,"short":["You keep the same account, sign-in, résumés, credentials and results. Your school's career pages stay open to you.","Your alumni home page opens when you sign in. Select Open career services for the pages you used as a student.","A few appointments and sessions may be for students only. That's your school's choice."],"blocks":[{"t":"p","c":[{"t":"text","v":"When you graduate, your school's "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" moves you from its students to its alumni. You get a notification: "},{"t":"b","v":"Welcome to the alumni network"},{"t":"text","v":". If you've graduated and still show as a student, ask your career center to update your record."}]},{"t":"h2","c":[{"t":"text","v":"What stays the same"}]},{"t":"p","c":[{"t":"text","v":"You sign in the same way, with the same e-mail address and password. Nothing in your account is deleted when you graduate. You keep:"}]},{"t":"ul","items":[[{"t":"text","v":"your "},{"t":"link","v":"résumés","href":"/help/resumes"},{"t":"text","v":", cover letters and job checks;"}],[{"t":"text","v":"your "},{"t":"link","v":"credentials and skill passport","href":"/help/credentials-and-passport"},{"t":"text","v":";"}],[{"t":"text","v":"your results, your career record and your conversations with the career center;"}],[{"t":"text","v":"your privacy choices. See "},{"t":"link","v":"Your data and privacy","href":"/help/your-data"},{"t":"text","v":"."}]]},{"t":"h2","c":[{"t":"text","v":"Your alumni home page"}]},{"t":"p","c":[{"t":"text","v":"When you sign in, your "},{"t":"link","v":"alumni home page","href":"/alumni"},{"t":"text","v":" opens. It shows two cards:"}]},{"t":"ul","items":[[{"t":"ui","v":"Mentoring"},{"t":"text","v":": help current students as a "},{"t":"term","v":"mentor","key":"mentoring"},{"t":"text","v":". See "},{"t":"link","v":"Be a mentor","href":"/help/be-a-mentor"},{"t":"text","v":"."}],[{"t":"ui","v":"Career services"},{"t":"text","v":": select "},{"t":"ui","v":"Open career services"},{"t":"text","v":" to open the career pages you used as a student."}]]},{"t":"p","c":[{"t":"text","v":"To come back to your alumni home page from the career pages, open your account menu (the circle with your initials, top right) and select "},{"t":"ui","v":"My school"},{"t":"text","v":" under "},{"t":"ui","v":"Switch to"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"What you can still use"}]},{"t":"p","c":[{"t":"text","v":"Your school's career pages work for you as they did before. You can:"}]},{"t":"ul","items":[[{"t":"link","v":"book an appointment","href":"/help/appointments"},{"t":"text","v":" or join a group session;"}],[{"t":"link","v":"get your résumé or documents reviewed","href":"/help/document-review"},{"t":"text","v":";"}],[{"t":"link","v":"message the career center","href":"/help/messages"},{"t":"text","v":";"}],[{"t":"link","v":"find jobs and sign up for interviews","href":"/help/campus-jobs-and-interviews"},{"t":"text","v":";"}],[{"t":"link","v":"find a mentor","href":"/help/mentoring"},{"t":"text","v":" for yourself."}]]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Your record"},{"t":"text","v":", open "},{"t":"ui","v":"My next step"},{"t":"text","v":" to tell your career center where you're headed: a job, further study or something else. Only you and your career center see it."}]},{"t":"note","c":[{"t":"text","v":"Your school decides who can book each kind of appointment and group session. Some are for students only, and some are for alumni only, so your choices may differ from before."}]},{"t":"h2","c":[{"t":"text","v":"Need help?"}]},{"t":"p","c":[{"t":"text","v":"Your school helps first. The help center shows your school's contact at the end of each article. See "},{"t":"link","v":"Get help and contact support","href":"/help/help-and-support"},{"t":"text","v":"."}]}],"headings":["What stays the same","Your alumni home page","What you can still use","Need help?"],"text":"When you graduate, your school's career center moves you from its students to its alumni. You get a notification: Welcome to the alumni network. If you've graduated and still show as a student, ask your career center to update your record. What stays the same You sign in the same way, with the same e-mail address and password. Nothing in your account is deleted when you graduate. You keep: your résumés, cover letters and job checks;your credentials and skill passport;your results, your career record and your conversations with the career center;your privacy choices. See Your data and privacy. Your alumni home page When you sign in, your alumni home page opens. It shows two cards: Mentoring: help current students as a mentor. See Be a mentor.Career services: select Open career services to open the career pages you used as a student. To come back to your alumni home page from the career pages, open your account menu (the circle with your initials, top right) and select My school under Switch to. What you can still use Your school's career pages work for you as they did before. You can: book an appointment or join a group session;get your résumé or documents reviewed;message the career center;find jobs and sign up for interviews;find a mentor for yourself. Under Your record, open My next step to tell your career center where you're headed: a job, further study or something else. Only you and your career center see it. Your school decides who can book each kind of appointment and group session. Some are for students only, and some are for alumni only, so your choices may differ from before. Need help? Your school helps first. The help center shows your school's contact at the end of each article. See Get help and contact support."},{"slug":"getting-started","title":"Get your school started","summary":"The five steps from an empty school to its first decided result, and how the checklist on your home page tracks them.","roles":["admin"],"group":"Getting started","features":["career-core","class-assessments"],"checked":"2026-11-11","order":1,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"When you open the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" as a school admin, your home page shows "},{"t":"ui","v":"Get started with Build & Defend"},{"t":"text","v":". It lists five steps, and each one ticks itself when your school has really done it. You don't mark anything by hand."}]},{"t":"ol","items":[[{"t":"ui","v":"Add your faculty"},{"t":"text","v":". Invite your teachers from "},{"t":"ui","v":"People"},{"t":"text","v":". Each teacher gets an e-mail with where to sign in. See "},{"t":"link","v":"Add people to your school","href":"/help/add-people"},{"t":"text","v":"."}],[{"t":"ui","v":"Add a class and its students"},{"t":"text","v":". Teachers create their classes and import the "},{"t":"term","v":"roster","key":"roster"},{"t":"text","v":" from a spreadsheet. See "},{"t":"link","v":"Create a class and import its roster","href":"/help/classes-and-rosters"},{"t":"text","v":"."}],[{"t":"ui","v":"Create an assessment from a template"},{"t":"text","v":". A teacher picks a template, such as an essay or a project defense, and adjusts the "},{"t":"term","v":"rubric","key":"rubric"},{"t":"text","v":" and the "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":". See "},{"t":"link","v":"Create an assessment","href":"/help/create-an-assessment"},{"t":"text","v":"."}],[{"t":"ui","v":"Give it to a class"},{"t":"text","v":". Students are e-mailed and see it under "},{"t":"ui","v":"My assessments"},{"t":"text","v":". See "},{"t":"link","v":"Give an assessment to a class","href":"/help/give-to-a-class"},{"t":"text","v":"."}],[{"t":"ui","v":"Decide the first results"},{"t":"text","v":". Teachers review each student's work and viva, and decide. See "},{"t":"link","v":"Review a student's evidence","href":"/help/review-the-evidence"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Each step has a link that takes you to the page where it's done."}]},{"t":"note","c":[{"t":"text","v":"When all five steps are done, the checklist goes away. If your school is in a pilot, your home page then shows the pilot's dates and a link to its results."}]},{"t":"shot","name":"school-checklist","alt":"The Get started with Build & Defend checklist on a school admin's home page, with its five steps","w":1600,"h":642},{"t":"h2","c":[{"t":"text","v":"Who does what"}]},{"t":"ul","items":[[{"t":"b","v":"School admins"},{"t":"text","v":" invite people, see every class and assessment, and can resolve "},{"t":"term","v":"appeals","key":"appeal"},{"t":"text","v":"."}],[{"t":"b","v":"Teachers"},{"t":"text","v":" create classes, assessments and "},{"t":"term","v":"decisions","key":"decision"},{"t":"text","v":" for their own classes."}],[{"t":"b","v":"Students"},{"t":"text","v":" hand in their work and do the viva."}]]}],"headings":["Who does what"],"text":"When you open the career center as a school admin, your home page shows Get started with Build & Defend. It lists five steps, and each one ticks itself when your school has really done it. You don't mark anything by hand. Add your faculty. Invite your teachers from People. Each teacher gets an e-mail with where to sign in. See Add people to your school.Add a class and its students. Teachers create their classes and import the roster from a spreadsheet. See Create a class and import its roster.Create an assessment from a template. A teacher picks a template, such as an essay or a project defense, and adjusts the rubric and the viva. See Create an assessment.Give it to a class. Students are e-mailed and see it under My assessments. See Give an assessment to a class.Decide the first results. Teachers review each student's work and viva, and decide. See Review a student's evidence. Each step has a link that takes you to the page where it's done. When all five steps are done, the checklist goes away. If your school is in a pilot, your home page then shows the pilot's dates and a link to its results. Who does what School admins invite people, see every class and assessment, and can resolve appeals.Teachers create classes, assessments and decisions for their own classes.Students hand in their work and do the viva."},{"slug":"member-getting-started","title":"Get started on your own","summary":"What you can do in Edulexa without a school, how the menus are laid out, and where to start.","roles":["member"],"group":"Getting started","features":["member-dashboard","individual-plans"],"checked":"2026-11-12","order":1,"short":["Your Dashboard suggests a few first steps. Select Start on one.","Practice has drills, interviews and exams. Guidance helps you choose a direction. Your record keeps your results, credentials and résumés.","Interview practice and voice defenses use voice minutes. Pricing and minutes shows how many you have."],"blocks":[{"t":"p","c":[{"t":"text","v":"You don't need a school to use Edulexa. On your own, you can practice real work, prove what you can do, and keep the proof in one place."}]},{"t":"h2","c":[{"t":"text","v":"Your dashboard"}]},{"t":"p","c":[{"t":"link","v":"Dashboard","href":"/dashboard"},{"t":"text","v":" is your home page. It shows:"}]},{"t":"ul","items":[[{"t":"ui","v":"Get started"},{"t":"text","v":", and later "},{"t":"ui","v":"Up next"},{"t":"text","v":": a few good next steps, such as the career quiz or a skills exam. Select "},{"t":"ui","v":"Start"},{"t":"text","v":" on one."}],[{"t":"ui","v":"Current streak"},{"t":"text","v":": how many days in a row you've practiced. "},{"t":"ui","v":"Active days"},{"t":"text","v":" counts the last 30 days."}],[{"t":"ui","v":"Verified credentials"},{"t":"text","v":": the "},{"t":"term","v":"credentials","key":"credential"},{"t":"text","v":" you've earned so far."}],[{"t":"ui","v":"Interview minutes"},{"t":"text","v":": the "},{"t":"term","v":"voice minutes","key":"voice-minutes"},{"t":"text","v":" you have left, and when they renew."}],[{"t":"ui","v":"Skills"},{"t":"text","v":", "},{"t":"ui","v":"Recent results"},{"t":"text","v":" and "},{"t":"ui","v":"Credentials"},{"t":"text","v":": these fill in as your work is graded."}],[{"t":"ui","v":"Career track"},{"t":"text","v":": your career quiz result, or "},{"t":"ui","v":"Take the quiz"},{"t":"text","v":"."}]]},{"t":"h2","c":[{"t":"text","v":"The menus"}]},{"t":"ul","items":[[{"t":"ui","v":"Practice"},{"t":"text","v":": interview and speaking practice, engineering drills, coding challenges, written exams and the leaderboard."}],[{"t":"ui","v":"Guidance"},{"t":"text","v":": the career quiz, your career path, course suggestions, "},{"t":"term","v":"mentoring","key":"mentoring"},{"t":"text","v":", and your questions to Edulexa."}],[{"t":"ui","v":"Your record"},{"t":"text","v":": "},{"t":"ui","v":"My results"},{"t":"text","v":", "},{"t":"ui","v":"Credentials"},{"t":"text","v":", "},{"t":"ui","v":"Skill passport"},{"t":"text","v":", "},{"t":"ui","v":"Résumés"},{"t":"text","v":", "},{"t":"ui","v":"Job check"},{"t":"text","v":", "},{"t":"ui","v":"Cover letters"},{"t":"text","v":" and "},{"t":"ui","v":"Campus"},{"t":"text","v":" (tasks a school gives you, how campus jobs work, and a connection check; see "},{"t":"link","v":"Campus","href":"/help/member-campus"},{"t":"text","v":")."}]]},{"t":"p","c":[{"t":"text","v":"Point at a menu to see its pages. The pages of the menu you're in also show as a bar under the header. On a phone, open the menu button at the top."}]},{"t":"p","c":[{"t":"text","v":"Your name at the top right opens the account menu, with "},{"t":"ui","v":"Your account"},{"t":"text","v":", "},{"t":"ui","v":"Pricing and minutes"},{"t":"text","v":" and "},{"t":"ui","v":"Privacy and your data"},{"t":"text","v":". The bell opens your notifications."}]},{"t":"h2","c":[{"t":"text","v":"Voice minutes"}]},{"t":"p","c":[{"t":"text","v":"Interview practice and "},{"t":"term","v":"voice defenses","key":"voice-defense"},{"t":"text","v":" are spoken conversations, so they use voice minutes. Your plan gives you minutes each month. They don't roll over. "},{"t":"link","v":"Pricing and minutes","href":"/pricing"},{"t":"text","v":" shows your plan, the other plans and top-up minutes, which are used after your monthly minutes."}]},{"t":"h2","c":[{"t":"text","v":"Need help?"}]},{"t":"p","c":[{"t":"text","v":"Use the question-mark button at the top of any page. If a guide doesn't answer your question, e-mail support@edulexa.com."}]},{"t":"p","c":[{"t":"text","v":"Next step: find the area that suits you with the career quiz. See "},{"t":"link","v":"Find your direction","href":"/help/career-direction"},{"t":"text","v":"."}]}],"headings":["Your dashboard","The menus","Voice minutes","Need help?"],"text":"You don't need a school to use Edulexa. On your own, you can practice real work, prove what you can do, and keep the proof in one place. Your dashboard Dashboard is your home page. It shows: Get started, and later Up next: a few good next steps, such as the career quiz or a skills exam. Select Start on one.Current streak: how many days in a row you've practiced. Active days counts the last 30 days.Verified credentials: the credentials you've earned so far.Interview minutes: the voice minutes you have left, and when they renew.Skills, Recent results and Credentials: these fill in as your work is graded.Career track: your career quiz result, or Take the quiz. The menus Practice: interview and speaking practice, engineering drills, coding challenges, written exams and the leaderboard.Guidance: the career quiz, your career path, course suggestions, mentoring, and your questions to Edulexa.Your record: My results, Credentials, Skill passport, Résumés, Job check, Cover letters and Campus (tasks a school gives you, how campus jobs work, and a connection check; see Campus). Point at a menu to see its pages. The pages of the menu you're in also show as a bar under the header. On a phone, open the menu button at the top. Your name at the top right opens the account menu, with Your account, Pricing and minutes and Privacy and your data. The bell opens your notifications. Voice minutes Interview practice and voice defenses are spoken conversations, so they use voice minutes. Your plan gives you minutes each month. They don't roll over. Pricing and minutes shows your plan, the other plans and top-up minutes, which are used after your monthly minutes. Need help? Use the question-mark button at the top of any page. If a guide doesn't answer your question, e-mail support@edulexa.com. Next step: find the area that suits you with the career quiz. See Find your direction."},{"slug":"help-and-support","title":"Get help and contact support","summary":"Where the help center is, and who to contact when an article doesn't answer your question.","roles":["everyone"],"group":"Getting started","features":["help-center"],"checked":"2026-11-11","order":2,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"Open the help center from the question-mark button at the top of any page. Search for what you're trying to do, or browse the guides for your role. Each article shows when it was last checked against the app."}]},{"t":"h2","c":[{"t":"text","v":"Still need help?"}]},{"t":"p","c":[{"t":"text","v":"At the end of every help page is "},{"t":"ui","v":"Still need help?"},{"t":"text","v":". Who helps you depends on how you use Edulexa:"}]},{"t":"ul","items":[[{"t":"b","v":"School admins, teachers, career staff, admissions counselors at guidance institutes, recruiters, employers and mentors"},{"t":"text","v":" write to Edulexa support from the form. Say "},{"t":"ui","v":"What it's about"},{"t":"text","v":" and "},{"t":"ui","v":"What happened, and what you expected"},{"t":"text","v":", then select "},{"t":"ui","v":"Send to support"},{"t":"text","v":". We see the page you came from, and we reply within two working days, by e-mail."}],[{"t":"b","v":"Students and graduates"},{"t":"text","v":" get help from their own school first. The help center shows your school's contact, or you can ask your teacher or "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":"."}],[{"t":"b","v":"If you use Edulexa on your own, without a school,"},{"t":"text","v":" e-mail us at support@edulexa.com."}]]},{"t":"h2","c":[{"t":"text","v":"Tell us what's missing"}]},{"t":"p","c":[{"t":"text","v":"Each article asks "},{"t":"ui","v":"Was this helpful?"},{"t":"text","v":". Your answer is counted without your name or school, and so are searches that find nothing, so we know which guides to improve or write next."}]}],"headings":["Still need help?","Tell us what's missing"],"text":"Open the help center from the question-mark button at the top of any page. Search for what you're trying to do, or browse the guides for your role. Each article shows when it was last checked against the app. Still need help? At the end of every help page is Still need help?. Who helps you depends on how you use Edulexa: School admins, teachers, career staff, admissions counselors at guidance institutes, recruiters, employers and mentors write to Edulexa support from the form. Say What it's about and What happened, and what you expected, then select Send to support. We see the page you came from, and we reply within two working days, by e-mail.Students and graduates get help from their own school first. The help center shows your school's contact, or you can ask your teacher or career center.If you use Edulexa on your own, without a school, e-mail us at support@edulexa.com. Tell us what's missing Each article asks Was this helpful?. Your answer is counted without your name or school, and so are searches that find nothing, so we know which guides to improve or write next."},{"slug":"employer-getting-started","title":"Set up your company and ask to recruit at a school","summary":"Create your company's employer account, invite your colleagues, and ask a school's career center for approval to recruit its students.","roles":["employer"],"group":"Getting started","features":["employer-accounts"],"checked":"2026-11-12","order":5,"short":["Create your company account, then ask each school for approval on the Schools page.","Once a school approves you, you can send it jobs, interview requests and challenges, and browse its résumé book.","The account owner edits the company profile and invites colleagues."],"blocks":[{"t":"p","c":[{"t":"text","v":"To recruit at a school through Edulexa, your company needs an employer account, and the school's "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" must approve it."}]},{"t":"h2","c":[{"t":"text","v":"Create your company account"}]},{"t":"ol","items":[[{"t":"text","v":"Open the employer area. If your company isn't set up yet, you see "},{"t":"ui","v":"Set up your company"},{"t":"text","v":"."}],[{"t":"text","v":"Fill in your company's details and select "},{"t":"ui","v":"Create company account"},{"t":"text","v":". You're the account owner."}]]},{"t":"p","c":[{"t":"text","v":"If a colleague already set up your company, ask them to invite you instead."}]},{"t":"p","c":[{"t":"text","v":"Your home page shows how Edulexa checked your company:"}]},{"t":"ul","items":[[{"t":"ui","v":"E-mail address checked"},{"t":"text","v":": your sign-in e-mail address ends with your company website's name, so Edulexa confirmed the company automatically. A free e-mail service doesn't count."}],[{"t":"ui","v":"Unverified"},{"t":"text","v":": Edulexa couldn't confirm the company automatically. Schools may ask for more detail before they approve you."}],[{"t":"ui","v":"Staff verified"},{"t":"text","v":": Edulexa staff checked and verified your company."}],[{"t":"ui","v":"Under review"},{"t":"text","v":": you can't ask new schools until the review is finished."}]]},{"t":"h2","c":[{"t":"text","v":"Your company profile and team"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Your company"},{"t":"text","v":" in the menu:"}]},{"t":"ul","items":[[{"t":"ui","v":"Company"},{"t":"text","v":": the "},{"t":"ui","v":"Company profile"},{"t":"text","v":" that schools see when you ask to recruit their students. Only the account owner can edit it. If you change the website, your company is no longer confirmed by your e-mail address."}],[{"t":"ui","v":"Team"},{"t":"text","v":": the account owner invites colleagues. Under "},{"t":"ui","v":"Invite a colleague"},{"t":"text","v":", fill in their "},{"t":"ui","v":"Email"},{"t":"text","v":", "},{"t":"ui","v":"Name"},{"t":"text","v":" and "},{"t":"ui","v":"Job title"},{"t":"text","v":", then select "},{"t":"ui","v":"Send invite"},{"t":"text","v":". They join when they sign in with that address. "},{"t":"ui","v":"Resend"},{"t":"text","v":" sends a reminder, and "},{"t":"ui","v":"Cancel invite"},{"t":"text","v":" or "},{"t":"ui","v":"Remove"},{"t":"text","v":" takes their access away."}]]},{"t":"p","c":[{"t":"text","v":"If you recruit for more than one company, choose the company at the top of each page."}]},{"t":"h2","c":[{"t":"text","v":"Ask to recruit at a school"}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Schools"},{"t":"text","v":". Under "},{"t":"ui","v":"Find a school"},{"t":"text","v":", type the "},{"t":"ui","v":"School name"},{"t":"text","v":" and select "},{"t":"ui","v":"Search"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Request access"},{"t":"text","v":". Add a note about who you hire and the roles you recruit for. It helps the school decide."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Send request"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The school's career center approves, declines or blocks your request, and you're told when they decide. "},{"t":"ui","v":"Your schools"},{"t":"text","v":" lists each school with its status and the school's note. If a school declined, you can "},{"t":"ui","v":"Request again"},{"t":"text","v":". A school that blocked you can't be asked again."}]},{"t":"p","c":[{"t":"text","v":"Once a school approves you, you can send it jobs, interview requests and challenges, see its career fairs, and browse its "},{"t":"term","v":"résumé book","key":"resume-book"},{"t":"text","v":" if it has one."}]}],"headings":["Create your company account","Your company profile and team","Ask to recruit at a school"],"text":"To recruit at a school through Edulexa, your company needs an employer account, and the school's career center must approve it. Create your company account Open the employer area. If your company isn't set up yet, you see Set up your company.Fill in your company's details and select Create company account. You're the account owner. If a colleague already set up your company, ask them to invite you instead. Your home page shows how Edulexa checked your company: E-mail address checked: your sign-in e-mail address ends with your company website's name, so Edulexa confirmed the company automatically. A free e-mail service doesn't count.Unverified: Edulexa couldn't confirm the company automatically. Schools may ask for more detail before they approve you.Staff verified: Edulexa staff checked and verified your company.Under review: you can't ask new schools until the review is finished. Your company profile and team Under Your company in the menu: Company: the Company profile that schools see when you ask to recruit their students. Only the account owner can edit it. If you change the website, your company is no longer confirmed by your e-mail address.Team: the account owner invites colleagues. Under Invite a colleague, fill in their Email, Name and Job title, then select Send invite. They join when they sign in with that address. Resend sends a reminder, and Cancel invite or Remove takes their access away. If you recruit for more than one company, choose the company at the top of each page. Ask to recruit at a school Open Schools. Under Find a school, type the School name and select Search.Select Request access. Add a note about who you hire and the roles you recruit for. It helps the school decide.Select Send request. The school's career center approves, declines or blocks your request, and you're told when they decide. Your schools lists each school with its status and the school's note. If a school declined, you can Request again. A school that blocked you can't be asked again. Once a school approves you, you can send it jobs, interview requests and challenges, see its career fairs, and browse its résumé book if it has one."},{"slug":"institute-setup","title":"Set up your institute","summary":"The four setup steps, your admissions team and who can sign in, and bringing leads over from another system.","roles":["admissions"],"group":"Getting started","features":["institute-setup","staff-access","admissions-crm"],"checked":"2026-11-12","order":5,"short":["School setup has four steps: your school, your first form, your team and your website. Skip any and come back later.","Staff access decides who can sign in. Admissions settings holds your admissions team and e-mail templates.","Coming from another system? Import leads takes a spreadsheet, and you can undo an import."],"blocks":[{"t":"p","c":[{"t":"text","v":"Your institute's area has three menus: "},{"t":"ui","v":"Leads"},{"t":"text","v":", "},{"t":"ui","v":"Forms"},{"t":"text","v":" and "},{"t":"ui","v":"Settings"},{"t":"text","v":". Admins see all three. Counselors see only the admissions "},{"t":"term","v":"leads","key":"lead"},{"t":"text","v":", where they work with the people who asked about your courses."}]},{"t":"h2","c":[{"t":"text","v":"The four setup steps"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"School setup"},{"t":"text","v":" under "},{"t":"ui","v":"Settings"},{"t":"text","v":". Each step can be skipped; come back from the checklist on your "},{"t":"link","v":"admissions leads","href":"/institute/dashboard"},{"t":"text","v":" page."}]},{"t":"ol","items":[[{"t":"ui","v":"Your school"},{"t":"text","v":": what kind of organization you are, your "},{"t":"ui","v":"Logo"},{"t":"text","v":" and brand color, your "},{"t":"ui","v":"Website"},{"t":"text","v":", the e-mail address for families' replies, and the "},{"t":"ui","v":"Spelling on your forms, reports and e-mails"},{"t":"text","v":". Your logo and color go on your forms, the reports people receive and your e-mails. Select "},{"t":"ui","v":"Save and continue"},{"t":"text","v":"."}],[{"t":"ui","v":"Your first form"},{"t":"text","v":": pick a template made for schools like yours. It's published with your logo and color. You can change its questions later. See "},{"t":"link","v":"Build your guidance forms","href":"/help/guidance-forms"},{"t":"text","v":"."}],[{"t":"ui","v":"Your team"},{"t":"text","v":": invite your counselors and admins."}],[{"t":"ui","v":"Your website"},{"t":"text","v":": copy "},{"t":"ui","v":"The form's link"},{"t":"text","v":", or the code for your website. If someone else runs your website, enter their e-mail address and we'll send them the code and the instructions."}]]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Finish and open the dashboard"},{"t":"text","v":" at the end. Until every step is done, a setup checklist shows on your admissions leads page. Each step ticks itself when it's done. Select "},{"t":"ui","v":"Hide"},{"t":"text","v":" to put it away."}]},{"t":"h2","c":[{"t":"text","v":"Who can sign in"}]},{"t":"p","c":[{"t":"ui","v":"Staff access"},{"t":"text","v":" lists who can sign in for your institute, and as what:"}]},{"t":"ul","items":[[{"t":"ui","v":"Institute admin"},{"t":"text","v":": everything at your institute, including staff access and settings;"}],[{"t":"ui","v":"Counselor"},{"t":"text","v":": leads, follow-ups, meetings and guidance results;"}],[{"t":"ui","v":"Faculty"},{"t":"text","v":": teaching tools for their own courses and students."}]]},{"t":"p","c":[{"t":"text","v":"Enter a "},{"t":"ui","v":"Work e-mail"},{"t":"text","v":" and choose a "},{"t":"ui","v":"Role"},{"t":"text","v":", then select "},{"t":"ui","v":"Send invitation"},{"t":"text","v":". New people get an e-mail to set their password. People who already have an account get access at once. Changes take effect the next time the person signs in. "},{"t":"ui","v":"History of changes"},{"t":"text","v":" shows who changed what."}]},{"t":"h2","c":[{"t":"text","v":"Your admissions team and templates"}]},{"t":"p","c":[{"t":"ui","v":"Admissions settings"},{"t":"text","v":" has three tabs:"}]},{"t":"ul","items":[[{"t":"ui","v":"Team"},{"t":"text","v":": the people who can own leads and get follow-up reminders. Add each one with the e-mail they sign in with, so "},{"t":"ui","v":"My leads"},{"t":"text","v":" finds their leads."}],[{"t":"ui","v":"Email templates"},{"t":"text","v":": the e-mails your team sends often. Names, the course and your institute are filled in for each person when it's sent."}],[{"t":"ui","v":"Connected apps"},{"t":"text","v":": "},{"t":"ui","v":"SMS and WhatsApp"},{"t":"text","v":", and "},{"t":"ui","v":"Send leads to your own systems"},{"t":"text","v":" if you also keep your leads in another system. That part is for your IT team: it names the address and the key they must set up."}]]},{"t":"h2","c":[{"t":"text","v":"Bring your leads over"}]},{"t":"p","c":[{"t":"text","v":"On "},{"t":"ui","v":"Import leads"},{"t":"text","v":", choose a "},{"t":"ui","v":"Spreadsheet (CSV file)"},{"t":"text","v":" exported from your old system, such as VirtualAdviser. An Excel file? In Excel, choose File → Save As → CSV (UTF-8) first. Then:"}]},{"t":"ol","items":[[{"t":"text","v":"Say "},{"t":"ui","v":"Where the leads came from"},{"t":"text","v":". It becomes their source and a tag, so you can find them."}],[{"t":"text","v":"Choose how to read dates such as 03/04/2026, and what to do with someone who is already in your leads (the same e-mail address or phone number): add the row to their lead as a note, or leave it out."}],[{"t":"text","v":"Check "},{"t":"ui","v":"What each column is"},{"t":"text","v":", then look at "},{"t":"ui","v":"What will happen"},{"t":"text","v":". Nothing is saved until you import, and nothing is sent to the people you import."}]]},{"t":"p","c":[{"t":"ui","v":"Past imports"},{"t":"text","v":" lists each import. Select "},{"t":"ui","v":"Undo"},{"t":"text","v":" to take one back."}]},{"t":"p","c":[{"t":"ui","v":"Billing"},{"t":"text","v":" shows your plan."}]}],"headings":["The four setup steps","Who can sign in","Your admissions team and templates","Bring your leads over"],"text":"Your institute's area has three menus: Leads, Forms and Settings. Admins see all three. Counselors see only the admissions leads, where they work with the people who asked about your courses. The four setup steps Open School setup under Settings. Each step can be skipped; come back from the checklist on your admissions leads page. Your school: what kind of organization you are, your Logo and brand color, your Website, the e-mail address for families' replies, and the Spelling on your forms, reports and e-mails. Your logo and color go on your forms, the reports people receive and your e-mails. Select Save and continue.Your first form: pick a template made for schools like yours. It's published with your logo and color. You can change its questions later. See Build your guidance forms.Your team: invite your counselors and admins.Your website: copy The form's link, or the code for your website. If someone else runs your website, enter their e-mail address and we'll send them the code and the instructions. Select Finish and open the dashboard at the end. Until every step is done, a setup checklist shows on your admissions leads page. Each step ticks itself when it's done. Select Hide to put it away. Who can sign in Staff access lists who can sign in for your institute, and as what: Institute admin: everything at your institute, including staff access and settings;Counselor: leads, follow-ups, meetings and guidance results;Faculty: teaching tools for their own courses and students. Enter a Work e-mail and choose a Role, then select Send invitation. New people get an e-mail to set their password. People who already have an account get access at once. Changes take effect the next time the person signs in. History of changes shows who changed what. Your admissions team and templates Admissions settings has three tabs: Team: the people who can own leads and get follow-up reminders. Add each one with the e-mail they sign in with, so My leads finds their leads.Email templates: the e-mails your team sends often. Names, the course and your institute are filled in for each person when it's sent.Connected apps: SMS and WhatsApp, and Send leads to your own systems if you also keep your leads in another system. That part is for your IT team: it names the address and the key they must set up. Bring your leads over On Import leads, choose a Spreadsheet (CSV file) exported from your old system, such as VirtualAdviser. An Excel file? In Excel, choose File → Save As → CSV (UTF-8) first. Then: Say Where the leads came from. It becomes their source and a tag, so you can find them.Choose how to read dates such as 03/04/2026, and what to do with someone who is already in your leads (the same e-mail address or phone number): add the row to their lead as a note, or leave it out.Check What each column is, then look at What will happen. Nothing is saved until you import, and nothing is sent to the people you import. Past imports lists each import. Select Undo to take one back. Billing shows your plan."},{"slug":"recruiter-getting-started","title":"Get started on the recruiter portal","summary":"How to get recruiter access, what each part of the portal is for, and how to invite your colleagues.","roles":["recruiter"],"group":"Getting started","features":["recruiter-access","recruiter-team","ats-integrations"],"checked":"2026-11-12","order":5,"short":["Ask for recruiter access. Edulexa checks each request and connects you to your company.","The menu follows the work. Candidates, then Review, then Fairness, then Settings.","The people who manage your team invite colleagues from Team."],"blocks":[{"t":"p","c":[{"t":"text","v":"On the recruiter portal, your company sends assessments to candidates, reviews what they did, and records fair "},{"t":"term","v":"decisions","key":"decision"},{"t":"text","v":". Edulexa never advances or turns down a candidate on its own. A person on your team always decides."}]},{"t":"h2","c":[{"t":"text","v":"Get access"}]},{"t":"ol","items":[[{"t":"text","v":"Create a free Edulexa account, or sign in."}],[{"t":"text","v":"Open "},{"t":"link","v":"recruiter access","href":"/access/recruiter"},{"t":"text","v":". Fill in "},{"t":"ui","v":"Company"},{"t":"text","v":", "},{"t":"ui","v":"Company website"},{"t":"text","v":" and "},{"t":"ui","v":"Your job title"},{"t":"text","v":", then select "},{"t":"ui","v":"Send request"},{"t":"text","v":"."}],[{"t":"text","v":"Edulexa checks every request before giving anyone access to candidates' information. Requests from a company e-mail address are approved faster. We e-mail you when it's decided."}],[{"t":"text","v":"Once it's approved, sign out and sign in again, then select "},{"t":"ui","v":"Open the recruiter portal"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"If a page says your recruiter account isn't connected to a company yet, sign out and sign in again. If that doesn't help, contact Edulexa support."}]},{"t":"h2","c":[{"t":"text","v":"Find your way around"}]},{"t":"p","c":[{"t":"text","v":"The menu at the top has four parts, in the order of the work:"}]},{"t":"ul","items":[[{"t":"ui","v":"Candidates"},{"t":"text","v":": the assessments you sent, where each candidate is, and your decisions."}],[{"t":"ui","v":"Review"},{"t":"text","v":": "},{"t":"ui","v":"Evidence packs"},{"t":"text","v":", "},{"t":"ui","v":"Work trials"},{"t":"text","v":", "},{"t":"ui","v":"Proctored sessions"},{"t":"text","v":" and "},{"t":"ui","v":"Challenge results"},{"t":"text","v":"."}],[{"t":"ui","v":"Fairness"},{"t":"text","v":": "},{"t":"ui","v":"Appeals"},{"t":"text","v":", "},{"t":"ui","v":"Accommodations"},{"t":"text","v":", "},{"t":"ui","v":"Validity & bias audit"},{"t":"text","v":" and "},{"t":"ui","v":"Transparency"},{"t":"text","v":"."}],[{"t":"ui","v":"Settings"},{"t":"text","v":": "},{"t":"ui","v":"Team"},{"t":"text","v":" and "},{"t":"ui","v":"ATS connections"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"On a phone, select "},{"t":"ui","v":"Menu"},{"t":"text","v":" to see every page. The bell at the top opens your notifications."}]},{"t":"h2","c":[{"t":"text","v":"Your team"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Team"},{"t":"text","v":" under "},{"t":"ui","v":"Settings"},{"t":"text","v":". It lists the recruiters at your company, each "},{"t":"ui","v":"Joined"},{"t":"text","v":" or "},{"t":"ui","v":"Invited"},{"t":"text","v":". Everyone on the team sees the same candidates, reviews and settings."}]},{"t":"p","c":[{"t":"text","v":"If you manage the team, your name shows "},{"t":"ui","v":"Manages the team"},{"t":"text","v":", and you can invite colleagues:"}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"Invite a colleague"},{"t":"text","v":", fill in "},{"t":"ui","v":"First name"},{"t":"text","v":", "},{"t":"ui","v":"Last name"},{"t":"text","v":" and "},{"t":"ui","v":"Work e-mail"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Send invitation"},{"t":"text","v":". A new colleague gets an e-mail to set a password. Someone who already has an Edulexa account is added and told by e-mail."}],[{"t":"text","v":"If an invitation got lost, select "},{"t":"ui","v":"Resend"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"To withdraw an invitation or remove a colleague, select the bin button next to their name. Someone you remove is signed out. Only Edulexa can change the access of the people who manage the team."}]},{"t":"h2","c":[{"t":"text","v":"Connect your applicant tracking system"}]},{"t":"p","c":[{"t":"text","v":"If your company uses an applicant tracking system (ATS), such as Greenhouse, Lever or Workday, "},{"t":"ui","v":"ATS connections"},{"t":"text","v":" lets you invite candidates from it and get their results back there. Results carry the reviewer's decision, if there is one, and a link to the "},{"t":"term","v":"evidence pack","key":"evidence-pack"},{"t":"text","v":". They never carry an automatic verdict."}]},{"t":"p","c":[{"t":"text","v":"Your IT team usually sets this up. Under "},{"t":"ui","v":"New connection"},{"t":"text","v":", they choose the "},{"t":"ui","v":"Applicant tracking system"},{"t":"text","v":", give the connection a "},{"t":"ui","v":"Display name"},{"t":"text","v":" and enter what that system asks for. Then they select "},{"t":"ui","v":"Create connection"},{"t":"text","v":". Edulexa shows the keys for your system once, so copy them before you select "},{"t":"ui","v":"I have saved these values"},{"t":"text","v":". "},{"t":"ui","v":"Send test"},{"t":"text","v":" checks that results arrive."}]}],"headings":["Get access","Find your way around","Your team","Connect your applicant tracking system"],"text":"On the recruiter portal, your company sends assessments to candidates, reviews what they did, and records fair decisions. Edulexa never advances or turns down a candidate on its own. A person on your team always decides. Get access Create a free Edulexa account, or sign in.Open recruiter access. Fill in Company, Company website and Your job title, then select Send request.Edulexa checks every request before giving anyone access to candidates' information. Requests from a company e-mail address are approved faster. We e-mail you when it's decided.Once it's approved, sign out and sign in again, then select Open the recruiter portal. If a page says your recruiter account isn't connected to a company yet, sign out and sign in again. If that doesn't help, contact Edulexa support. Find your way around The menu at the top has four parts, in the order of the work: Candidates: the assessments you sent, where each candidate is, and your decisions.Review: Evidence packs, Work trials, Proctored sessions and Challenge results.Fairness: Appeals, Accommodations, Validity & bias audit and Transparency.Settings: Team and ATS connections. On a phone, select Menu to see every page. The bell at the top opens your notifications. Your team Open Team under Settings. It lists the recruiters at your company, each Joined or Invited. Everyone on the team sees the same candidates, reviews and settings. If you manage the team, your name shows Manages the team, and you can invite colleagues: Under Invite a colleague, fill in First name, Last name and Work e-mail.Select Send invitation. A new colleague gets an e-mail to set a password. Someone who already has an Edulexa account is added and told by e-mail.If an invitation got lost, select Resend. To withdraw an invitation or remove a colleague, select the bin button next to their name. Someone you remove is signed out. Only Edulexa can change the access of the people who manage the team. Connect your applicant tracking system If your company uses an applicant tracking system (ATS), such as Greenhouse, Lever or Workday, ATS connections lets you invite candidates from it and get their results back there. Results carry the reviewer's decision, if there is one, and a link to the evidence pack. They never carry an automatic verdict. Your IT team usually sets this up. Under New connection, they choose the Applicant tracking system, give the connection a Display name and enter what that system asks for. Then they select Create connection. Edulexa shows the keys for your system once, so copy them before you select I have saved these values. Send test checks that results arrive."},{"slug":"staff-getting-started","title":"Get started in the career center","summary":"What the career center can do in Edulexa, what each staff role can use, and where to start.","roles":["staff"],"group":"Getting started","features":["career-core"],"checked":"2026-11-11","order":5,"short":["Your home page shows your school, your role and a link to every page you can open.","Counselors work with students, employer relations staff work with employers, and career center admins do both and set the rules.","If you meet students, set your hours first. If you work with employers, start with their requests."],"blocks":[{"t":"p","c":[{"t":"text","v":"Your "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" home page shows your school's name, the role you're signed in as, how many people of each role your school has, and a "},{"t":"ui","v":"Go to"},{"t":"text","v":" list of every page you can open."}]},{"t":"p","c":[{"t":"text","v":"The menu at the top groups the pages:"}]},{"t":"ul","items":[[{"t":"ui","v":"Students"},{"t":"text","v":": appointments, "},{"t":"term","v":"caseload","key":"caseload"},{"t":"text","v":", "},{"t":"term","v":"document review","key":"document-review"},{"t":"text","v":", interview schedules, "},{"t":"term","v":"mentoring","key":"mentoring"},{"t":"text","v":" and messages."}],[{"t":"ui","v":"Employers and jobs"},{"t":"text","v":": employers, career fairs, internships, placements, "},{"t":"term","v":"campus drives","key":"campus-drive"},{"t":"text","v":" and the "},{"t":"term","v":"résumé book","key":"resume-book"},{"t":"text","v":"."}],[{"t":"ui","v":"Reports"},{"t":"text","v":": outcomes and reports."}],[{"t":"ui","v":"Setup"},{"t":"text","v":": people, your calendar connection, settings and more."}],[{"t":"ui","v":"Privacy"},{"t":"text","v":": privacy requests and the privacy log."}]]},{"t":"p","c":[{"t":"text","v":"The bell at the top opens your notifications. If you work at more than one school, choose the school at the top of the page."}]},{"t":"h2","c":[{"t":"text","v":"What each role can do"}]},{"t":"ul","items":[[{"t":"b","v":"Career center admins"},{"t":"text","v":" can do everything below. They also invite people, change the school's settings, and set the rules for each area, such as appointment types, caseload rules and drive rules."}],[{"t":"b","v":"Counselors"},{"t":"text","v":" handle appointments, their caseload, document review and messages, and review internships for credit. They can look at campus drives and interview schedules, but they don't approve employers, drives or schedules."}],[{"t":"b","v":"Employer relations"},{"t":"text","v":" staff approve employers, campus drives and interview schedules, look after the résumé book, answer messages, and see the employer report. Appointments, caseload and document review are for counselors and admins."}]]},{"t":"h2","c":[{"t":"text","v":"Where to start"}]},{"t":"ul","items":[[{"t":"b","v":"You meet students:"},{"t":"text","v":" set the hours students can book. See "},{"t":"link","v":"Set your availability and manage appointments","href":"/help/appointments-and-availability"},{"t":"text","v":"."}],[{"t":"b","v":"You work with employers:"},{"t":"text","v":" your home page shows how many "},{"t":"ui","v":"Employer requests"},{"t":"text","v":" are waiting. See "},{"t":"link","v":"Approve employers","href":"/help/employers-and-approvals"},{"t":"text","v":"."}],[{"t":"b","v":"You're an admin:"},{"t":"text","v":" invite your staff from "},{"t":"ui","v":"People"},{"t":"text","v":" and give each one the right role."}]]}],"headings":["What each role can do","Where to start"],"text":"Your career center home page shows your school's name, the role you're signed in as, how many people of each role your school has, and a Go to list of every page you can open. The menu at the top groups the pages: Students: appointments, caseload, document review, interview schedules, mentoring and messages.Employers and jobs: employers, career fairs, internships, placements, campus drives and the résumé book.Reports: outcomes and reports.Setup: people, your calendar connection, settings and more.Privacy: privacy requests and the privacy log. The bell at the top opens your notifications. If you work at more than one school, choose the school at the top of the page. What each role can do Career center admins can do everything below. They also invite people, change the school's settings, and set the rules for each area, such as appointment types, caseload rules and drive rules.Counselors handle appointments, their caseload, document review and messages, and review internships for credit. They can look at campus drives and interview schedules, but they don't approve employers, drives or schedules.Employer relations staff approve employers, campus drives and interview schedules, look after the résumé book, answer messages, and see the employer report. Appointments, caseload and document review are for counselors and admins. Where to start You meet students: set the hours students can book. See Set your availability and manage appointments.You work with employers: your home page shows how many Employer requests are waiting. See Approve employers.You're an admin: invite your staff from People and give each one the right role."},{"slug":"add-people","title":"Add people to your school","summary":"Invite teachers and career staff one by one, or import a student roster from a spreadsheet.","roles":["admin"],"group":"People and classes","features":["career-core"],"checked":"2026-11-11","order":10,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"Everyone at your school is on the "},{"t":"ui","v":"People"},{"t":"text","v":" page of the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":". You can search by name or e-mail, filter by role, change someone's role, or remove them."}]},{"t":"h2","c":[{"t":"text","v":"Invite one person"}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"People"},{"t":"text","v":" and find "},{"t":"ui","v":"Invite someone"},{"t":"text","v":"."}],[{"t":"text","v":"Enter their e-mail address and name."}],[{"t":"text","v":"Choose their role:"}]]},{"t":"ul","items":[[{"t":"ui","v":"Faculty"},{"t":"text","v":": teachers. They create classes and assessments and decide results."}],[{"t":"ui","v":"Counselor"},{"t":"text","v":": career staff who work with students."}],[{"t":"ui","v":"Career center admin"},{"t":"text","v":": school admins. They can do everything, including inviting people."}],[{"t":"ui","v":"Employer relations"},{"t":"text","v":": staff who work with employers."}],[{"t":"ui","v":"Student"}]]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Send invite"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Teachers and staff get an e-mail with where to sign in. Students added here aren't e-mailed: they hear about each assessment when a teacher gives it to their class."}]},{"t":"shot","name":"add-people-page","alt":"The Invite someone form on the People page, with the e-mail, name and role","w":1278,"h":509},{"t":"h2","c":[{"t":"text","v":"Import students from a spreadsheet"}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"Import student roster"},{"t":"text","v":", choose a spreadsheet saved as a CSV file."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Preview"},{"t":"text","v":". You see who would be added or updated, and any rows with problems."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Confirm import"},{"t":"text","v":". Rows with problems are skipped."}]]},{"t":"note","c":[{"t":"text","v":"Teachers usually import their own class lists instead, from the class page. See "},{"t":"link","v":"Create a class and import its roster","href":"/help/classes-and-rosters"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"People sign in with the e-mail address you entered. When they sign in for the first time, their account is linked to your school."}]}],"headings":["Invite one person","Import students from a spreadsheet"],"text":"Everyone at your school is on the People page of the career center. You can search by name or e-mail, filter by role, change someone's role, or remove them. Invite one person Open People and find Invite someone.Enter their e-mail address and name.Choose their role: Faculty: teachers. They create classes and assessments and decide results.Counselor: career staff who work with students.Career center admin: school admins. They can do everything, including inviting people.Employer relations: staff who work with employers.Student Select Send invite. Teachers and staff get an e-mail with where to sign in. Students added here aren't e-mailed: they hear about each assessment when a teacher gives it to their class. Import students from a spreadsheet Under Import student roster, choose a spreadsheet saved as a CSV file.Select Preview. You see who would be added or updated, and any rows with problems.Select Confirm import. Rows with problems are skipped. Teachers usually import their own class lists instead, from the class page. See Create a class and import its roster. People sign in with the e-mail address you entered. When they sign in for the first time, their account is linked to your school."},{"slug":"admissions-leads","title":"Work with your admissions leads","summary":"See who's waiting, contact a lead by call, e-mail, SMS or WhatsApp, book a meeting, schedule follow-ups, and move each lead through its stages.","roles":["admissions"],"group":"Leads","features":["admissions-crm"],"checked":"2026-11-12","order":10,"short":["The boxes at the top show today's work. Select one to see those leads.","Open a lead to call, e-mail or message them, book a meeting, add a note or schedule a follow-up. Everything is kept on the lead.","Move each lead from New to Enrolled or Lost. Follow-ups lists what's due for you."],"blocks":[{"t":"p","c":[{"t":"text","v":"A lead is a person who asked about your courses on Edulexa, asked you for career guidance, or sent the guidance form on your website. Open "},{"t":"link","v":"Admissions leads","href":"/institute/dashboard"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Today's work"}]},{"t":"p","c":[{"t":"text","v":"The boxes at the top show what needs you today: "},{"t":"ui","v":"New, not contacted"},{"t":"text","v":", "},{"t":"ui","v":"Replied, need your answer"},{"t":"text","v":", "},{"t":"ui","v":"Follow-ups overdue"},{"t":"text","v":", "},{"t":"ui","v":"Follow-ups due today"},{"t":"text","v":" and "},{"t":"ui","v":"My open leads"},{"t":"text","v":". Select a box to see those leads."}]},{"t":"p","c":[{"t":"text","v":"Below them are four tabs:"}]},{"t":"ul","items":[[{"t":"ui","v":"Leads"},{"t":"text","v":": every lead, as a table or a board."}],[{"t":"ui","v":"People"},{"t":"text","v":": one profile per person, with all their inquiries joined by e-mail address or phone number."}],[{"t":"ui","v":"Follow-ups"},{"t":"text","v":": the follow-ups due for you."}],[{"t":"ui","v":"Insights"},{"t":"text","v":": leads per week, your funnel, and leads by source, course and owner."}]]},{"t":"h2","c":[{"t":"text","v":"Find leads"}]},{"t":"p","c":[{"t":"text","v":"Choose "},{"t":"ui","v":"All leads"},{"t":"text","v":", "},{"t":"ui","v":"My leads"},{"t":"text","v":" or a quick view such as "},{"t":"ui","v":"Unassigned"},{"t":"text","v":", "},{"t":"ui","v":"High priority"},{"t":"text","v":" or "},{"t":"ui","v":"Possible spam"},{"t":"text","v":". Search by name, e-mail address, phone, course, source, tag or question. "},{"t":"ui","v":"Filters"},{"t":"text","v":" narrows the list further, and "},{"t":"ui","v":"Save this view"},{"t":"text","v":" keeps your choice for next time."}]},{"t":"p","c":[{"t":"ui","v":"Table"},{"t":"text","v":" shows a list you can "},{"t":"ui","v":"Sort"},{"t":"text","v":". "},{"t":"ui","v":"Board"},{"t":"text","v":" shows a column per stage: drag a lead to another stage. To change many leads at once, tick them, then use "},{"t":"ui","v":"Assign to…"},{"t":"text","v":", "},{"t":"ui","v":"Move to…"},{"t":"text","v":" or "},{"t":"ui","v":"Add tag"},{"t":"text","v":". "},{"t":"ui","v":"Export"},{"t":"text","v":" downloads the leads shown as a spreadsheet."}]},{"t":"h2","c":[{"t":"text","v":"Open a lead"}]},{"t":"p","c":[{"t":"text","v":"Select a lead to open it. At the top are their contact details and buttons for what you can do:"}]},{"t":"ul","items":[[{"t":"ui","v":"Log call"},{"t":"text","v":": record how the call went."}],[{"t":"ui","v":"Email"},{"t":"text","v":": write it yourself, start from a template, or let AI draft it. Send it now or later. Their reply comes back to the lead."}],[{"t":"ui","v":"WhatsApp"},{"t":"text","v":": opens WhatsApp with your message ready to send from your phone."}],[{"t":"ui","v":"SMS"},{"t":"text","v":": sends a text message, once your institute has connected SMS."}],[{"t":"ui","v":"Meeting"},{"t":"text","v":": book a time. They get the time and a calendar invite by e-mail."}],[{"t":"ui","v":"Note"},{"t":"text","v":": only your team sees notes."}]]},{"t":"p","c":[{"t":"text","v":"Every e-mail has a link to stop further contact. If the person uses it, the lead is marked "},{"t":"ui","v":"Do not contact"},{"t":"text","v":", and e-mail, SMS and WhatsApp are blocked."}]},{"t":"p","c":[{"t":"text","v":"Under the buttons, three tabs keep the history: "},{"t":"ui","v":"Communication"},{"t":"text","v":" (every call, message and note), "},{"t":"ui","v":"Follow-ups"},{"t":"text","v":" and "},{"t":"ui","v":"What they shared"},{"t":"text","v":" (their answers and results)."}]},{"t":"h2","c":[{"t":"text","v":"Stages, owners and follow-ups"}]},{"t":"p","c":[{"t":"text","v":"Each lead moves through stages: "},{"t":"ui","v":"New"},{"t":"text","v":", "},{"t":"ui","v":"Contacted"},{"t":"text","v":", "},{"t":"b","v":"Counseling booked"},{"t":"text","v":", "},{"t":"ui","v":"Applied"},{"t":"text","v":", "},{"t":"ui","v":"Enrolled"},{"t":"text","v":" or "},{"t":"ui","v":"Lost"},{"t":"text","v":". A lead moves to "},{"t":"ui","v":"Contacted"},{"t":"text","v":" on its own when you call, e-mail or message them. Select "},{"t":"ui","v":"Mark as lost"},{"t":"text","v":" to close a lead, and say why."}]},{"t":"p","c":[{"t":"text","v":"Choose the lead's "},{"t":"ui","v":"Owner"},{"t":"text","v":" from your team. Add "},{"t":"ui","v":"Tags"},{"t":"text","v":", such as \"scholarship\", and tick "},{"t":"ui","v":"High priority"},{"t":"text","v":" for the ones to call first."}]},{"t":"p","c":[{"t":"text","v":"To plan the next contact, open "},{"t":"ui","v":"Follow-ups"},{"t":"text","v":" on the lead, write "},{"t":"ui","v":"What needs doing"},{"t":"text","v":", pick the "},{"t":"ui","v":"Due time"},{"t":"text","v":" and "},{"t":"ui","v":"Who"},{"t":"text","v":", and select "},{"t":"ui","v":"Schedule"},{"t":"text","v":". That person gets an e-mail reminder when it's due."}]},{"t":"h2","c":[{"t":"text","v":"Leads that need a look"}]},{"t":"ul","items":[[{"t":"ui","v":"Possible spam"},{"t":"text","v":": kept out of your leads until you select "},{"t":"ui","v":"Not spam"},{"t":"text","v":"."}],[{"t":"ui","v":"Incomplete"},{"t":"text","v":": they started your website form and gave their contact details, but haven't sent it yet."}],[{"t":"ui","v":"Email not confirmed"},{"t":"text","v":": they haven't clicked the link in the confirmation e-mail yet, so the address may not be theirs."}],[{"t":"ui","v":"Duplicate"},{"t":"text","v":": the same e-mail address sent another inquiry. Check before you contact them twice."}]]},{"t":"note","c":[{"t":"text","v":"If the page says you're not on your institute's team list, no leads can be yours yet. Ask your admin to add you to the team in Admissions settings, with the e-mail you sign in with."}]}],"headings":["Today's work","Find leads","Open a lead","Stages, owners and follow-ups","Leads that need a look"],"text":"A lead is a person who asked about your courses on Edulexa, asked you for career guidance, or sent the guidance form on your website. Open Admissions leads. Today's work The boxes at the top show what needs you today: New, not contacted, Replied, need your answer, Follow-ups overdue, Follow-ups due today and My open leads. Select a box to see those leads. Below them are four tabs: Leads: every lead, as a table or a board.People: one profile per person, with all their inquiries joined by e-mail address or phone number.Follow-ups: the follow-ups due for you.Insights: leads per week, your funnel, and leads by source, course and owner. Find leads Choose All leads, My leads or a quick view such as Unassigned, High priority or Possible spam. Search by name, e-mail address, phone, course, source, tag or question. Filters narrows the list further, and Save this view keeps your choice for next time. Table shows a list you can Sort. Board shows a column per stage: drag a lead to another stage. To change many leads at once, tick them, then use Assign to…, Move to… or Add tag. Export downloads the leads shown as a spreadsheet. Open a lead Select a lead to open it. At the top are their contact details and buttons for what you can do: Log call: record how the call went.Email: write it yourself, start from a template, or let AI draft it. Send it now or later. Their reply comes back to the lead.WhatsApp: opens WhatsApp with your message ready to send from your phone.SMS: sends a text message, once your institute has connected SMS.Meeting: book a time. They get the time and a calendar invite by e-mail.Note: only your team sees notes. Every e-mail has a link to stop further contact. If the person uses it, the lead is marked Do not contact, and e-mail, SMS and WhatsApp are blocked. Under the buttons, three tabs keep the history: Communication (every call, message and note), Follow-ups and What they shared (their answers and results). Stages, owners and follow-ups Each lead moves through stages: New, Contacted, Counseling booked, Applied, Enrolled or Lost. A lead moves to Contacted on its own when you call, e-mail or message them. Select Mark as lost to close a lead, and say why. Choose the lead's Owner from your team. Add Tags, such as \"scholarship\", and tick High priority for the ones to call first. To plan the next contact, open Follow-ups on the lead, write What needs doing, pick the Due time and Who, and select Schedule. That person gets an e-mail reminder when it's due. Leads that need a look Possible spam: kept out of your leads until you select Not spam.Incomplete: they started your website form and gave their contact details, but haven't sent it yet.Email not confirmed: they haven't clicked the link in the confirmation e-mail yet, so the address may not be theirs.Duplicate: the same e-mail address sent another inquiry. Check before you contact them twice. If the page says you're not on your institute's team list, no leads can be yours yet. Ask your admin to add you to the team in Admissions settings, with the e-mail you sign in with."},{"slug":"advisor-desk","title":"Answer guidance requests as an Edulexa advisor","summary":"Reply to people who asked Edulexa for career guidance, hand a request to a community mentor, suggest an institute, and change Edulexa's questions.","roles":["mentor"],"group":"Guidance requests","features":["guidance-desk","guidance-forms"],"checked":"2026-11-12","order":10,"short":["In Guidance requests, choose a request, read what the person shared, and reply. They get it in Edulexa and by e-mail.","Busy? Hand it to a community mentor. Or suggest an institute: nothing is sent to it unless the person approves.","Select Mark resolved when you're done."],"blocks":[{"t":"p","c":[{"t":"text","v":"People who don't know which institute to ask, or which area or certification to choose, can send their question to Edulexa. As an Edulexa advisor, you answer them on "},{"t":"link","v":"Guidance requests","href":"/advisor/guidance"},{"t":"text","v":". New requests, replies and hand-backs also come to the advisors by e-mail."}]},{"t":"h2","c":[{"t":"text","v":"Find a request"}]},{"t":"p","c":[{"t":"text","v":"The list opens on "},{"t":"ui","v":"Waiting for an advisor"},{"t":"text","v":". Use the list above the requests to show "},{"t":"ui","v":"All"},{"t":"text","v":" or another status: "},{"t":"ui","v":"With a mentor"},{"t":"text","v":", "},{"t":"ui","v":"Answered"},{"t":"text","v":", "},{"t":"ui","v":"Institute suggested"},{"t":"text","v":", "},{"t":"ui","v":"Sent to an institute"},{"t":"text","v":" or "},{"t":"ui","v":"Resolved"},{"t":"text","v":". Choose a request to open it."}]},{"t":"p","c":[{"t":"text","v":"Each request shows the person's contact details, "},{"t":"ui","v":"What they're unsure about:"},{"t":"text","v":", their answers and any files they attached, and their counseling quiz result if they chose to share it."}]},{"t":"h2","c":[{"t":"text","v":"Reply"}]},{"t":"p","c":[{"t":"text","v":"Write your reply and select "},{"t":"ui","v":"Send"},{"t":"text","v":". The person gets it in Edulexa and by e-mail. If the request says reply-by-email isn't set up, people answer on their own page in Edulexa instead."}]},{"t":"p","c":[{"t":"text","v":"To leave a message for the other advisors and the "},{"t":"term","v":"mentor","key":"mentoring"},{"t":"text","v":" only, tick "},{"t":"ui","v":"Note for staff only (the person doesn't see it)"},{"t":"text","v":", then select "},{"t":"ui","v":"Add note"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Hand it to a community mentor"}]},{"t":"p","c":[{"t":"text","v":"When you're stretched, choose a mentor under "},{"t":"ui","v":"Hand to a community mentor"},{"t":"text","v":" and select "},{"t":"ui","v":"Hand over"},{"t":"text","v":". Only approved community mentors who have signed in are listed. The mentor gets a notification and an e-mail, and replies in Edulexa or by e-mail. See "},{"t":"link","v":"Guidance requests handed to you","href":"/help/guidance-requests-for-you"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"To answer it yourself again, select "},{"t":"ui","v":"Take back"},{"t":"text","v":". If the mentor hands it back, it's waiting for an advisor again."}]},{"t":"h2","c":[{"t":"text","v":"Suggest an institute"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Suggest an institute"},{"t":"text","v":", choose one of the institutes listed on Edulexa, add "},{"t":"ui","v":"Why this institute (optional)"},{"t":"text","v":", and select "},{"t":"ui","v":"Suggest"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"The person decides. They're asked by e-mail and on their own page, and nothing is sent to the institute unless they approve. If they approve, the request shows "},{"t":"ui","v":"Sent to an institute"},{"t":"text","v":" and the institute contacts them. If they decline, it's waiting for an advisor again."}]},{"t":"h2","c":[{"t":"text","v":"Finish"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Mark resolved"},{"t":"text","v":" when the person has what they need. "},{"t":"ui","v":"Reopen"},{"t":"text","v":" brings it back."}]},{"t":"h2","c":[{"t":"text","v":"Edulexa's questions"}]},{"t":"p","c":[{"t":"link","v":"Edulexa's forms","href":"/advisor/questions"},{"t":"text","v":" holds the questions people answer when they ask Edulexa for guidance. You change them the same way an institute changes its own forms: see "},{"t":"link","v":"Build your guidance forms","href":"/help/guidance-forms"},{"t":"text","v":"."}]}],"headings":["Find a request","Reply","Hand it to a community mentor","Suggest an institute","Finish","Edulexa's questions"],"text":"People who don't know which institute to ask, or which area or certification to choose, can send their question to Edulexa. As an Edulexa advisor, you answer them on Guidance requests. New requests, replies and hand-backs also come to the advisors by e-mail. Find a request The list opens on Waiting for an advisor. Use the list above the requests to show All or another status: With a mentor, Answered, Institute suggested, Sent to an institute or Resolved. Choose a request to open it. Each request shows the person's contact details, What they're unsure about:, their answers and any files they attached, and their counseling quiz result if they chose to share it. Reply Write your reply and select Send. The person gets it in Edulexa and by e-mail. If the request says reply-by-email isn't set up, people answer on their own page in Edulexa instead. To leave a message for the other advisors and the mentor only, tick Note for staff only (the person doesn't see it), then select Add note. Hand it to a community mentor When you're stretched, choose a mentor under Hand to a community mentor and select Hand over. Only approved community mentors who have signed in are listed. The mentor gets a notification and an e-mail, and replies in Edulexa or by e-mail. See Guidance requests handed to you. To answer it yourself again, select Take back. If the mentor hands it back, it's waiting for an advisor again. Suggest an institute Under Suggest an institute, choose one of the institutes listed on Edulexa, add Why this institute (optional), and select Suggest. The person decides. They're asked by e-mail and on their own page, and nothing is sent to the institute unless they approve. If they approve, the request shows Sent to an institute and the institute contacts them. If they decline, it's waiting for an advisor again. Finish Select Mark resolved when the person has what they need. Reopen brings it back. Edulexa's questions Edulexa's forms holds the questions people answer when they ask Edulexa for guidance. You change them the same way an institute changes its own forms: see Build your guidance forms."},{"slug":"appointments","title":"Book an appointment with the career center","summary":"Book a time with a career counselor, join a drop-in line or a group session, and move or cancel a booking.","roles":["student","alumni"],"group":"Career help","features":["appointments"],"checked":"2026-11-11","order":10,"short":["Open Appointments, select Book, choose what you need help with, then pick an open time.","To change it, find it under My appointments and select Reschedule or Cancel.","Too close to the start to change it? Contact the career center."],"blocks":[{"t":"p","c":[{"t":"text","v":"Open "},{"t":"link","v":"Appointments","href":"/student/appointments"},{"t":"text","v":" from the menu."}]},{"t":"h2","c":[{"t":"text","v":"Book a time"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Book"},{"t":"text","v":"."}],[{"t":"text","v":"Choose what you need help with. Each choice shows how long it takes and how you can meet: in person, by video or by phone."}],[{"t":"text","v":"Pick a "},{"t":"ui","v":"Counselor"},{"t":"text","v":", or leave "},{"t":"ui","v":"Any available counselor"},{"t":"text","v":". Choose "},{"t":"ui","v":"How would you like to meet?"},{"t":"text","v":"."}],[{"t":"text","v":"Pick a day and one of its open times. Only times when a counselor is free are shown. Use "},{"t":"ui","v":"Next two weeks"},{"t":"text","v":" to look further ahead."}],[{"t":"text","v":"Answer any questions the career center asks, then select "},{"t":"ui","v":"Book appointment"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"You get a confirmation, and the appointment shows under "},{"t":"ui","v":"My appointments"},{"t":"text","v":". Select "},{"t":"ui","v":"Add to calendar"},{"t":"text","v":" to save it in your own calendar. Under the times, the page says how far ahead you can book and how late you can still change it online."}]},{"t":"h2","c":[{"t":"text","v":"If you can't make it"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"My appointments"},{"t":"text","v":":"}]},{"t":"ul","items":[[{"t":"b","v":"Move it:"},{"t":"text","v":" select "},{"t":"ui","v":"Reschedule"},{"t":"text","v":", pick another time with the same counselor, then select "},{"t":"ui","v":"Move appointment"},{"t":"text","v":"."}],[{"t":"b","v":"Cancel it:"},{"t":"text","v":" select "},{"t":"ui","v":"Cancel"},{"t":"text","v":", say why (your counselor sees this), then select "},{"t":"ui","v":"Cancel appointment"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Close to the start, these buttons go away. Contact the career center instead."}]},{"t":"h2","c":[{"t":"text","v":"Drop-in hours and group sessions"}]},{"t":"ul","items":[[{"t":"ui","v":"Drop-in"},{"t":"text","v":": when drop-in hours are open, select "},{"t":"ui","v":"Join the line"},{"t":"text","v":". You see your place in line and about how long you'll wait. You can "},{"t":"ui","v":"Leave the line"},{"t":"text","v":"."}],[{"t":"ui","v":"Group sessions"},{"t":"text","v":": workshops and group advising. Select "},{"t":"ui","v":"Register"},{"t":"text","v":". If a session is full, select "},{"t":"ui","v":"Join the waitlist"},{"t":"text","v":": you're registered automatically when a seat opens."}]]},{"t":"h2","c":[{"t":"text","v":"After the meeting"}]},{"t":"p","c":[{"t":"text","v":"Notes your counselor shares and the tasks you agreed on are under "},{"t":"ui","v":"Notes & tasks"},{"t":"text","v":". Tick your tasks off as you finish them."}]},{"t":"note","c":[{"t":"text","v":"Some appointments and sessions are only for students, or only for alumni, so you may see different choices from a friend."}]}],"headings":["Book a time","If you can't make it","Drop-in hours and group sessions","After the meeting"],"text":"Open Appointments from the menu. Book a time Select Book.Choose what you need help with. Each choice shows how long it takes and how you can meet: in person, by video or by phone.Pick a Counselor, or leave Any available counselor. Choose How would you like to meet?.Pick a day and one of its open times. Only times when a counselor is free are shown. Use Next two weeks to look further ahead.Answer any questions the career center asks, then select Book appointment. You get a confirmation, and the appointment shows under My appointments. Select Add to calendar to save it in your own calendar. Under the times, the page says how far ahead you can book and how late you can still change it online. If you can't make it Under My appointments: Move it: select Reschedule, pick another time with the same counselor, then select Move appointment.Cancel it: select Cancel, say why (your counselor sees this), then select Cancel appointment. Close to the start, these buttons go away. Contact the career center instead. Drop-in hours and group sessions Drop-in: when drop-in hours are open, select Join the line. You see your place in line and about how long you'll wait. You can Leave the line.Group sessions: workshops and group advising. Select Register. If a session is full, select Join the waitlist: you're registered automatically when a seat opens. After the meeting Notes your counselor shares and the tasks you agreed on are under Notes & tasks. Tick your tasks off as you finish them. Some appointments and sessions are only for students, or only for alumni, so you may see different choices from a friend."},{"slug":"appointments-and-availability","title":"Set your availability and manage appointments","summary":"Set the hours students can book, see your schedule, book for a student, and record what happened after a meeting.","roles":["staff"],"group":"Students and appointments","features":["appointments","calendar-sync"],"checked":"2026-11-11","order":10,"short":["In Appointments, open Availability, fill in your booking profile, tick \"Students can book me\" and add your weekly hours.","Students book an open time themselves. Your bookings show under Schedule.","Open an appointment to record attendance, add notes and set follow-up tasks."],"blocks":[{"t":"p","c":[{"t":"text","v":"Appointments are for counselors and "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" admins. Open "},{"t":"ui","v":"Appointments"},{"t":"text","v":" from the "},{"t":"ui","v":"Students"},{"t":"text","v":" menu."}]},{"t":"h2","c":[{"t":"text","v":"Set when students can book you"}]},{"t":"ol","items":[[{"t":"text","v":"Open the "},{"t":"ui","v":"Availability"},{"t":"text","v":" tab."}],[{"t":"text","v":"In "},{"t":"ui","v":"My booking profile"},{"t":"text","v":", fill in the "},{"t":"ui","v":"Name students see"},{"t":"text","v":", your "},{"t":"ui","v":"Video meeting link"},{"t":"text","v":" and your "},{"t":"ui","v":"In-person location"},{"t":"text","v":". Tick the "},{"t":"ui","v":"Appointment types offered"},{"t":"text","v":" you take, and tick "},{"t":"ui","v":"Students can book me"},{"t":"text","v":". Select "},{"t":"ui","v":"Save profile"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Weekly hours"},{"t":"text","v":", select "},{"t":"ui","v":"Add hours"},{"t":"text","v":" for each block of time, then "},{"t":"ui","v":"Save weekly hours"},{"t":"text","v":". Students can't book you until you add hours."}],[{"t":"text","v":"For a day off or a one-off extra block, use "},{"t":"ui","v":"Time off and extra hours"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Times are in your school's time zone. Career admins can pick any counselor at the top of the tab and change their hours. Admins also create the kinds of appointments students can book, under "},{"t":"ui","v":"Appointment types"},{"t":"text","v":"."}]},{"t":"shot","name":"staff-availability","alt":"The weekly hours on the Availability tab of Appointments, with the Save weekly hours button","w":912,"h":471},{"t":"h2","c":[{"t":"text","v":"Your schedule"}]},{"t":"p","c":[{"t":"text","v":"Students book an open time themselves, so there's nothing to accept. The "},{"t":"ui","v":"Schedule"},{"t":"text","v":" tab shows what's booked, for one day or seven days, for you or for all counselors. To book on a student's behalf, select "},{"t":"ui","v":"Book for a student"},{"t":"text","v":", find the student, choose a type and a time, and select "},{"t":"ui","v":"Book appointment"},{"t":"text","v":". The student is told."}]},{"t":"h2","c":[{"t":"text","v":"After the meeting"}]},{"t":"p","c":[{"t":"text","v":"Open an appointment to:"}]},{"t":"ul","items":[[{"t":"text","v":"Record "},{"t":"ui","v":"Attended"},{"t":"text","v":", "},{"t":"ui","v":"No-show"},{"t":"text","v":" or "},{"t":"ui","v":"Late cancellation"},{"t":"text","v":", once it has started."}],[{"t":"text","v":"Add "},{"t":"ui","v":"Advising notes"},{"t":"text","v":". Choose "},{"t":"ui","v":"Career staff only"},{"t":"text","v":" or "},{"t":"ui","v":"Also the student"},{"t":"text","v":". Notes are never shared with employers."}],[{"t":"text","v":"Add "},{"t":"ui","v":"Follow-up tasks"},{"t":"text","v":" for the student or for you, with a due date."}],[{"t":"ui","v":"Cancel appointment"},{"t":"text","v":", with a reason the student receives."}]]},{"t":"h2","c":[{"t":"text","v":"See bookings in your own calendar"}]},{"t":"p","c":[{"t":"text","v":"Copy the link under "},{"t":"ui","v":"Private calendar feed"},{"t":"text","v":" into Outlook, Google or Apple Calendar. Keep it private: anyone with it can see students' names. Or connect your work calendar in "},{"t":"ui","v":"Calendar connection"},{"t":"text","v":". Depending on your school's choices, busy times in it aren't offered to students, and your bookings are added to it."}]}],"headings":["Set when students can book you","Your schedule","After the meeting","See bookings in your own calendar"],"text":"Appointments are for counselors and career center admins. Open Appointments from the Students menu. Set when students can book you Open the Availability tab.In My booking profile, fill in the Name students see, your Video meeting link and your In-person location. Tick the Appointment types offered you take, and tick Students can book me. Select Save profile.Under Weekly hours, select Add hours for each block of time, then Save weekly hours. Students can't book you until you add hours.For a day off or a one-off extra block, use Time off and extra hours. Times are in your school's time zone. Career admins can pick any counselor at the top of the tab and change their hours. Admins also create the kinds of appointments students can book, under Appointment types. Your schedule Students book an open time themselves, so there's nothing to accept. The Schedule tab shows what's booked, for one day or seven days, for you or for all counselors. To book on a student's behalf, select Book for a student, find the student, choose a type and a time, and select Book appointment. The student is told. After the meeting Open an appointment to: Record Attended, No-show or Late cancellation, once it has started.Add Advising notes. Choose Career staff only or Also the student. Notes are never shared with employers.Add Follow-up tasks for the student or for you, with a due date.Cancel appointment, with a reason the student receives. See bookings in your own calendar Copy the link under Private calendar feed into Outlook, Google or Apple Calendar. Keep it private: anyone with it can see students' names. Or connect your work calendar in Calendar connection. Depending on your school's choices, busy times in it aren't offered to students, and your bookings are added to it."},{"slug":"be-a-mentor","title":"Be a mentor","summary":"Volunteer as a mentor for your school's students or in the Edulexa community, answer requests, and look after your mentees.","roles":["alumni","mentor"],"group":"Mentoring","features":["mentoring"],"checked":"2026-11-12","order":10,"short":["Set up your mentor profile and select Submit for approval. You're listed once it's approved.","Accept or decline each request. Contact details are shared only once you both accept.","Message your mentee, log your sessions, then mark the mentorship completed and leave feedback."],"blocks":[{"t":"p","c":[{"t":"term","v":"Mentors","key":"mentoring"},{"t":"text","v":" are volunteers. You choose your topics, how you meet and how many mentees you take. Mentoring on Edulexa is free."}]},{"t":"h2","c":[{"t":"text","v":"Where to start"}]},{"t":"ul","items":[[{"t":"b","v":"Alumni of a school:"},{"t":"text","v":" on your "},{"t":"link","v":"alumni home page","href":"/alumni"},{"t":"text","v":", select "},{"t":"ui","v":"Become a mentor"},{"t":"text","v":"."}],[{"t":"b","v":"The Edulexa community:"},{"t":"text","v":" open "},{"t":"link","v":"Mentoring","href":"/mentors"},{"t":"text","v":" and select "},{"t":"ui","v":"Apply to mentor"},{"t":"text","v":". You need a verified e-mail address first, because mentors and mentees reach each other by e-mail."}]]},{"t":"p","c":[{"t":"text","v":"Both open your mentor page, with "},{"t":"ui","v":"Set up your mentor profile"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Set up your profile"}]},{"t":"ol","items":[[{"t":"text","v":"Fill in your "},{"t":"ui","v":"Headline"},{"t":"text","v":", one line on how you can help, and your "},{"t":"ui","v":"Employer"},{"t":"text","v":", "},{"t":"ui","v":"Job title"},{"t":"text","v":" and "},{"t":"ui","v":"Industry"},{"t":"text","v":"."}],[{"t":"text","v":"Choose the "},{"t":"ui","v":"Topics you can help with"},{"t":"text","v":" and "},{"t":"ui","v":"How you can meet"},{"t":"text","v":" (video call, phone, in person or e-mail). You need at least one of each."}],[{"t":"text","v":"Set your "},{"t":"ui","v":"Maximum active mentees"},{"t":"text","v":", from 1 to 10. No one can ask you once you're full."}],[{"t":"text","v":"Add a "},{"t":"ui","v":"Contact email for mentees"},{"t":"text","v":" if you don't want to use your sign-in e-mail. It's shared only with mentees whose mentorship is active."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Save profile"},{"t":"text","v":", then "},{"t":"ui","v":"Submit for approval"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Your status shows at the top. Your school's "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" reviews alumni mentors; in the Edulexa community, the Edulexa team reviews mentors, and your page says so. In the community, the Edulexa team also does what a career center does elsewhere in this guide. Once approved, your status is "},{"t":"ui","v":"Listed"},{"t":"text","v":" and people can find you. If the reviewer asks for changes, the status is "},{"t":"ui","v":"Changes requested"},{"t":"text","v":": update your profile and submit it again."}]},{"t":"p","c":[{"t":"text","v":"Need a break? Select "},{"t":"ui","v":"Pause new requests"},{"t":"text","v":". Your current mentees aren't affected. Select "},{"t":"ui","v":"Resume new requests"},{"t":"text","v":" when you're ready."}]},{"t":"h2","c":[{"t":"text","v":"Answer requests"}]},{"t":"p","c":[{"t":"text","v":"Each request under "},{"t":"ui","v":"Requests"},{"t":"text","v":" shows the person's message, their goals, and what you have in common. Add a note if you like ("},{"t":"ui","v":"Note to the student (optional)"},{"t":"text","v":" at a school, "},{"t":"ui","v":"Note to your mentee (optional)"},{"t":"text","v":" in the Edulexa community), then select "},{"t":"b","v":"Accept"},{"t":"text","v":" or "},{"t":"b","v":"Decline"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"When you accept, the mentorship becomes "},{"t":"ui","v":"Active"},{"t":"text","v":" and you both see each other's contact details. At some schools the career center confirms each match first, so it shows "},{"t":"ui","v":"Waiting for career center"},{"t":"text","v":" until they do."}]},{"t":"h2","c":[{"t":"text","v":"Look after your mentees"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Your mentees"},{"t":"text","v":", choose a mentee to open the mentorship. There you can:"}]},{"t":"ul","items":[[{"t":"text","v":"send private messages. The career center reads them only if one of you reports a problem;"}],[{"t":"ui","v":"Log a session"},{"t":"text","v":" after you meet. "},{"t":"ui","v":"Private notes (only the two of you)"},{"t":"text","v":" stay between you; a "},{"t":"ui","v":"Summary for the career center (optional)"},{"t":"text","v":" is shared with them;"}],[{"t":"text","v":"see the mentee's goals. Only the mentee changes them."}]]},{"t":"p","c":[{"t":"text","v":"If no session has been logged for a while, the mentorship shows "},{"t":"ui","v":"Check-in due"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"When you're done, select "},{"t":"ui","v":"Mark completed"},{"t":"text","v":", or "},{"t":"ui","v":"End early"},{"t":"text","v":". Then leave a rating and select "},{"t":"ui","v":"Send feedback"},{"t":"text","v":". Only the career center sees it, not your mentee."}]},{"t":"note","c":[{"t":"text","v":"If something feels wrong, select "},{"t":"ui","v":"Report a problem"},{"t":"text","v":". You can also block the person, which ends the mentorship."}]},{"t":"p","c":[{"t":"text","v":"Edulexa advisors may also hand you career questions from people who aren't sure what to study. See "},{"t":"link","v":"Guidance requests handed to you","href":"/help/guidance-requests-for-you"},{"t":"text","v":"."}]}],"headings":["Where to start","Set up your profile","Answer requests","Look after your mentees"],"text":"Mentors are volunteers. You choose your topics, how you meet and how many mentees you take. Mentoring on Edulexa is free. Where to start Alumni of a school: on your alumni home page, select Become a mentor.The Edulexa community: open Mentoring and select Apply to mentor. You need a verified e-mail address first, because mentors and mentees reach each other by e-mail. Both open your mentor page, with Set up your mentor profile. Set up your profile Fill in your Headline, one line on how you can help, and your Employer, Job title and Industry.Choose the Topics you can help with and How you can meet (video call, phone, in person or e-mail). You need at least one of each.Set your Maximum active mentees, from 1 to 10. No one can ask you once you're full.Add a Contact email for mentees if you don't want to use your sign-in e-mail. It's shared only with mentees whose mentorship is active.Select Save profile, then Submit for approval. Your status shows at the top. Your school's career center reviews alumni mentors; in the Edulexa community, the Edulexa team reviews mentors, and your page says so. In the community, the Edulexa team also does what a career center does elsewhere in this guide. Once approved, your status is Listed and people can find you. If the reviewer asks for changes, the status is Changes requested: update your profile and submit it again. Need a break? Select Pause new requests. Your current mentees aren't affected. Select Resume new requests when you're ready. Answer requests Each request under Requests shows the person's message, their goals, and what you have in common. Add a note if you like (Note to the student (optional) at a school, Note to your mentee (optional) in the Edulexa community), then select Accept or Decline. When you accept, the mentorship becomes Active and you both see each other's contact details. At some schools the career center confirms each match first, so it shows Waiting for career center until they do. Look after your mentees Under Your mentees, choose a mentee to open the mentorship. There you can: send private messages. The career center reads them only if one of you reports a problem;Log a session after you meet. Private notes (only the two of you) stay between you; a Summary for the career center (optional) is shared with them;see the mentee's goals. Only the mentee changes them. If no session has been logged for a while, the mentorship shows Check-in due. When you're done, select Mark completed, or End early. Then leave a rating and select Send feedback. Only the career center sees it, not your mentee. If something feels wrong, select Report a problem. You can also block the person, which ends the mentorship. Edulexa advisors may also hand you career questions from people who aren't sure what to study. See Guidance requests handed to you."},{"slug":"career-direction","title":"Find your direction","summary":"Take the career quiz, see your career path, and find courses for the skills you want to strengthen.","roles":["member"],"group":"Guidance","features":["counselling-quiz","career-path","course-referrals"],"checked":"2026-11-12","order":10,"short":["The career quiz asks what you enjoy and how you like to work, then shows the area of tech your answers point to.","Career path puts your quiz result, target role and graded skills together, with what to learn next.","Recommendations suggests courses after a voice defense. Nothing is shared unless you choose to."],"blocks":[{"t":"h2","c":[{"t":"text","v":"The career quiz"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Counseling quiz"},{"t":"text","v":" from the "},{"t":"ui","v":"Guidance"},{"t":"text","v":" menu."}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Start the quiz"},{"t":"text","v":". The page says how many questions there are and about how long it takes. There are no right or wrong answers, and you don't need any experience."}],[{"t":"text","v":"Answer each question, then select "},{"t":"ui","v":"Next"},{"t":"text","v":". Use "},{"t":"ui","v":"Back"},{"t":"text","v":" to change an answer."}],[{"t":"text","v":"On the last question, select "},{"t":"ui","v":"See my result"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Need a break? Select "},{"t":"ui","v":"Leave (your answers are kept)"},{"t":"text","v":", and later "},{"t":"ui","v":"Continue where you left off"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Your result names the area of tech that suits you, and often a second one. "},{"t":"ui","v":"How your answers split"},{"t":"text","v":" shows how often you picked each area, and "},{"t":"ui","v":"Why this result"},{"t":"text","v":" lists the answers that led there. You also see "},{"t":"ui","v":"Roles people start in"},{"t":"text","v":" and "},{"t":"ui","v":"Good things to learn first"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Your result is saved. You can take the quiz again after the time the page shows."}]},{"t":"h3","c":[{"t":"text","v":"Courses that fit"}]},{"t":"p","c":[{"t":"text","v":"If institutes have listed courses in your area, they show under "},{"t":"ui","v":"Courses that fit"},{"t":"text","v":". To ask about one, select the button that asks that institute about it, check what will be sent, and select "},{"t":"ui","v":"Send inquiry"},{"t":"text","v":". Nothing goes to an institute until you send it."}]},{"t":"h2","c":[{"t":"text","v":"Your career path"}]},{"t":"p","c":[{"t":"ui","v":"Career path"},{"t":"text","v":" brings it together:"}]},{"t":"ul","items":[[{"t":"ui","v":"Target role"},{"t":"text","v":": the job you're aiming for. Select "},{"t":"ui","v":"Set it in your skill passport"},{"t":"text","v":" to set it."}],[{"t":"ui","v":"Area that suits you"},{"t":"text","v":": your career quiz result."}],[{"t":"ui","v":"Your skills"},{"t":"text","v":": your best graded result in each area. Once you have an area, you also see good things to learn next."}],[{"t":"ui","v":"Next steps"},{"t":"text","v":": what to do now."}],[{"t":"ui","v":"Salary data"},{"t":"text","v":": shown only from a named, licensed source. Edulexa doesn't predict salaries or promotions."}]]},{"t":"h2","c":[{"t":"text","v":"Course suggestions"}]},{"t":"p","c":[{"t":"text","v":"After a "},{"t":"term","v":"voice defense","key":"voice-defense"},{"t":"text","v":", "},{"t":"ui","v":"Recommendations"},{"t":"text","v":" suggests courses for the skills it said to strengthen. Partner courses are sponsored, and the page says so."}]},{"t":"p","c":[{"t":"text","v":"To hear from a course provider, select the course's button to share your details, then "},{"t":"ui","v":"Share my details"},{"t":"text","v":". They get your name, your e-mail address and the skills to improve, never your scores, transcripts or recordings. Under "},{"t":"ui","v":"Details you've shared"},{"t":"text","v":", select "},{"t":"ui","v":"Withdraw"},{"t":"text","v":" at any time: the provider is asked to stop contacting you and delete your details."}]},{"t":"p","c":[{"t":"text","v":"Next step: start practicing. See "},{"t":"link","v":"Daily drills and practice","href":"/help/daily-practice"},{"t":"text","v":"."}]}],"headings":["The career quiz","Courses that fit","Your career path","Course suggestions"],"text":"The career quiz Open Counseling quiz from the Guidance menu. Select Start the quiz. The page says how many questions there are and about how long it takes. There are no right or wrong answers, and you don't need any experience.Answer each question, then select Next. Use Back to change an answer.On the last question, select See my result. Need a break? Select Leave (your answers are kept), and later Continue where you left off. Your result names the area of tech that suits you, and often a second one. How your answers split shows how often you picked each area, and Why this result lists the answers that led there. You also see Roles people start in and Good things to learn first. Your result is saved. You can take the quiz again after the time the page shows. Courses that fit If institutes have listed courses in your area, they show under Courses that fit. To ask about one, select the button that asks that institute about it, check what will be sent, and select Send inquiry. Nothing goes to an institute until you send it. Your career path Career path brings it together: Target role: the job you're aiming for. Select Set it in your skill passport to set it.Area that suits you: your career quiz result.Your skills: your best graded result in each area. Once you have an area, you also see good things to learn next.Next steps: what to do now.Salary data: shown only from a named, licensed source. Edulexa doesn't predict salaries or promotions. Course suggestions After a voice defense, Recommendations suggests courses for the skills it said to strengthen. Partner courses are sponsored, and the page says so. To hear from a course provider, select the course's button to share your details, then Share my details. They get your name, your e-mail address and the skills to improve, never your scores, transcripts or recordings. Under Details you've shared, select Withdraw at any time: the provider is asked to stop contacting you and delete your details. Next step: start practicing. See Daily drills and practice."},{"slug":"credentials-and-passport","title":"Your credentials and skill passport","summary":"What your credentials and skill passport are, how to share them, and how others check they're real.","roles":["student","alumni"],"group":"Your credentials","features":["credentials","skill-passport"],"checked":"2026-11-11","order":10,"short":["Credentials holds the signed proof of what you passed. Select Share to give someone a link.","Your skill passport sums up your skills and credentials. Turn sharing on to give out its link.","Anyone can check a credential is real from its Verify link."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Your credentials"}]},{"t":"p","c":[{"t":"text","v":"When you pass an assessment that issues credentials, a signed credential is added to "},{"t":"link","v":"Credentials","href":"/credentials"},{"t":"text","v":". Signed means Edulexa vouches for it: anyone can check that it's real and unchanged. Each shows your scores and until when it's valid; class assessment results don't expire."}]},{"t":"p","c":[{"t":"text","v":"To share one:"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Share"},{"t":"text","v":"."}],[{"t":"text","v":"Say who it's for (only you see this), tick the "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" to include, and choose when the link expires, from 1 to 90 days."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Create link"},{"t":"text","v":", then "},{"t":"ui","v":"Copy link"},{"t":"text","v":". The link is shown only once, but you can always create another."}]]},{"t":"p","c":[{"t":"text","v":"Anyone with the link sees the signed results and the evidence you ticked. Under each credential, the share links list shows each link and how often it was opened. Select "},{"t":"ui","v":"Revoke"},{"t":"text","v":" to stop one working."}]},{"t":"note","c":[{"t":"text","v":"Revoking a whole credential can't be undone: all its links stop working, and anyone who checks it sees it was revoked."}]},{"t":"h2","c":[{"t":"text","v":"Your skill passport"}]},{"t":"p","c":[{"t":"text","v":"Your "},{"t":"link","v":"Skill passport","href":"/passport"},{"t":"text","v":" is your record of skills and credentials, built from your graded results. Each skill shows your best result. "},{"t":"ui","v":"Verified"},{"t":"text","v":" means a credential backs it."}]},{"t":"shot","name":"passport-sharing","alt":"The skill passport's Sharing panel, with the switch that turns the share link on or off","w":592,"h":771},{"t":"p","c":[{"t":"text","v":"To share it, switch sharing on so it says "},{"t":"ui","v":"Sharing is on"},{"t":"text","v":", then select "},{"t":"ui","v":"Copy"},{"t":"text","v":". Anyone with the link sees your name, target role, skills and credentials, never your email or your activity. Under "},{"t":"ui","v":"How you appear"},{"t":"text","v":", set the name and target role it shows."}]},{"t":"p","c":[{"t":"text","v":"Shared it too widely? Select "},{"t":"ui","v":"Create a new link (the old one stops working)"},{"t":"text","v":", or switch sharing off."}]},{"t":"h2","c":[{"t":"text","v":"How others check"}]},{"t":"p","c":[{"t":"text","v":"Each credential in your passport has a "},{"t":"ui","v":"Verify"},{"t":"text","v":" link to its public page, which shows that it's genuine, or that it was revoked. Your credentials and passport stay in your account after you graduate."}]}],"headings":["Your credentials","Your skill passport","How others check"],"text":"Your credentials When you pass an assessment that issues credentials, a signed credential is added to Credentials. Signed means Edulexa vouches for it: anyone can check that it's real and unchanged. Each shows your scores and until when it's valid; class assessment results don't expire. To share one: Select Share.Say who it's for (only you see this), tick the evidence to include, and choose when the link expires, from 1 to 90 days.Select Create link, then Copy link. The link is shown only once, but you can always create another. Anyone with the link sees the signed results and the evidence you ticked. Under each credential, the share links list shows each link and how often it was opened. Select Revoke to stop one working. Revoking a whole credential can't be undone: all its links stop working, and anyone who checks it sees it was revoked. Your skill passport Your Skill passport is your record of skills and credentials, built from your graded results. Each skill shows your best result. Verified means a credential backs it. To share it, switch sharing on so it says Sharing is on, then select Copy. Anyone with the link sees your name, target role, skills and credentials, never your email or your activity. Under How you appear, set the name and target role it shows. Shared it too widely? Select Create a new link (the old one stops working), or switch sharing off. How others check Each credential in your passport has a Verify link to its public page, which shows that it's genuine, or that it was revoked. Your credentials and passport stay in your account after you graduate."},{"slug":"daily-practice","title":"Daily drills and practice","summary":"Do the two daily drills, keep your streak, practice system design and hard conversations, and see the leaderboard.","roles":["member"],"group":"Practice","features":["daily-practice","code-review-drills","system-design-duels","practice-scenarios","leaderboard"],"checked":"2026-11-12","order":10,"short":["Two short drills a day, an incident and a code review. Your first try at each earns points; the answers show once you submit.","Practice on any day to keep your streak. Seven days in a row earn a streak freeze, which covers a missed day.","Duels and the leadership and failover scenarios are practice only. They don't earn points."],"blocks":[{"t":"p","c":[{"t":"text","v":"Every day there are two short drills: an incident drill and a code review. Both are in the "},{"t":"ui","v":"Practice"},{"t":"text","v":" menu, under "},{"t":"ui","v":"Incident drills"},{"t":"text","v":" and "},{"t":"ui","v":"Code review drills"},{"t":"text","v":". The "},{"t":"link","v":"Daily practice","href":"/daily"},{"t":"text","v":" page shows both, with your streak and points."}]},{"t":"h2","c":[{"t":"text","v":"Points and your streak"}]},{"t":"ul","items":[[{"t":"text","v":"Your "},{"t":"b","v":"first try"},{"t":"text","v":" at each drill earns points. You can do a drill again, but repeats don't earn points."}],[{"t":"text","v":"The answers and the reasons are shown as soon as you submit."}],[{"t":"ui","v":"Streak"},{"t":"text","v":": the days in a row you've practiced. Every 7 days in a row earn a streak freeze (you can hold 2). A freeze covers one missed day for you."}],[{"t":"ui","v":"This week"},{"t":"text","v":" starts again each week, on the day the page shows. "},{"t":"ui","v":"All time"},{"t":"text","v":" counts every point since you started."}]]},{"t":"h2","c":[{"t":"text","v":"The incident drill"}]},{"t":"p","c":[{"t":"text","v":"About 10 minutes. A service is failing, and you work out why."}]},{"t":"ol","items":[[{"t":"text","v":"Choose your "},{"t":"ui","v":"Track"},{"t":"text","v":" and "},{"t":"ui","v":"Difficulty"},{"t":"text","v":", then select "},{"t":"ui","v":"Show today's drill"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Open the drill"},{"t":"text","v":". The clock starts now."}],[{"t":"text","v":"Read the "},{"t":"ui","v":"Symptoms"},{"t":"text","v":", "},{"t":"ui","v":"Metrics"},{"t":"text","v":" and "},{"t":"ui","v":"Logs"},{"t":"text","v":"."}],[{"t":"text","v":"Choose the "},{"t":"ui","v":"Root cause"},{"t":"text","v":" and, under "},{"t":"ui","v":"What do you do now?"},{"t":"text","v":", the safe fix. Then select "},{"t":"ui","v":"Submit"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The right cause and the right fix are worth 50 points each, with 20 bonus points if both are right within 5 minutes. Afterwards you see every cause, the risk of each action, and a "},{"t":"ui","v":"Post-mortem"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"To practice on the tools you use, select "},{"t":"ui","v":"Generate a drill for your own stack"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"The code review"}]},{"t":"p","c":[{"t":"text","v":"About 3 minutes. A change to some code has one defect in it."}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Open the pull request"},{"t":"text","v":". The clock starts now."}],[{"t":"text","v":"Select the line with the defect. A line next to it counts too."}],[{"t":"text","v":"Choose the "},{"t":"ui","v":"Kind of defect"},{"t":"text","v":", then "},{"t":"ui","v":"Your decision"},{"t":"text","v":": "},{"t":"ui","v":"Approve"},{"t":"text","v":", "},{"t":"ui","v":"Request changes"},{"t":"text","v":" or "},{"t":"ui","v":"Comment only"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Submit review"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The right line is worth 50 points, the right call 30 and the right kind of defect 20. Get the line and the call right within 3 minutes for 20 bonus points."}]},{"t":"h2","c":[{"t":"text","v":"System design duels"}]},{"t":"p","c":[{"t":"text","v":"In "},{"t":"ui","v":"System design duels"},{"t":"text","v":", you design a system against the clock, and your design is scored against a practice bot. The bots aren't people, and their scores are fixed."}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"Start a duel"},{"t":"text","v":", choose a "},{"t":"ui","v":"Scenario"},{"t":"text","v":" and an "},{"t":"ui","v":"Opponent"},{"t":"text","v":", then start. The page shows the goals and how designs are scored."}],[{"t":"text","v":"Add parts from "},{"t":"ui","v":"Components"},{"t":"text","v":", set how many "},{"t":"ui","v":"Replicas"},{"t":"text","v":" each needs, and join them with "},{"t":"ui","v":"Connect"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Submit design"},{"t":"text","v":" before the time runs out."}]]},{"t":"p","c":[{"t":"text","v":"You see each check your design passed or missed, and your new rating. Duels don't earn daily points."}]},{"t":"h2","c":[{"t":"text","v":"Hard conversations and failover"}]},{"t":"p","c":[{"t":"ui","v":"Leadership practice"},{"t":"text","v":" and "},{"t":"ui","v":"Failover practice"},{"t":"text","v":" are short scenarios. In each turn, choose your response. At the end you see how close each choice was to the strongest response. Only you see your result. Select "},{"t":"ui","v":"Try again"},{"t":"text","v":" or "},{"t":"ui","v":"Other scenarios"},{"t":"text","v":", and find earlier tries under "},{"t":"ui","v":"Your past attempts"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"The leaderboard"}]},{"t":"p","c":[{"t":"ui","v":"Leaderboard"},{"t":"text","v":" ranks members on graded results only: "},{"t":"ui","v":"This week"},{"t":"text","v":", "},{"t":"ui","v":"All time"},{"t":"text","v":" and "},{"t":"ui","v":"Verified challenges"},{"t":"text","v":". Names show as a first name and last initial. To leave the leaderboard, switch off "},{"t":"ui","v":"Show me to other members"},{"t":"text","v":". You still see your own rank."}]},{"t":"p","c":[{"t":"text","v":"Next step: practice an interview out loud. See "},{"t":"link","v":"Practice interviews and speaking","href":"/help/interview-and-speaking-practice"},{"t":"text","v":"."}]}],"headings":["Points and your streak","The incident drill","The code review","System design duels","Hard conversations and failover","The leaderboard"],"text":"Every day there are two short drills: an incident drill and a code review. Both are in the Practice menu, under Incident drills and Code review drills. The Daily practice page shows both, with your streak and points. Points and your streak Your first try at each drill earns points. You can do a drill again, but repeats don't earn points.The answers and the reasons are shown as soon as you submit.Streak: the days in a row you've practiced. Every 7 days in a row earn a streak freeze (you can hold 2). A freeze covers one missed day for you.This week starts again each week, on the day the page shows. All time counts every point since you started. The incident drill About 10 minutes. A service is failing, and you work out why. Choose your Track and Difficulty, then select Show today's drill.Select Open the drill. The clock starts now.Read the Symptoms, Metrics and Logs.Choose the Root cause and, under What do you do now?, the safe fix. Then select Submit. The right cause and the right fix are worth 50 points each, with 20 bonus points if both are right within 5 minutes. Afterwards you see every cause, the risk of each action, and a Post-mortem. To practice on the tools you use, select Generate a drill for your own stack. The code review About 3 minutes. A change to some code has one defect in it. Select Open the pull request. The clock starts now.Select the line with the defect. A line next to it counts too.Choose the Kind of defect, then Your decision: Approve, Request changes or Comment only.Select Submit review. The right line is worth 50 points, the right call 30 and the right kind of defect 20. Get the line and the call right within 3 minutes for 20 bonus points. System design duels In System design duels, you design a system against the clock, and your design is scored against a practice bot. The bots aren't people, and their scores are fixed. Under Start a duel, choose a Scenario and an Opponent, then start. The page shows the goals and how designs are scored.Add parts from Components, set how many Replicas each needs, and join them with Connect.Select Submit design before the time runs out. You see each check your design passed or missed, and your new rating. Duels don't earn daily points. Hard conversations and failover Leadership practice and Failover practice are short scenarios. In each turn, choose your response. At the end you see how close each choice was to the strongest response. Only you see your result. Select Try again or Other scenarios, and find earlier tries under Your past attempts. The leaderboard Leaderboard ranks members on graded results only: This week, All time and Verified challenges. Names show as a first name and last initial. To leave the leaderboard, switch off Show me to other members. You still see your own rank. Next step: practice an interview out loud. See Practice interviews and speaking."},{"slug":"employer-jobs-and-drives","title":"Post campus jobs and follow your drives","summary":"Post a job or internship, send it to the schools that approved you, and follow each school's campus drive from applications to offers.","roles":["employer"],"group":"Hiring","features":["campus-drives","career-fairs"],"checked":"2026-11-12","order":10,"short":["Your company must be verified for campus hiring before you post.","Save the job as a draft, publish it, then send it to schools. Each school's career center approves its drive.","Once a school approves, follow the applicants, rounds and offers on the drive's page."],"blocks":[{"t":"p","c":[{"t":"text","v":"A job you send to a school becomes a "},{"t":"term","v":"campus drive","key":"campus-drive"},{"t":"text","v":" at that school. Students see it only after the school's "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" approves it."}]},{"t":"h2","c":[{"t":"text","v":"Before you post"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Campus jobs"},{"t":"text","v":" under "},{"t":"ui","v":"Hiring"},{"t":"text","v":". "},{"t":"ui","v":"Company verification"},{"t":"text","v":" must show "},{"t":"ui","v":"Verified"},{"t":"text","v":" before you can post."}]},{"t":"ul","items":[[{"t":"text","v":"A company that Edulexa staff verified is ready."}],[{"t":"text","v":"A company in India can verify itself with its GSTIN, signed in with a company e-mail address."}],[{"t":"text","v":"Other companies ask Edulexa support to verify them, from the help center."}]]},{"t":"h2","c":[{"t":"text","v":"Post a job"}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"New job or internship"},{"t":"text","v":", fill in the "},{"t":"ui","v":"Title"},{"t":"text","v":", the "},{"t":"ui","v":"Type"},{"t":"text","v":", the "},{"t":"ui","v":"Currency"},{"t":"text","v":" and the pay."}],[{"t":"text","v":"Add the "},{"t":"ui","v":"Locations"},{"t":"text","v":", "},{"t":"ui","v":"Degrees"},{"t":"text","v":", "},{"t":"ui","v":"Programs"},{"t":"text","v":", "},{"t":"ui","v":"Graduation years"},{"t":"text","v":", the lowest grade you accept, and your "},{"t":"ui","v":"Selection rounds"},{"t":"text","v":" in order."}],[{"t":"text","v":"Set the "},{"t":"ui","v":"Application deadline"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Who receives it"},{"t":"text","v":", choose "},{"t":"ui","v":"Schools I choose"},{"t":"text","v":", or "},{"t":"ui","v":"All schools that approved my company (each still approves)"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"How students respond"},{"t":"text","v":", choose "},{"t":"ui","v":"Apply with documents"},{"t":"text","v":" and tick the "},{"t":"ui","v":"Documents students must attach"},{"t":"text","v":", or choose "},{"t":"ui","v":"Opt in"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Save as draft"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Open the job from "},{"t":"ui","v":"Your jobs"},{"t":"text","v":" and select "},{"t":"ui","v":"Publish"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Send it to schools"}]},{"t":"p","c":[{"t":"text","v":"On the job's page, under "},{"t":"ui","v":"Send to schools"},{"t":"text","v":", tick the schools. Add a "},{"t":"ui","v":"Drive date"},{"t":"text","v":" and a "},{"t":"ui","v":"Mode"},{"t":"text","v":" if you know them, then select the send button."}]},{"t":"p","c":[{"t":"ui","v":"Drives at schools"},{"t":"text","v":" shows each school's drive, its status, the number of applications and the school's note. Some schools approve drives from verified employers automatically; those show "},{"t":"ui","v":"Approved automatically"},{"t":"text","v":"."}]},{"t":"ul","items":[[{"t":"ui","v":"Pause"},{"t":"text","v":" stops schools taking applications. Select "},{"t":"ui","v":"Publish"},{"t":"text","v":" to start again."}],[{"t":"ui","v":"Close job"},{"t":"text","v":" closes it for good."}],[{"t":"ui","v":"Withdraw"},{"t":"text","v":" takes the drive back from one school."}]]},{"t":"h2","c":[{"t":"text","v":"Follow a drive"}]},{"t":"p","c":[{"t":"text","v":"Select a school's name to open its drive. The top shows the deadline, whether it's taking applications, and the school's rules, such as one offer per student."}]},{"t":"p","c":[{"t":"text","v":"Applicants appear once the school approves the drive. You see the details students chose to share with your company when they applied. Each time the list is shown, it's recorded in the school's log of who saw student information. From the drive you can:"}]},{"t":"ul","items":[[{"t":"text","v":"add the selection rounds with "},{"t":"ui","v":"Add round"},{"t":"text","v":";"}],[{"t":"text","v":"shortlist applicants, and select "},{"t":"ui","v":"Record result for selected"},{"t":"text","v":" after each round;"}],[{"t":"text","v":"set "},{"t":"ui","v":"Interview slots"},{"t":"text","v":" for the shortlist;"}],[{"t":"ui","v":"Make an offer"},{"t":"text","v":" to an applicant, who can accept or decline it, and issue "},{"t":"ui","v":"Offer letters"},{"t":"text","v":" for students to sign."}]]},{"t":"h2","c":[{"t":"text","v":"Career fairs"}]},{"t":"p","c":[{"t":"ui","v":"Career fairs"},{"t":"text","v":" lists upcoming fairs at the schools that approved you. Each fair links to the school's own event page, where you request a booth."}]}],"headings":["Before you post","Post a job","Send it to schools","Follow a drive","Career fairs"],"text":"A job you send to a school becomes a campus drive at that school. Students see it only after the school's career center approves it. Before you post Open Campus jobs under Hiring. Company verification must show Verified before you can post. A company that Edulexa staff verified is ready.A company in India can verify itself with its GSTIN, signed in with a company e-mail address.Other companies ask Edulexa support to verify them, from the help center. Post a job Under New job or internship, fill in the Title, the Type, the Currency and the pay.Add the Locations, Degrees, Programs, Graduation years, the lowest grade you accept, and your Selection rounds in order.Set the Application deadline.Under Who receives it, choose Schools I choose, or All schools that approved my company (each still approves).Under How students respond, choose Apply with documents and tick the Documents students must attach, or choose Opt in.Select Save as draft. Open the job from Your jobs and select Publish. Send it to schools On the job's page, under Send to schools, tick the schools. Add a Drive date and a Mode if you know them, then select the send button. Drives at schools shows each school's drive, its status, the number of applications and the school's note. Some schools approve drives from verified employers automatically; those show Approved automatically. Pause stops schools taking applications. Select Publish to start again.Close job closes it for good.Withdraw takes the drive back from one school. Follow a drive Select a school's name to open its drive. The top shows the deadline, whether it's taking applications, and the school's rules, such as one offer per student. Applicants appear once the school approves the drive. You see the details students chose to share with your company when they applied. Each time the list is shown, it's recorded in the school's log of who saw student information. From the drive you can: add the selection rounds with Add round;shortlist applicants, and select Record result for selected after each round;set Interview slots for the shortlist;Make an offer to an applicant, who can accept or decline it, and issue Offer letters for students to sign. Career fairs Career fairs lists upcoming fairs at the schools that approved you. Each fair links to the school's own event page, where you request a booth."},{"slug":"employers-and-approvals","title":"Approve employers and their jobs","summary":"Decide which companies can recruit your students, and approve the jobs and campus drives they send your school.","roles":["staff"],"group":"Employers and jobs","features":["employer-accounts","campus-drives"],"checked":"2026-11-11","order":10,"short":["Companies ask to recruit at your school. Approve, decline or block them in Employers.","Their jobs reach your students only after you approve them in Campus drives.","Career admins and employer relations staff make these decisions."],"blocks":[{"t":"p","c":[{"t":"text","v":"Employers create a company account in Edulexa and ask to recruit at your school. Career admins and employer relations staff decide. Your home page shows how many requests are waiting."}]},{"t":"h2","c":[{"t":"text","v":"Approve an employer"}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Employers"},{"t":"text","v":" from the "},{"t":"ui","v":"Employers and jobs"},{"t":"text","v":" menu."}],[{"t":"text","v":"The "},{"t":"ui","v":"Pending"},{"t":"text","v":" tab lists new requests, with the company's details, its website and its note to you. A badge shows whether Edulexa could confirm the company. It's there to help you decide; it doesn't approve anyone."}],[{"t":"text","v":"Write a "},{"t":"ui","v":"Note to the employer (optional)"},{"t":"text","v":" if you like, then select "},{"t":"ui","v":"Approve"},{"t":"text","v":", "},{"t":"ui","v":"Decline"},{"t":"text","v":" or "},{"t":"ui","v":"Block"},{"t":"text","v":". A blocked company can't ask again."}]]},{"t":"p","c":[{"t":"text","v":"The employer is told either way. You can change a "},{"t":"term","v":"decision","key":"decision"},{"t":"text","v":" later from the "},{"t":"ui","v":"Approved"},{"t":"text","v":", "},{"t":"ui","v":"Declined"},{"t":"text","v":" or "},{"t":"ui","v":"Blocked"},{"t":"text","v":" tab."}]},{"t":"p","c":[{"t":"text","v":"Once approved, an employer can send your school jobs and interview schedules and, if your school has one, browse the "},{"t":"link","v":"résumé book","href":"/help/resume-book"},{"t":"text","v":"."}]},{"t":"shot","name":"staff-employer-requests","alt":"The Employers page, with its Pending, Approved, Declined and Blocked tabs, showing an approved company","w":1600,"h":518},{"t":"h2","c":[{"t":"text","v":"Approve their jobs"}]},{"t":"p","c":[{"t":"text","v":"Each job an employer sends your school arrives as a "},{"t":"term","v":"campus drive","key":"campus-drive"},{"t":"text","v":" and waits for you in "},{"t":"ui","v":"Campus drives"},{"t":"text","v":", on the "},{"t":"ui","v":"Approvals"},{"t":"text","v":" tab. Only approved drives are shown to students."}]},{"t":"ol","items":[[{"t":"text","v":"Open a drive to see the job, the pay, the deadline and whether the employer is verified."}],[{"t":"text","v":"Check the eligibility rules for your school, such as programs and graduation years."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Approve"},{"t":"text","v":", or "},{"t":"ui","v":"Don't approve"},{"t":"text","v":" with a "},{"t":"ui","v":"Note to the employer"},{"t":"text","v":" saying why."}]]},{"t":"p","c":[{"t":"text","v":"When you approve, eligible students are told."}]},{"t":"h2","c":[{"t":"text","v":"Your school's rules"}]},{"t":"p","c":[{"t":"text","v":"On the "},{"t":"ui","v":"Rules"},{"t":"text","v":" tab, a career admin can approve drives from verified employers automatically and set placement rules, such as one offer per student."}]},{"t":"p","c":[{"t":"text","v":"Counselors can see campus drives but don't decide on them or on employers."}]}],"headings":["Approve an employer","Approve their jobs","Your school's rules"],"text":"Employers create a company account in Edulexa and ask to recruit at your school. Career admins and employer relations staff decide. Your home page shows how many requests are waiting. Approve an employer Open Employers from the Employers and jobs menu.The Pending tab lists new requests, with the company's details, its website and its note to you. A badge shows whether Edulexa could confirm the company. It's there to help you decide; it doesn't approve anyone.Write a Note to the employer (optional) if you like, then select Approve, Decline or Block. A blocked company can't ask again. The employer is told either way. You can change a decision later from the Approved, Declined or Blocked tab. Once approved, an employer can send your school jobs and interview schedules and, if your school has one, browse the résumé book. Approve their jobs Each job an employer sends your school arrives as a campus drive and waits for you in Campus drives, on the Approvals tab. Only approved drives are shown to students. Open a drive to see the job, the pay, the deadline and whether the employer is verified.Check the eligibility rules for your school, such as programs and graduation years.Select Approve, or Don't approve with a Note to the employer saying why. When you approve, eligible students are told. Your school's rules On the Rules tab, a career admin can approve drives from verified employers automatically and set placement rules, such as one offer per student. Counselors can see campus drives but don't decide on them or on employers."},{"slug":"exams-and-challenges","title":"Exams, coding challenges and your GitHub work","summary":"Take a written exam, solve a graded coding challenge and defend it, or defend code you wrote on GitHub, and earn credentials anyone can check.","roles":["member"],"group":"Prove your skills","features":["written-exams","coding-challenges","repo-defense"],"checked":"2026-11-12","order":10,"short":["Written exams are timed multiple-choice exams. Pass a credential exam, then select Claim verified credential.","In a coding challenge you write or fix code, hidden tests check it, and then you explain it in a voice defense.","Defend your GitHub work lets you prove a public project is yours, then defend it the same way."],"blocks":[{"t":"p","c":[{"t":"text","v":"Everything here is graded, and passing earns a "},{"t":"term","v":"credential","key":"credential"},{"t":"text","v":": a signed record anyone can check. These are under "},{"t":"ui","v":"Prove your skills"},{"t":"text","v":" in the "},{"t":"ui","v":"Practice"},{"t":"text","v":" menu."}]},{"t":"h2","c":[{"t":"text","v":"Written exams"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Written exams"},{"t":"text","v":". "},{"t":"ui","v":"Available exams"},{"t":"text","v":" lists the exams you can take. Each card shows how long it takes, how many questions it has, and how many tries you have left."}]},{"t":"ul","items":[[{"t":"b","v":"Credential exams"},{"t":"text","v":" ("},{"t":"ui","v":"Credential exam: answers not shown"},{"t":"text","v":") can earn a credential. You get a few tries, with a wait between them."}],[{"t":"b","v":"Practice exams"},{"t":"text","v":" don't give a credential. Many show the right answers after you submit; the card says so."}]]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Start exam"},{"t":"text","v":", or "},{"t":"ui","v":"Start practice exam"},{"t":"text","v":". The clock starts."}],[{"t":"text","v":"Answer each question. Move with "},{"t":"ui","v":"Next question"},{"t":"text","v":" and "},{"t":"ui","v":"Previous question"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Submit final exam"},{"t":"text","v":" before the time runs out. If the time runs out first, the try isn't graded, but it still counts as one of your tries."}]]},{"t":"p","c":[{"t":"text","v":"You see your score, the "},{"t":"ui","v":"Passing score"},{"t":"text","v":" and whether you passed. Passed a credential exam? Select "},{"t":"ui","v":"Claim verified credential"},{"t":"text","v":" to add it to your credentials and your "},{"t":"term","v":"skill passport","key":"skill-passport"},{"t":"text","v":". To try again, select "},{"t":"ui","v":"Retake exam"},{"t":"text","v":". Your past tries are under "},{"t":"ui","v":"My attempts and credentials"},{"t":"text","v":"."}]},{"t":"h3","c":[{"t":"text","v":"Your own practice exams"}]},{"t":"ul","items":[[{"t":"ui","v":"Generate an exam with AI"},{"t":"text","v":": choose a "},{"t":"ui","v":"Topic"},{"t":"text","v":", "},{"t":"ui","v":"Difficulty"},{"t":"text","v":" and "},{"t":"ui","v":"Number of questions"},{"t":"text","v":", then select "},{"t":"ui","v":"Generate and start"},{"t":"text","v":"."}],[{"t":"ui","v":"Import questions"},{"t":"text","v":": add your own questions. Select "},{"t":"ui","v":"Load an example"},{"t":"text","v":" to see how to write them, then "},{"t":"ui","v":"Publish questions"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Only you see the exams you make, and they don't give a credential."}]},{"t":"h2","c":[{"t":"text","v":"Coding challenges"}]},{"t":"p","c":[{"t":"ui","v":"Coding challenges"},{"t":"text","v":" opens a practice editor where nothing is graded. Use "},{"t":"ui","v":"Run code"},{"t":"text","v":" to try things out."}]},{"t":"p","c":[{"t":"text","v":"For the real thing, pick a challenge from "},{"t":"ui","v":"Graded challenges"},{"t":"text","v":". Challenges marked "},{"t":"ui","v":"Pro"},{"t":"text","v":" need the Pro plan; see "},{"t":"link","v":"Pricing and minutes","href":"/pricing"},{"t":"text","v":". Each challenge has four steps:"}]},{"t":"ol","items":[[{"t":"b","v":"Write or fix the code"},{"t":"text","v":" in your browser. Some challenges are an existing project with defects to find and fix. Select "},{"t":"ui","v":"Run"},{"t":"text","v":" to try your code, then "},{"t":"ui","v":"Submit Sprint"},{"t":"text","v":"."}],[{"t":"b","v":"Tests:"},{"t":"text","v":" hidden tests check your code."}],[{"t":"b","v":"Voice defense:"},{"t":"text","v":" a short spoken conversation with an AI interviewer about your code: why you made your choices, and what you'd change. Select "},{"t":"ui","v":"Start defense"},{"t":"text","v":", and "},{"t":"ui","v":"End call"},{"t":"text","v":" when it's over. If voice doesn't work for you, select "},{"t":"ui","v":"Answer in writing instead"},{"t":"text","v":"."}],[{"t":"b","v":"Result:"},{"t":"text","v":" if you pass, you get a credential. Sometimes a reviewer confirms it first; until then it shows as under review."}]]},{"t":"note","c":[{"t":"text","v":"Your edits, pastes and switching away from the window are recorded, and reviewers see them with your work. The challenge also says whether AI tools are allowed: "},{"t":"ui","v":"No AI tools"},{"t":"text","v":", "},{"t":"ui","v":"AI use reviewed"},{"t":"text","v":" or "},{"t":"ui","v":"AI allowed"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Your work is saved as you go. If you lose your connection, come back and pick up where you left off. Each result, with its feedback, is in "},{"t":"link","v":"My results","href":"/my/results"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Defend your GitHub work"}]},{"t":"p","c":[{"t":"ui","v":"Defend your GitHub work"},{"t":"text","v":" lets you defend code you really wrote. It works with public projects only."}]},{"t":"ol","items":[[{"t":"text","v":"Paste the "},{"t":"ui","v":"Link to the GitHub repository or pull request"},{"t":"text","v":", add the "},{"t":"ui","v":"Pull request number (optional)"},{"t":"text","v":", and enter "},{"t":"ui","v":"Your GitHub username"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Get verification code"},{"t":"text","v":"."}],[{"t":"text","v":"Add the code to your GitHub profile bio, or to the description of a public gist, then select "},{"t":"ui","v":"Verify"},{"t":"text","v":". You can remove the code from GitHub afterwards."}],[{"t":"text","v":"Edulexa checks how much of the work is yours and picks the files you wrote."}],[{"t":"text","v":"Under "},{"t":"ui","v":"3. Defend it"},{"t":"text","v":", select "},{"t":"ui","v":"Start defense"},{"t":"text","v":". The interviewer asks about those files."}]]},{"t":"p","c":[{"t":"text","v":"If you pass, a credential for this work is added to your credentials."}]},{"t":"note","c":[{"t":"text","v":"A voice defense uses your "},{"t":"term","v":"voice minutes","key":"voice-minutes"},{"t":"text","v":" for the time you talk, rounded up to the next minute. Answering in writing uses none."}]},{"t":"p","c":[{"t":"text","v":"Next step: see your results and share your credentials. See "},{"t":"link","v":"Your results, credentials and skill passport","href":"/help/member-results-and-credentials"},{"t":"text","v":"."}]}],"headings":["Written exams","Your own practice exams","Coding challenges","Defend your GitHub work"],"text":"Everything here is graded, and passing earns a credential: a signed record anyone can check. These are under Prove your skills in the Practice menu. Written exams Open Written exams. Available exams lists the exams you can take. Each card shows how long it takes, how many questions it has, and how many tries you have left. Credential exams (Credential exam: answers not shown) can earn a credential. You get a few tries, with a wait between them.Practice exams don't give a credential. Many show the right answers after you submit; the card says so. Select Start exam, or Start practice exam. The clock starts.Answer each question. Move with Next question and Previous question.Select Submit final exam before the time runs out. If the time runs out first, the try isn't graded, but it still counts as one of your tries. You see your score, the Passing score and whether you passed. Passed a credential exam? Select Claim verified credential to add it to your credentials and your skill passport. To try again, select Retake exam. Your past tries are under My attempts and credentials. Your own practice exams Generate an exam with AI: choose a Topic, Difficulty and Number of questions, then select Generate and start.Import questions: add your own questions. Select Load an example to see how to write them, then Publish questions. Only you see the exams you make, and they don't give a credential. Coding challenges Coding challenges opens a practice editor where nothing is graded. Use Run code to try things out. For the real thing, pick a challenge from Graded challenges. Challenges marked Pro need the Pro plan; see Pricing and minutes. Each challenge has four steps: Write or fix the code in your browser. Some challenges are an existing project with defects to find and fix. Select Run to try your code, then Submit Sprint.Tests: hidden tests check your code.Voice defense: a short spoken conversation with an AI interviewer about your code: why you made your choices, and what you'd change. Select Start defense, and End call when it's over. If voice doesn't work for you, select Answer in writing instead.Result: if you pass, you get a credential. Sometimes a reviewer confirms it first; until then it shows as under review. Your edits, pastes and switching away from the window are recorded, and reviewers see them with your work. The challenge also says whether AI tools are allowed: No AI tools, AI use reviewed or AI allowed. Your work is saved as you go. If you lose your connection, come back and pick up where you left off. Each result, with its feedback, is in My results. Defend your GitHub work Defend your GitHub work lets you defend code you really wrote. It works with public projects only. Paste the Link to the GitHub repository or pull request, add the Pull request number (optional), and enter Your GitHub username.Select Get verification code.Add the code to your GitHub profile bio, or to the description of a public gist, then select Verify. You can remove the code from GitHub afterwards.Edulexa checks how much of the work is yours and picks the files you wrote.Under 3. Defend it, select Start defense. The interviewer asks about those files. If you pass, a credential for this work is added to your credentials. A voice defense uses your voice minutes for the time you talk, rounded up to the next minute. Answering in writing uses none. Next step: see your results and share your credentials. See Your results, credentials and skill passport."},{"slug":"guidance-forms","title":"Build your guidance forms","summary":"Make a form from a template, change its questions and results, publish it, and put it on your website or share its link.","roles":["admissions"],"group":"Forms and the quiz","features":["guidance-forms"],"checked":"2026-11-12","order":10,"short":["Select New form, pick a template and select Create and edit. Change the questions, then select Publish.","Turn on the public link in Share, then copy the link, print the QR code or put the form on your website.","Each person who sends the form becomes a lead, and gets a report with their results if you choose."],"blocks":[{"t":"p","c":[{"t":"text","v":"Your guidance forms are the questions people answer when they ask your institute for help choosing an area or a certification. Each answer becomes a "},{"t":"term","v":"lead","key":"lead"},{"t":"text","v":" in your "},{"t":"link","v":"admissions leads","href":"/institute/dashboard"},{"t":"text","v":". Open "},{"t":"ui","v":"Guidance forms"},{"t":"text","v":" under "},{"t":"ui","v":"Forms"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Make a form"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"New form"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Start from"},{"t":"text","v":", pick a template. Templates are grouped by the kind of school they're for. Use "},{"t":"ui","v":"Show templates for"},{"t":"text","v":" to see the ones for your country."}],[{"t":"text","v":"Give it a "},{"t":"ui","v":"Name"},{"t":"text","v":" and select "},{"t":"ui","v":"Create and edit"},{"t":"text","v":". You can change every question before you publish."}]]},{"t":"p","c":[{"t":"text","v":"To copy a form you already have, select "},{"t":"ui","v":"Duplicate"},{"t":"text","v":" on its card."}]},{"t":"h2","c":[{"t":"text","v":"Change it"}]},{"t":"p","c":[{"t":"text","v":"The form opens on "},{"t":"ui","v":"Questions"},{"t":"text","v":". Change the text of any question, select "},{"t":"ui","v":"Add question"},{"t":"text","v":", or "},{"t":"ui","v":"Add a step"},{"t":"text","v":" to split the form into steps. A preview shows beside it."}]},{"t":"p","c":[{"t":"text","v":"The other tabs:"}]},{"t":"ul","items":[[{"t":"ui","v":"Results"},{"t":"text","v":": what the form works out from the answers, an outcome, a match score or both, and whether people see their results after they send."}],[{"t":"ui","v":"Automatic messages"},{"t":"text","v":": e-mails, SMS or WhatsApp messages the form sends by itself, to the person or to your team."}],[{"t":"ui","v":"Settings"},{"t":"text","v":": the form's languages, who can fill it in, saving answers for people who don't finish, and checks against fake requests."}],[{"t":"ui","v":"Translations"},{"t":"text","v":": your texts in each language you added."}],[{"t":"ui","v":"Share"},{"t":"text","v":": the link, the QR code and the code for your website."}],[{"t":"ui","v":"Insights"},{"t":"text","v":": visits, how many started and sent the form, and where they came from."}]]},{"t":"p","c":[{"t":"text","v":"Your changes are saved as you go, as a draft. People keep seeing the published version until you select "},{"t":"ui","v":"Publish"},{"t":"text","v":". "},{"t":"ui","v":"Discard changes"},{"t":"text","v":" goes back to the published form."}]},{"t":"h2","c":[{"t":"text","v":"Share it"}]},{"t":"p","c":[{"t":"text","v":"A new form can't be opened from outside Edulexa yet. In "},{"t":"ui","v":"Share"},{"t":"text","v":", select "},{"t":"ui","v":"Turn on the public link"},{"t":"text","v":". Then:"}]},{"t":"ul","items":[[{"t":"text","v":"copy the link, or select "},{"t":"ui","v":"Download QR (PNG)"},{"t":"text","v":" for posters, brochures and stalls. Add a "},{"t":"ui","v":"Campaign (optional)"},{"t":"text","v":" name to see which link a lead came from;"}],[{"t":"text","v":"under "},{"t":"ui","v":"Put it on your website"},{"t":"text","v":", copy the code into your website, or the code for a button that opens the form. It works on most website builders."}]]},{"t":"note","c":[{"t":"text","v":"Your plan may include your own address for the form, such as guidance.yourschool.edu. The person who manages your domain name has to add two records first; the steps are on the page."}]},{"t":"h2","c":[{"t":"text","v":"Your forms page"}]},{"t":"p","c":[{"t":"text","v":"Each form's card shows whether its public link is on, its version, how many people sent it, and "},{"t":"ui","v":"Unpublished changes"},{"t":"text","v":" if you haven't published your latest changes. One form is "},{"t":"ui","v":"Used for “Ask an advisor”"},{"t":"text","v":": Edulexa members who are signed in use it when they ask you for guidance. To change which one, select "},{"t":"ui","v":"Use for “Ask an advisor”"},{"t":"text","v":" on another form."}]},{"t":"p","c":[{"t":"text","v":"At the top of the page, "},{"t":"ui","v":"Statistics"},{"t":"text","v":" compares your forms, and "},{"t":"ui","v":"Notifications"},{"t":"text","v":" lists every automatic message sent."}]},{"t":"p","c":[{"t":"text","v":"Below your forms, fill in "},{"t":"ui","v":"Your institute's card"},{"t":"text","v":" and select "},{"t":"ui","v":"Save card"},{"t":"text","v":". It's shown when people on Edulexa choose an institute to talk to, with your real courses. Only what you fill in is shown."}]}],"headings":["Make a form","Change it","Share it","Your forms page"],"text":"Your guidance forms are the questions people answer when they ask your institute for help choosing an area or a certification. Each answer becomes a lead in your admissions leads. Open Guidance forms under Forms. Make a form Select New form.Under Start from, pick a template. Templates are grouped by the kind of school they're for. Use Show templates for to see the ones for your country.Give it a Name and select Create and edit. You can change every question before you publish. To copy a form you already have, select Duplicate on its card. Change it The form opens on Questions. Change the text of any question, select Add question, or Add a step to split the form into steps. A preview shows beside it. The other tabs: Results: what the form works out from the answers, an outcome, a match score or both, and whether people see their results after they send.Automatic messages: e-mails, SMS or WhatsApp messages the form sends by itself, to the person or to your team.Settings: the form's languages, who can fill it in, saving answers for people who don't finish, and checks against fake requests.Translations: your texts in each language you added.Share: the link, the QR code and the code for your website.Insights: visits, how many started and sent the form, and where they came from. Your changes are saved as you go, as a draft. People keep seeing the published version until you select Publish. Discard changes goes back to the published form. Share it A new form can't be opened from outside Edulexa yet. In Share, select Turn on the public link. Then: copy the link, or select Download QR (PNG) for posters, brochures and stalls. Add a Campaign (optional) name to see which link a lead came from;under Put it on your website, copy the code into your website, or the code for a button that opens the form. It works on most website builders. Your plan may include your own address for the form, such as guidance.yourschool.edu. The person who manages your domain name has to add two records first; the steps are on the page. Your forms page Each form's card shows whether its public link is on, its version, how many people sent it, and Unpublished changes if you haven't published your latest changes. One form is Used for “Ask an advisor”: Edulexa members who are signed in use it when they ask you for guidance. To change which one, select Use for “Ask an advisor” on another form. At the top of the page, Statistics compares your forms, and Notifications lists every automatic message sent. Below your forms, fill in Your institute's card and select Save card. It's shown when people on Edulexa choose an institute to talk to, with your real courses. Only what you fill in is shown."},{"slug":"member-results-and-credentials","title":"Your results, credentials and skill passport","summary":"Read the full report on each graded challenge, appeal or ask for an accommodation, share your credentials, and share your skill passport.","roles":["member"],"group":"Your record","features":["my-results","credentials","skill-passport"],"checked":"2026-11-12","order":10,"short":["My results has a full report on each coding challenge, with feedback. Appeal or ask for an accommodation from the report.","In Credentials, select Share to give someone a link that ends when you choose. You can stop it at any time.","Your skill passport sums up your skills and credentials. Turn sharing on to give out its link."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Your results"}]},{"t":"p","c":[{"t":"ui","v":"My results"},{"t":"text","v":" lists each coding challenge you've handed in, and any assessment an employer invited you to. Each one shows its tests, your defense and where the review stands. Select one to open its report:"}]},{"t":"ul","items":[[{"t":"ui","v":"Tests passed"},{"t":"text","v":", your "},{"t":"ui","v":"Defense score"},{"t":"text","v":", the "},{"t":"ui","v":"Review"},{"t":"text","v":" and "},{"t":"ui","v":"Integrity"},{"t":"text","v":"."}],[{"t":"text","v":"Feedback written for you: "},{"t":"ui","v":"Strengths"},{"t":"text","v":", "},{"t":"ui","v":"Gaps"},{"t":"text","v":" and "},{"t":"ui","v":"Three next steps"},{"t":"text","v":"."}],[{"t":"ui","v":"Your defense"},{"t":"text","v":": your scores, the skills to work on, and the questions and answers."}]]},{"t":"p","c":[{"t":"text","v":"A person reviews every result. Nothing is decided automatically."}]},{"t":"p","c":[{"t":"text","v":"Your written exam results are on the "},{"t":"ui","v":"Written exams"},{"t":"text","v":" page, under "},{"t":"ui","v":"My attempts and credentials"},{"t":"text","v":"."}]},{"t":"h3","c":[{"t":"text","v":"Appeal a result"}]},{"t":"p","c":[{"t":"text","v":"If something went wrong, or you think the result was unfair, "},{"t":"term","v":"appeal","key":"appeal"},{"t":"text","v":" it from the report."}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"What is the appeal about?"},{"t":"text","v":", choose what happened: "},{"t":"ui","v":"Technical problem"},{"t":"text","v":" (something broke, or you lost work), "},{"t":"ui","v":"Accessibility"},{"t":"text","v":", "},{"t":"ui","v":"Integrity review"},{"t":"text","v":" (you think your work is being questioned unfairly), "},{"t":"ui","v":"Scoring error"},{"t":"text","v":" or "},{"t":"ui","v":"Other"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Explain what happened"},{"t":"text","v":", say what happened, when, and what you'd like looked at again (at least 50 characters)."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Submit appeal"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"A reviewer who wasn't part of the first review looks at it, and you get their answer by e-mail. You can "},{"t":"ui","v":"Withdraw appeal"},{"t":"text","v":" while it's open."}]},{"t":"h3","c":[{"t":"text","v":"Ask for an accommodation"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Accommodations"},{"t":"text","v":", choose the "},{"t":"ui","v":"Type"},{"t":"text","v":" of help you need: "},{"t":"ui","v":"Extra time"},{"t":"text","v":", "},{"t":"ui","v":"Written defense instead of voice"},{"t":"text","v":", "},{"t":"ui","v":"Screen-reader support"},{"t":"text","v":" or "},{"t":"ui","v":"Other"},{"t":"text","v":". Tick "},{"t":"ui","v":"Only for this challenge (otherwise for all my assessments)"},{"t":"text","v":" if it's just for this one. Under "},{"t":"ui","v":"What do you need?"},{"t":"text","v":", describe what would help (you don't have to share a diagnosis), and select "},{"t":"ui","v":"Send request"},{"t":"text","v":". You get an e-mail when a reviewer decides."}]},{"t":"h2","c":[{"t":"text","v":"Your credentials"}]},{"t":"p","c":[{"t":"text","v":"A "},{"t":"term","v":"credential","key":"credential"},{"t":"text","v":" is a signed record of something you passed. Signed means Edulexa vouches for it: anyone can check it's real and unchanged. Yours are all in "},{"t":"ui","v":"Credentials"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"To share one:"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Share"},{"t":"text","v":"."}],[{"t":"text","v":"Say who it's for (only you see this), and tick what to show with your results: "},{"t":"ui","v":"Submitted code"},{"t":"text","v":", the "},{"t":"ui","v":"Voice defense recording"},{"t":"text","v":" or the "},{"t":"ui","v":"Voice defense transcript"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Link expires after"},{"t":"text","v":", choose from 1 to 90 days, then select "},{"t":"ui","v":"Create link"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Copy link"},{"t":"text","v":". The link is shown only once, but you can always create another."}]]},{"t":"p","c":[{"t":"text","v":"Under each credential, the share links list how often each link was opened. Select "},{"t":"ui","v":"Revoke"},{"t":"text","v":" next to a link to stop it working."}]},{"t":"p","c":[{"t":"text","v":"Other ways to use a credential:"}]},{"t":"ul","items":[[{"t":"ui","v":"Use for a job application"},{"t":"text","v":": if an employer invited you to an assessment, answer with this credential instead of taking it again."}],[{"t":"ui","v":"Download Open Badge"},{"t":"text","v":": for badge wallets and other organizations' systems."}],[{"t":"ui","v":"Download learner record"},{"t":"text","v":": a signed file of the credentials you choose, for a registrar or another school."}]]},{"t":"note","c":[{"t":"text","v":"Revoking a whole credential can't be undone. All its links stop working, and anyone who checks it sees it was revoked."}]},{"t":"h2","c":[{"t":"text","v":"Your skill passport"}]},{"t":"p","c":[{"t":"text","v":"Your "},{"t":"ui","v":"Skill passport"},{"t":"text","v":" is your record of skills and credentials, built from your graded results. Each skill shows your best result; "},{"t":"ui","v":"Verified"},{"t":"text","v":" means a credential backs it."}]},{"t":"ul","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"How you appear"},{"t":"text","v":", set the "},{"t":"ui","v":"Name"},{"t":"text","v":" and "},{"t":"ui","v":"Target role"},{"t":"text","v":" it shows, then select "},{"t":"ui","v":"Save"},{"t":"text","v":"."}],[{"t":"text","v":"Switch sharing on so it says "},{"t":"ui","v":"Sharing is on"},{"t":"text","v":", then select "},{"t":"ui","v":"Copy"},{"t":"text","v":" to copy its link. Anyone with the link sees your name, target role, skills and credentials, never your e-mail or your activity."}],[{"t":"text","v":"Shared it too widely? Select "},{"t":"ui","v":"Create a new link (the old one stops working)"},{"t":"text","v":", or switch sharing off."}]]},{"t":"p","c":[{"t":"text","v":"Next step: put your verified results on a résumé. See "},{"t":"link","v":"Résumés, job check and cover letters","href":"/help/member-resumes"},{"t":"text","v":"."}]}],"headings":["Your results","Appeal a result","Ask for an accommodation","Your credentials","Your skill passport"],"text":"Your results My results lists each coding challenge you've handed in, and any assessment an employer invited you to. Each one shows its tests, your defense and where the review stands. Select one to open its report: Tests passed, your Defense score, the Review and Integrity.Feedback written for you: Strengths, Gaps and Three next steps.Your defense: your scores, the skills to work on, and the questions and answers. A person reviews every result. Nothing is decided automatically. Your written exam results are on the Written exams page, under My attempts and credentials. Appeal a result If something went wrong, or you think the result was unfair, appeal it from the report. Under What is the appeal about?, choose what happened: Technical problem (something broke, or you lost work), Accessibility, Integrity review (you think your work is being questioned unfairly), Scoring error or Other.Under Explain what happened, say what happened, when, and what you'd like looked at again (at least 50 characters).Select Submit appeal. A reviewer who wasn't part of the first review looks at it, and you get their answer by e-mail. You can Withdraw appeal while it's open. Ask for an accommodation Under Accommodations, choose the Type of help you need: Extra time, Written defense instead of voice, Screen-reader support or Other. Tick Only for this challenge (otherwise for all my assessments) if it's just for this one. Under What do you need?, describe what would help (you don't have to share a diagnosis), and select Send request. You get an e-mail when a reviewer decides. Your credentials A credential is a signed record of something you passed. Signed means Edulexa vouches for it: anyone can check it's real and unchanged. Yours are all in Credentials. To share one: Select Share.Say who it's for (only you see this), and tick what to show with your results: Submitted code, the Voice defense recording or the Voice defense transcript.Under Link expires after, choose from 1 to 90 days, then select Create link.Select Copy link. The link is shown only once, but you can always create another. Under each credential, the share links list how often each link was opened. Select Revoke next to a link to stop it working. Other ways to use a credential: Use for a job application: if an employer invited you to an assessment, answer with this credential instead of taking it again.Download Open Badge: for badge wallets and other organizations' systems.Download learner record: a signed file of the credentials you choose, for a registrar or another school. Revoking a whole credential can't be undone. All its links stop working, and anyone who checks it sees it was revoked. Your skill passport Your Skill passport is your record of skills and credentials, built from your graded results. Each skill shows your best result; Verified means a credential backs it. Under How you appear, set the Name and Target role it shows, then select Save.Switch sharing on so it says Sharing is on, then select Copy to copy its link. Anyone with the link sees your name, target role, skills and credentials, never your e-mail or your activity.Shared it too widely? Select Create a new link (the old one stops working), or switch sharing off. Next step: put your verified results on a résumé. See Résumés, job check and cover letters."},{"slug":"recruiter-appeals-and-accommodations","title":"Answer appeals and accommodation requests","summary":"Look again at a decision a candidate appealed, and approve or decline a candidate's request for an accommodation, such as extra time.","roles":["recruiter"],"group":"Fairness","features":["appeals-accommodations"],"checked":"2026-11-12","order":10,"short":["In Appeals, uphold or overturn the result and write to the candidate. Someone other than the person who decided must answer.","In Accommodations, approve a request, or decline it with a note to the candidate.","The candidate is e-mailed your answer either way."],"blocks":[{"t":"p","c":[{"t":"text","v":"Candidates can ask you to look again at a "},{"t":"term","v":"decision","key":"decision"},{"t":"text","v":". That's an "},{"t":"term","v":"appeal","key":"appeal"},{"t":"text","v":". They can also ask for an "},{"t":"term","v":"accommodation","key":"accommodation"},{"t":"text","v":", a change that makes the assessment fair for them, such as extra time."}]},{"t":"h2","c":[{"t":"text","v":"Appeals"}]},{"t":"p","c":[{"t":"text","v":"Candidates appeal from their own results page and say what went wrong: a technical problem, accessibility, an integrity review they think is unfair, a scoring error, or something else."}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Appeals"},{"t":"text","v":" under "},{"t":"ui","v":"Fairness"},{"t":"text","v":". The "},{"t":"ui","v":"Open"},{"t":"text","v":" tab lists the appeals waiting for an answer, with the candidate's reasons and the latest decision."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Evidence pack"},{"t":"text","v":" to look at the work again."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Resolve"},{"t":"text","v":", then choose "},{"t":"ui","v":"Uphold the original result"},{"t":"text","v":" or "},{"t":"ui","v":"Overturn: the appeal succeeds"},{"t":"text","v":"."}],[{"t":"text","v":"Write the "},{"t":"ui","v":"Response to the candidate (emailed to them)"},{"t":"text","v":". It needs at least 20 characters."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Resolve appeal"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Someone other than the reviewer who recorded the latest decision must answer the appeal. If that was you, ask a colleague."}]},{"t":"p","c":[{"t":"text","v":"If you overturn the result, open the "},{"t":"term","v":"evidence pack","key":"evidence-pack"},{"t":"text","v":" again and record a new decision. The earlier decision stays in the pack's history."}]},{"t":"p","c":[{"t":"text","v":"The other tabs show appeals that were "},{"t":"ui","v":"Overturned"},{"t":"text","v":", "},{"t":"ui","v":"Upheld"},{"t":"text","v":" or "},{"t":"ui","v":"Withdrawn"},{"t":"text","v":" by the candidate."}]},{"t":"h2","c":[{"t":"text","v":"Accommodations"}]},{"t":"p","c":[{"t":"text","v":"Candidates can ask for extra time, a written defense instead of a spoken one, screen-reader support, or something else."}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Accommodations"},{"t":"text","v":" under "},{"t":"ui","v":"Fairness"},{"t":"text","v":". The "},{"t":"ui","v":"Requested"},{"t":"text","v":" tab lists the requests waiting for you, with what the candidate needs and whether it's for one coding task or all of their assessments."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Approve"},{"t":"text","v":". Or write a "},{"t":"ui","v":"Note to the candidate (required to decline, at least 20 characters)"},{"t":"text","v":" and select "},{"t":"ui","v":"Decline"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The candidate is e-mailed your decision. Approved accommodations appear in the candidate's "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" packs, so reviewers read the timing and the defense fairly. An approved written defense lets the candidate defend their code in writing instead of out loud."}]}],"headings":["Appeals","Accommodations"],"text":"Candidates can ask you to look again at a decision. That's an appeal. They can also ask for an accommodation, a change that makes the assessment fair for them, such as extra time. Appeals Candidates appeal from their own results page and say what went wrong: a technical problem, accessibility, an integrity review they think is unfair, a scoring error, or something else. Open Appeals under Fairness. The Open tab lists the appeals waiting for an answer, with the candidate's reasons and the latest decision.Select Evidence pack to look at the work again.Select Resolve, then choose Uphold the original result or Overturn: the appeal succeeds.Write the Response to the candidate (emailed to them). It needs at least 20 characters.Select Resolve appeal. Someone other than the reviewer who recorded the latest decision must answer the appeal. If that was you, ask a colleague. If you overturn the result, open the evidence pack again and record a new decision. The earlier decision stays in the pack's history. The other tabs show appeals that were Overturned, Upheld or Withdrawn by the candidate. Accommodations Candidates can ask for extra time, a written defense instead of a spoken one, screen-reader support, or something else. Open Accommodations under Fairness. The Requested tab lists the requests waiting for you, with what the candidate needs and whether it's for one coding task or all of their assessments.Select Approve. Or write a Note to the candidate (required to decline, at least 20 characters) and select Decline. The candidate is e-mailed your decision. Approved accommodations appear in the candidate's evidence packs, so reviewers read the timing and the defense fairly. An approved written defense lets the candidate defend their code in writing instead of out loud."},{"slug":"recruiter-results-and-proctoring","title":"Follow results and proctored sessions","summary":"See where each candidate stands, read their scores and interview summary, record your decision, and review what happened in proctored sessions.","roles":["recruiter"],"group":"Reviewing candidates","features":["recruiter-assessments","proctoring","benchmark"],"checked":"2026-11-12","order":10,"short":["The tiles on Candidates count your candidates by review status. Select one to see only those candidates.","Scores and the AI summary are only for reference. You record each decision yourself.","Proctored sessions list events such as switching tabs, for a person to review. No one is disqualified automatically."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Where each candidate stands"}]},{"t":"p","c":[{"t":"text","v":"At the top of "},{"t":"ui","v":"Candidates"},{"t":"text","v":", the tiles count your candidates: "},{"t":"ui","v":"Awaiting review"},{"t":"text","v":", "},{"t":"ui","v":"In progress"},{"t":"text","v":", "},{"t":"ui","v":"Advanced"},{"t":"text","v":", "},{"t":"ui","v":"On hold"},{"t":"text","v":" and "},{"t":"ui","v":"Declined"},{"t":"text","v":". Select a tile to see only those candidates. Select it again, or "},{"t":"ui","v":"Show all"},{"t":"text","v":", to see everyone."}]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"ui","v":"Assessments"},{"t":"text","v":" tab lists each candidate you sent an assessment to:"}]},{"t":"ul","items":[[{"t":"ui","v":"Stage scores"},{"t":"text","v":": the written (W), coding (C) and voice (V) scores, in percent."}],[{"t":"ui","v":"Progress"},{"t":"text","v":": the stage they're on, or "},{"t":"ui","v":"All stages complete"},{"t":"text","v":", and what happened to their link."}],[{"t":"ui","v":"Composite"},{"t":"text","v":": the overall score once every stage is done. "},{"t":"ui","v":"Needs scoring"},{"t":"text","v":" means it isn't scored yet."}]]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Details"},{"t":"text","v":" to see the stage scores, an AI-written summary of the interview with the strengths and gaps it noticed, and the "},{"t":"term","v":"voice defense","key":"voice-defense"},{"t":"text","v":" transcript. All of this is for reference only."}]},{"t":"h2","c":[{"t":"text","v":"Record your decision"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Record decision"},{"t":"text","v":"."}],[{"t":"text","v":"Choose "},{"t":"ui","v":"Advanced to the next step"},{"t":"text","v":", "},{"t":"ui","v":"Hire"},{"t":"text","v":" or "},{"t":"ui","v":"Not moving forward"},{"t":"text","v":"."}],[{"t":"text","v":"Add "},{"t":"ui","v":"Notes for your team (optional)"},{"t":"text","v":" and select "},{"t":"ui","v":"Save decision"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"This records your "},{"t":"term","v":"decision","key":"decision"},{"t":"text","v":" in Edulexa. Nothing is sent to the candidate. To change it, select "},{"t":"ui","v":"Change decision"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Coding challenge submissions"}]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"ui","v":"Coding challenge submissions"},{"t":"text","v":" tab lists work handed in for your coding challenges, with the score and "},{"t":"ui","v":"Integrity signals"},{"t":"text","v":": "},{"t":"ui","v":"Signals to review"},{"t":"text","v":" or "},{"t":"ui","v":"No signals raised"},{"t":"text","v":". Signals are reasons for a conversation, not proof. Select "},{"t":"ui","v":"Evidence pack"},{"t":"text","v":" to review the work and decide. See "},{"t":"link","v":"Review an evidence pack and decide","href":"/help/recruiter-evidence-packs"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Proctored sessions"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Proctored sessions"},{"t":"text","v":" under "},{"t":"ui","v":"Review"},{"t":"text","v":". It lists proctored sessions with the events Edulexa recorded, such as switching tabs, leaving full screen, pasting text, or a camera or microphone changing. There's no gaze or face detection."}]},{"t":"p","c":[{"t":"text","v":"Each session starts with an "},{"t":"ui","v":"Integrity score"},{"t":"text","v":" of 100. Each event lowers it, by an amount set only by the kind of event. The status is "},{"t":"ui","v":"Clean"},{"t":"text","v":", "},{"t":"ui","v":"Suspicious"},{"t":"text","v":" or "},{"t":"ui","v":"Flagged"},{"t":"text","v":", and a very low score shows "},{"t":"ui","v":"Needs review"},{"t":"text","v":". No one is disqualified automatically."}]},{"t":"ol","items":[[{"t":"text","v":"Use the tabs to choose which sessions to see, for example "},{"t":"ui","v":"Needs review"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Open"},{"t":"text","v":" to see the "},{"t":"ui","v":"Session log"},{"t":"text","v":", with each event and its time."}],[{"t":"text","v":"Write "},{"t":"ui","v":"Your review (recorded with your name)"},{"t":"text","v":" and select "},{"t":"ui","v":"Record review"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The session then shows "},{"t":"ui","v":"Reviewed"},{"t":"text","v":". A "},{"t":"ui","v":"Flagged"},{"t":"text","v":" session is shown as "},{"t":"ui","v":"Suspicious"},{"t":"text","v":" from then on."}]},{"t":"h2","c":[{"t":"text","v":"Challenge results"}]},{"t":"p","c":[{"t":"ui","v":"Challenge results"},{"t":"text","v":" under "},{"t":"ui","v":"Review"},{"t":"text","v":" shows how candidates did on each coding challenge: the number of "},{"t":"ui","v":"Candidates"},{"t":"text","v":", the "},{"t":"ui","v":"Median tests passed"},{"t":"text","v":", the spread of each candidate's best result, and how many are "},{"t":"ui","v":"For review"},{"t":"text","v":". It counts graded results only: the share of hidden tests passed, or a "},{"t":"ui","v":"Mentor-adjusted score"},{"t":"text","v":"."}]}],"headings":["Where each candidate stands","Record your decision","Coding challenge submissions","Proctored sessions","Challenge results"],"text":"Where each candidate stands At the top of Candidates, the tiles count your candidates: Awaiting review, In progress, Advanced, On hold and Declined. Select a tile to see only those candidates. Select it again, or Show all, to see everyone. The Assessments tab lists each candidate you sent an assessment to: Stage scores: the written (W), coding (C) and voice (V) scores, in percent.Progress: the stage they're on, or All stages complete, and what happened to their link.Composite: the overall score once every stage is done. Needs scoring means it isn't scored yet. Select Details to see the stage scores, an AI-written summary of the interview with the strengths and gaps it noticed, and the voice defense transcript. All of this is for reference only. Record your decision Select Record decision.Choose Advanced to the next step, Hire or Not moving forward.Add Notes for your team (optional) and select Save decision. This records your decision in Edulexa. Nothing is sent to the candidate. To change it, select Change decision. Coding challenge submissions The Coding challenge submissions tab lists work handed in for your coding challenges, with the score and Integrity signals: Signals to review or No signals raised. Signals are reasons for a conversation, not proof. Select Evidence pack to review the work and decide. See Review an evidence pack and decide. Proctored sessions Open Proctored sessions under Review. It lists proctored sessions with the events Edulexa recorded, such as switching tabs, leaving full screen, pasting text, or a camera or microphone changing. There's no gaze or face detection. Each session starts with an Integrity score of 100. Each event lowers it, by an amount set only by the kind of event. The status is Clean, Suspicious or Flagged, and a very low score shows Needs review. No one is disqualified automatically. Use the tabs to choose which sessions to see, for example Needs review.Select Open to see the Session log, with each event and its time.Write Your review (recorded with your name) and select Record review. The session then shows Reviewed. A Flagged session is shown as Suspicious from then on. Challenge results Challenge results under Review shows how candidates did on each coding challenge: the number of Candidates, the Median tests passed, the spread of each candidate's best result, and how many are For review. It counts graded results only: the share of hidden tests passed, or a Mentor-adjusted score."},{"slug":"recruiter-send-an-assessment","title":"Send an assessment to a candidate","summary":"Send a candidate a link to a written exam, a coding task and a voice defense, look after the link, check a résumé against the job, and make a work trial from your own code.","roles":["recruiter"],"group":"Assessments","features":["recruiter-assessments","work-trials","coding-challenges"],"checked":"2026-11-12","order":10,"short":["On Candidates, select Send an assessment, fill in the candidate and the three stages, and select Create and get link.","The full link is shown only once. Copy it, or let Edulexa e-mail it to the candidate.","E-mail again or New link replaces a lost link. Revoke stops it working."],"blocks":[{"t":"p","c":[{"t":"text","v":"An assessment has three stages, taken in order: a written exam, a coding task, and a "},{"t":"term","v":"voice defense","key":"voice-defense"},{"t":"text","v":", where the candidate explains and defends their work out loud to an AI interviewer."}]},{"t":"h2","c":[{"t":"text","v":"Send an assessment"}]},{"t":"ol","items":[[{"t":"text","v":"On "},{"t":"ui","v":"Candidates"},{"t":"text","v":", select "},{"t":"ui","v":"Send an assessment"},{"t":"text","v":"."}],[{"t":"text","v":"Fill in the "},{"t":"ui","v":"Candidate name"},{"t":"text","v":", "},{"t":"ui","v":"Candidate email"},{"t":"text","v":", "},{"t":"ui","v":"Role"},{"t":"text","v":" and "},{"t":"ui","v":"Company or team"},{"t":"text","v":"."}],[{"t":"text","v":"Choose the "},{"t":"ui","v":"Stage 1: written exam"},{"t":"text","v":" and the "},{"t":"ui","v":"Stage 2: coding language"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Stage 3: voice defense topic"},{"t":"text","v":", write what the candidate should explain and defend."}],[{"t":"text","v":"Leave "},{"t":"ui","v":"E-mail the link to the candidate"},{"t":"text","v":" ticked if you want Edulexa to send it. It goes out in your company's name, and the candidate's replies come to you."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Create and get link"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The candidate's link appears once. For security, the full link isn't shown again, so select "},{"t":"ui","v":"Copy"},{"t":"text","v":" now if you want to send it yourself. "},{"t":"ui","v":"Preview as the candidate"},{"t":"text","v":" shows you what the candidate will see."}]},{"t":"h2","c":[{"t":"text","v":"Look after the link"}]},{"t":"p","c":[{"t":"text","v":"Each candidate's row shows the stage they're on, when their link expires, whether the e-mail arrived and when they opened it. If it says the e-mail bounced, check the address."}]},{"t":"ul","items":[[{"t":"ui","v":"E-mail again"},{"t":"text","v":" e-mails the candidate a new link."}],[{"t":"ui","v":"New link"},{"t":"text","v":" makes a new link for you to copy and send yourself."}],[{"t":"ui","v":"Revoke"},{"t":"text","v":" withdraws the link, so the candidate can't open it any more."}]]},{"t":"p","c":[{"t":"text","v":"A new link always replaces the old one, which stops working. You can e-mail a link again only once a minute, and only a few times in all."}]},{"t":"h2","c":[{"t":"text","v":"Check a résumé against the job"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"More actions"},{"t":"text","v":", then "},{"t":"ui","v":"Check a résumé"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Requirements"},{"t":"text","v":", write one requirement per line. For alternatives, write \"or\", for example \"RN or LPN\"."}],[{"t":"text","v":"Paste the "},{"t":"ui","v":"Résumé text"},{"t":"text","v":" and select "},{"t":"ui","v":"Check résumé"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"You see which requirements the résumé mentions, and the lines that mention them. There's no score, nothing is sent to an AI, and the résumé isn't saved. A mention isn't proof, so ask about each requirement in the interview."}]},{"t":"h2","c":[{"t":"text","v":"Coding challenges"}]},{"t":"p","c":[{"t":"ui","v":"New coding challenge"},{"t":"text","v":", under "},{"t":"ui","v":"More actions"},{"t":"text","v":", makes a private coding task for your company. Give it a "},{"t":"ui","v":"Challenge title"},{"t":"text","v":", a "},{"t":"ui","v":"Language"},{"t":"text","v":" and a "},{"t":"ui","v":"Problem description"},{"t":"text","v":", then select "},{"t":"ui","v":"Create challenge"},{"t":"text","v":". Edulexa shows its invite code for a moment. Candidates need this code to start a private challenge, and their work shows on the "},{"t":"ui","v":"Coding challenge submissions"},{"t":"text","v":" tab."}]},{"t":"note","c":[{"t":"text","v":"To send a candidate a link they can open straight away, use "},{"t":"ui","v":"Send an assessment"},{"t":"text","v":" or a work trial."}]},{"t":"h2","c":[{"t":"text","v":"Work trials from your own code"}]},{"t":"p","c":[{"t":"text","v":"A work trial is a private task made from a small part of your own code, with planted defects (bugs put there on purpose) and hidden tests. Open "},{"t":"ui","v":"Work trials"},{"t":"text","v":" under "},{"t":"ui","v":"Review"},{"t":"text","v":". It's marked "},{"t":"ui","v":"Beta"},{"t":"text","v":"."}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"New work trial"},{"t":"text","v":". Choose the code from a "},{"t":"ui","v":"GitHub repository"},{"t":"text","v":", or "},{"t":"ui","v":"Paste or upload files"},{"t":"text","v":"."}],[{"t":"text","v":"Fill in the "},{"t":"ui","v":"Role title"},{"t":"text","v":" and the "},{"t":"ui","v":"AI policy for candidates"},{"t":"text","v":"."}],[{"t":"text","v":"Read "},{"t":"ui","v":"How your code is handled"},{"t":"text","v":". Edulexa removes secrets and personal details before any code leaves Edulexa, then shows you everything it removed. Tick the agreement and select "},{"t":"ui","v":"Fetch and clean the code"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Generate"},{"t":"text","v":". The AI chooses a small part of the code and plants the defects. This can take a minute or two."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Validate in sandbox"},{"t":"text","v":". This checks that the hidden tests pass on your original code and catch each planted defect."}],[{"t":"text","v":"Review what the AI made, then select "},{"t":"ui","v":"Publish"},{"t":"text","v":". Share the "},{"t":"ui","v":"Candidate link"},{"t":"text","v":" or the "},{"t":"ui","v":"Invite code"},{"t":"text","v":" with candidates."}]]},{"t":"p","c":[{"t":"text","v":"A draft that isn't published is deleted after 30 days. Candidates' work arrives in "},{"t":"ui","v":"Evidence packs"},{"t":"text","v":", where a person reviews it and decides. See "},{"t":"link","v":"Review an evidence pack and decide","href":"/help/recruiter-evidence-packs"},{"t":"text","v":"."}]}],"headings":["Send an assessment","Look after the link","Check a résumé against the job","Coding challenges","Work trials from your own code"],"text":"An assessment has three stages, taken in order: a written exam, a coding task, and a voice defense, where the candidate explains and defends their work out loud to an AI interviewer. Send an assessment On Candidates, select Send an assessment.Fill in the Candidate name, Candidate email, Role and Company or team.Choose the Stage 1: written exam and the Stage 2: coding language.Under Stage 3: voice defense topic, write what the candidate should explain and defend.Leave E-mail the link to the candidate ticked if you want Edulexa to send it. It goes out in your company's name, and the candidate's replies come to you.Select Create and get link. The candidate's link appears once. For security, the full link isn't shown again, so select Copy now if you want to send it yourself. Preview as the candidate shows you what the candidate will see. Look after the link Each candidate's row shows the stage they're on, when their link expires, whether the e-mail arrived and when they opened it. If it says the e-mail bounced, check the address. E-mail again e-mails the candidate a new link.New link makes a new link for you to copy and send yourself.Revoke withdraws the link, so the candidate can't open it any more. A new link always replaces the old one, which stops working. You can e-mail a link again only once a minute, and only a few times in all. Check a résumé against the job Select More actions, then Check a résumé.Under Requirements, write one requirement per line. For alternatives, write \"or\", for example \"RN or LPN\".Paste the Résumé text and select Check résumé. You see which requirements the résumé mentions, and the lines that mention them. There's no score, nothing is sent to an AI, and the résumé isn't saved. A mention isn't proof, so ask about each requirement in the interview. Coding challenges New coding challenge, under More actions, makes a private coding task for your company. Give it a Challenge title, a Language and a Problem description, then select Create challenge. Edulexa shows its invite code for a moment. Candidates need this code to start a private challenge, and their work shows on the Coding challenge submissions tab. To send a candidate a link they can open straight away, use Send an assessment or a work trial. Work trials from your own code A work trial is a private task made from a small part of your own code, with planted defects (bugs put there on purpose) and hidden tests. Open Work trials under Review. It's marked Beta. Select New work trial. Choose the code from a GitHub repository, or Paste or upload files.Fill in the Role title and the AI policy for candidates.Read How your code is handled. Edulexa removes secrets and personal details before any code leaves Edulexa, then shows you everything it removed. Tick the agreement and select Fetch and clean the code.Select Generate. The AI chooses a small part of the code and plants the defects. This can take a minute or two.Select Validate in sandbox. This checks that the hidden tests pass on your original code and catch each planted defect.Review what the AI made, then select Publish. Share the Candidate link or the Invite code with candidates. A draft that isn't published is deleted after 30 days. Candidates' work arrives in Evidence packs, where a person reviews it and decides. See Review an evidence pack and decide."},{"slug":"reports-and-outcomes","title":"Reports and graduate outcomes","summary":"See how students use the career center, where your graduates went, and download the numbers.","roles":["staff"],"group":"Reports","features":["reports","outcomes"],"checked":"2026-11-11","order":10,"short":["Reports shows how students use your services, for a term or your own dates. Export each report or print a summary.","Outcomes shows where graduates went, where each fact came from, and how well it's verified.","Employer relations staff see the employer report only."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Reports"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Reports"},{"t":"text","v":" from the "},{"t":"ui","v":"Reports"},{"t":"text","v":" menu. Choose a report:"}]},{"t":"ul","items":[[{"t":"ui","v":"Engagement"},{"t":"text","v":": how many students used at least one service, first-time and returning, by role, graduation year, degree level and major."}],[{"t":"ui","v":"Service volume"},{"t":"text","v":": appointments, drop-in waits, group sessions, "},{"t":"term","v":"document review","key":"document-review"},{"t":"text","v":" turnaround, "},{"t":"term","v":"mentoring","key":"mentoring"},{"t":"text","v":" and internships."}],[{"t":"ui","v":"Employers"},{"t":"text","v":": requests, approved employers, and how employers took part."}],[{"t":"ui","v":"Equity view"},{"t":"text","v":": use of services by groups such as work authorization and the details students chose to share about themselves."}]]},{"t":"p","c":[{"t":"text","v":"Pick a "},{"t":"ui","v":"Term"},{"t":"text","v":", or choose "},{"t":"ui","v":"Custom dates"},{"t":"text","v":", and select "},{"t":"ui","v":"Apply"},{"t":"text","v":". Each table can show a chart or the numbers. To keep a view you use often, save it under "},{"t":"ui","v":"Save preset"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"To share the numbers, select "},{"t":"ui","v":"Export spreadsheet (CSV)"},{"t":"text","v":", or "},{"t":"ui","v":"Printable summary"},{"t":"text","v":". Small groups are hidden so no one can be picked out. A career admin sets the "},{"t":"ui","v":"Smallest group shown in the equity view"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Employer relations staff see the employer report only."}]},{"t":"h2","c":[{"t":"text","v":"Outcomes"}]},{"t":"p","c":[{"t":"ui","v":"Outcomes"},{"t":"text","v":" shows where your graduates went: a job, further study, service or still looking. Each placement shows where it came from, such as the student, the employer or your own research, and how well it's verified: "},{"t":"ui","v":"Verified by employer"},{"t":"text","v":", "},{"t":"ui","v":"Confirmed by staff"},{"t":"text","v":" or "},{"t":"ui","v":"Self-reported"},{"t":"text","v":"."}]},{"t":"ul","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Confirm"},{"t":"text","v":" when you've checked a student's own report."}],[{"t":"text","v":"Use "},{"t":"ui","v":"Add research entry"},{"t":"text","v":" to add a placement you found yourself, with where you found it. Or record that a student is still looking."}],[{"t":"text","v":"Students report their next step themselves on their "},{"t":"ui","v":"My next step"},{"t":"text","v":" page."}]]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"ui","v":"Reports"},{"t":"text","v":" tab shows, by graduation year and program, how many graduates have a known outcome and how many are placed. Select "},{"t":"ui","v":"Export spreadsheet (CSV)"},{"t":"text","v":" to download it."}]},{"t":"note","c":[{"t":"text","v":"Placement records are part of the student's record. They're never shared with employers."}]},{"t":"shot","name":"staff-reports","alt":"The career center's Reports page, with the report tabs, the filters and the export buttons","w":1600,"h":917}],"headings":["Reports","Outcomes"],"text":"Reports Open Reports from the Reports menu. Choose a report: Engagement: how many students used at least one service, first-time and returning, by role, graduation year, degree level and major.Service volume: appointments, drop-in waits, group sessions, document review turnaround, mentoring and internships.Employers: requests, approved employers, and how employers took part.Equity view: use of services by groups such as work authorization and the details students chose to share about themselves. Pick a Term, or choose Custom dates, and select Apply. Each table can show a chart or the numbers. To keep a view you use often, save it under Save preset. To share the numbers, select Export spreadsheet (CSV), or Printable summary. Small groups are hidden so no one can be picked out. A career admin sets the Smallest group shown in the equity view. Employer relations staff see the employer report only. Outcomes Outcomes shows where your graduates went: a job, further study, service or still looking. Each placement shows where it came from, such as the student, the employer or your own research, and how well it's verified: Verified by employer, Confirmed by staff or Self-reported. Select Confirm when you've checked a student's own report.Use Add research entry to add a placement you found yourself, with where you found it. Or record that a student is still looking.Students report their next step themselves on their My next step page. The Reports tab shows, by graduation year and program, how many graduates have a known outcome and how many are placed. Select Export spreadsheet (CSV) to download it. Placement records are part of the student's record. They're never shared with employers."},{"slug":"resumes","title":"Your résumé library","summary":"Keep your résumés in one place, add new versions, and send one with a job application, a document review or an interview sign-up.","roles":["student","alumni"],"group":"Jobs and internships","features":["resumes"],"checked":"2026-11-11","order":10,"short":["In Résumés, select Upload résumé (PDF or Word, up to 5 MB), or Build a résumé.","When it changes, select Upload a new version. The newest version is the one you send.","Job applications, document reviews and interview sign-ups take résumés From your library."],"blocks":[{"t":"p","c":[{"t":"link","v":"Résumés","href":"/resumes"},{"t":"text","v":" keeps all your résumés in one place."}]},{"t":"h2","c":[{"t":"text","v":"Add a résumé"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Upload résumé"},{"t":"text","v":" and choose a PDF or Word (.docx) file, up to 5 MB. Edulexa reads its text. If it can't (a scanned page, for example), the résumé shows "},{"t":"ui","v":"Couldn't read text"},{"t":"text","v":". You can still send it as it is."}]},{"t":"p","c":[{"t":"text","v":"Or select "},{"t":"ui","v":"Build a résumé"},{"t":"text","v":", then "},{"t":"ui","v":"Start from your record"},{"t":"text","v":" or "},{"t":"ui","v":"Start blank"},{"t":"text","v":". Edulexa lays it out and makes the PDF. Lines from your verified results print with a Verified mark."}]},{"t":"shot","name":"resumes-library","alt":"The Résumés page, with the Upload résumé button at the top","w":1600,"h":947},{"t":"h2","c":[{"t":"text","v":"Keep it up to date"}]},{"t":"ul","items":[[{"t":"ui","v":"Upload a new version"},{"t":"text","v":" when you change it. The newest version is the one you send. Older ones are kept: "},{"t":"ui","v":"Versions and where they went"},{"t":"text","v":" lists them and where you sent each one."}],[{"t":"ui","v":"AI feedback"},{"t":"text","v":" suggests stronger lines. They're only suggestions: change what helps, in your own words."}],[{"t":"ui","v":"Archive"},{"t":"text","v":" puts away one you don't use; restore it from "},{"t":"ui","v":"Archived"},{"t":"text","v":" at any time."}]]},{"t":"p","c":[{"t":"text","v":"To see how well a résumé fits a job posting, select "},{"t":"ui","v":"Check against a job"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Use it when you apply"}]},{"t":"p","c":[{"t":"link","v":"Job applications","href":"/help/campus-jobs-and-interviews"},{"t":"text","v":", "},{"t":"link","v":"document reviews","href":"/help/document-review"},{"t":"text","v":" and interview sign-ups offer "},{"t":"ui","v":"From your library"},{"t":"text","v":". Each keeps its own copy of the version you send. A résumé you upload in one of those forms is saved to your library too."}]},{"t":"p","c":[{"t":"text","v":"Some schools take only résumés the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" approved. Send yours for "},{"t":"link","v":"document review","href":"/help/document-review"},{"t":"text","v":" first. Once it's approved, it shows "},{"t":"ui","v":"Approved by your school"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"If your school has a "},{"t":"term","v":"résumé book","key":"resume-book"},{"t":"text","v":", select "},{"t":"ui","v":"Add to the résumé book"},{"t":"text","v":" at the bottom of the page. Employers your school approved can then find your résumé, and you see how often they open it. You can "},{"t":"ui","v":"Leave the résumé book"},{"t":"text","v":" at any time."}]},{"t":"note","c":[{"t":"text","v":"If your school uses another résumé tool, its forms don't take résumés from here. Your library still works for everything else."}]}],"headings":["Add a résumé","Keep it up to date","Use it when you apply"],"text":"Résumés keeps all your résumés in one place. Add a résumé Select Upload résumé and choose a PDF or Word (.docx) file, up to 5 MB. Edulexa reads its text. If it can't (a scanned page, for example), the résumé shows Couldn't read text. You can still send it as it is. Or select Build a résumé, then Start from your record or Start blank. Edulexa lays it out and makes the PDF. Lines from your verified results print with a Verified mark. Keep it up to date Upload a new version when you change it. The newest version is the one you send. Older ones are kept: Versions and where they went lists them and where you sent each one.AI feedback suggests stronger lines. They're only suggestions: change what helps, in your own words.Archive puts away one you don't use; restore it from Archived at any time. To see how well a résumé fits a job posting, select Check against a job. Use it when you apply Job applications, document reviews and interview sign-ups offer From your library. Each keeps its own copy of the version you send. A résumé you upload in one of those forms is saved to your library too. Some schools take only résumés the career center approved. Send yours for document review first. Once it's approved, it shows Approved by your school. If your school has a résumé book, select Add to the résumé book at the bottom of the page. Employers your school approved can then find your résumé, and you see how often they open it. You can Leave the résumé book at any time. If your school uses another résumé tool, its forms don't take résumés from here. Your library still works for everything else."},{"slug":"sign-in","title":"Sign in and sign out","summary":"Sign in with your e-mail and password or your school's own sign-in, get back in if you forgot your password, and sign out.","roles":["everyone"],"group":"Account and settings","features":["sign-in","university-sso"],"checked":"2026-11-11","order":10,"short":["Enter your e-mail, select Continue, then enter your password.","Forgot it? Select Forgot Password? on the password step and follow the e-mail.","To sign out, open your account menu (your initials, top right) and select Sign out."],"blocks":[{"t":"p","c":[{"t":"text","v":"The sign-in page opens when you select "},{"t":"ui","v":"Sign in"},{"t":"text","v":", or by itself when a page needs you to be signed in."}]},{"t":"h2","c":[{"t":"text","v":"Sign in"}]},{"t":"ol","items":[[{"t":"text","v":"Enter your e-mail address and select "},{"t":"b","v":"Continue"},{"t":"text","v":"."}],[{"t":"text","v":"Enter your password and select "},{"t":"b","v":"Sign In"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"On your own computer, tick "},{"t":"b","v":"Remember me"},{"t":"text","v":" to stay signed in longer. Leave it off on a shared computer."}]},{"t":"p","c":[{"t":"text","v":"Students sign in with the e-mail address their school put on the class list. If you were invited, use the e-mail address the invitation was sent to."}]},{"t":"h2","c":[{"t":"text","v":"If your school or company has its own sign-in"}]},{"t":"p","c":[{"t":"text","v":"Enter your school or work e-mail. If your school or company has connected its own sign-in, you're taken there, and then back to Edulexa."}]},{"t":"h2","c":[{"t":"text","v":"If you forgot your password"}]},{"t":"p","c":[{"t":"text","v":"On the password step, select "},{"t":"b","v":"Forgot Password?"},{"t":"text","v":", enter your e-mail and select "},{"t":"b","v":"Send reset link"},{"t":"text","v":". The link in the e-mail works for 15 minutes. Your new password needs at least 12 characters, can't be your e-mail, and can't be one of your last five."}]},{"t":"h2","c":[{"t":"text","v":"If you still can't sign in"}]},{"t":"ul","items":[[{"t":"text","v":"After 10 wrong passwords, sign-in is paused for a minute, and longer if it happens again (up to 15 minutes). Wait, then try again."}],[{"t":"text","v":"If the page says it has expired, select "},{"t":"b","v":"Start again"},{"t":"text","v":"."}],[{"t":"text","v":"Staff accounts also need a code from an authenticator app. If you see "},{"t":"ui","v":"Two-step sign-in is needed for your role"},{"t":"text","v":", select "},{"t":"ui","v":"Sign in again"},{"t":"text","v":" and set it up. It takes about a minute."}],[{"t":"text","v":"Still stuck? See "},{"t":"link","v":"Get help and contact support","href":"/help/help-and-support"},{"t":"text","v":"."}]]},{"t":"h2","c":[{"t":"text","v":"Sign out"}]},{"t":"p","c":[{"t":"text","v":"Open your account menu (the circle with your initials, top right) and select "},{"t":"ui","v":"Sign out"},{"t":"text","v":". This also signs you out of the other apps that use the same account in this browser."}]}],"headings":["Sign in","If your school or company has its own sign-in","If you forgot your password","If you still can't sign in","Sign out"],"text":"The sign-in page opens when you select Sign in, or by itself when a page needs you to be signed in. Sign in Enter your e-mail address and select Continue.Enter your password and select Sign In. On your own computer, tick Remember me to stay signed in longer. Leave it off on a shared computer. Students sign in with the e-mail address their school put on the class list. If you were invited, use the e-mail address the invitation was sent to. If your school or company has its own sign-in Enter your school or work e-mail. If your school or company has connected its own sign-in, you're taken there, and then back to Edulexa. If you forgot your password On the password step, select Forgot Password?, enter your e-mail and select Send reset link. The link in the e-mail works for 15 minutes. Your new password needs at least 12 characters, can't be your e-mail, and can't be one of your last five. If you still can't sign in After 10 wrong passwords, sign-in is paused for a minute, and longer if it happens again (up to 15 minutes). Wait, then try again.If the page says it has expired, select Start again.Staff accounts also need a code from an authenticator app. If you see Two-step sign-in is needed for your role, select Sign in again and set it up. It takes about a minute.Still stuck? See Get help and contact support. Sign out Open your account menu (the circle with your initials, top right) and select Sign out. This also signs you out of the other apps that use the same account in this browser."},{"slug":"staff-document-review","title":"Review students' résumés and documents","summary":"Pick up a student's résumé, cover letter or statement, comment on it, and return it with your feedback.","roles":["staff"],"group":"Documents and résumés","features":["document-review"],"checked":"2026-11-11","order":10,"short":["Open Document review, claim a request and start the review.","Comment on passages, rate the checklist, and write an overall summary.","Return it to the student. They're told and can send a new version."],"blocks":[{"t":"p","c":[{"t":"text","v":"Students send a résumé, cover letter, personal statement or LinkedIn summary for review. Their requests wait in "},{"t":"ui","v":"Document review"},{"t":"text","v":" for counselors and "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" admins."}]},{"t":"h2","c":[{"t":"text","v":"Pick up a request"}]},{"t":"p","c":[{"t":"text","v":"On "},{"t":"ui","v":"Queue"},{"t":"text","v":", filter by "},{"t":"ui","v":"Status"},{"t":"text","v":", "},{"t":"ui","v":"Document type"},{"t":"text","v":", "},{"t":"ui","v":"Assignee"},{"t":"text","v":" or "},{"t":"ui","v":"Waiting at least (days)"},{"t":"text","v":", or tick "},{"t":"ui","v":"Overdue only"},{"t":"text","v":". Open a request, select "},{"t":"ui","v":"Claim"},{"t":"text","v":", then "},{"t":"ui","v":"Start review"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Once a request is yours, you can hand it to a colleague with "},{"t":"ui","v":"Assign to"},{"t":"text","v":". Career admins can assign any request. Use "},{"t":"ui","v":"Mark urgent"},{"t":"text","v":" when the student's deadline is close."}]},{"t":"h2","c":[{"t":"text","v":"Write your review"}]},{"t":"ul","items":[[{"t":"text","v":"Select a passage in the submitted text and choose "},{"t":"ui","v":"Comment on selection"},{"t":"text","v":", or write a "},{"t":"ui","v":"General comment"},{"t":"text","v":". Then select "},{"t":"ui","v":"Add comment"},{"t":"text","v":"."}],[{"t":"text","v":"Rate each line of the "},{"t":"ui","v":"Checklist"},{"t":"text","v":": "},{"t":"ui","v":"Strong"},{"t":"text","v":", "},{"t":"ui","v":"Satisfactory"},{"t":"text","v":", "},{"t":"ui","v":"Needs work"},{"t":"text","v":" or "},{"t":"ui","v":"Not applicable"},{"t":"text","v":"."}],[{"t":"text","v":"Write the "},{"t":"ui","v":"Overall summary"},{"t":"text","v":". You need it before you can return the review, and the student sees it exactly as you write it."}],[{"t":"text","v":"If you like, upload a marked-up copy under "},{"t":"ui","v":"Annotated file"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Save draft"},{"t":"text","v":" to finish later, or "},{"t":"ui","v":"Return to student"},{"t":"text","v":". The student is told and can send a new version. Earlier versions stay on the page, with your comments."}]},{"t":"p","c":[{"t":"text","v":"If your school asks for an approved résumé for campus applications, you'll see "},{"t":"ui","v":"Approve this résumé"},{"t":"text","v":" when you return one. Tick it to approve that version."}]},{"t":"h2","c":[{"t":"text","v":"Metrics and settings"}]},{"t":"p","c":[{"t":"ui","v":"Metrics"},{"t":"text","v":" shows how many reviews each reviewer returned, how fast, how many were on time, and how students rated them. Select "},{"t":"ui","v":"Export spreadsheet (CSV)"},{"t":"text","v":" to download it. Career admins set the review target and the checklists under "},{"t":"ui","v":"Settings"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"Reviews are part of the student's education record. They're never shared with employers."}]},{"t":"shot","name":"staff-document-review-queue","alt":"The document review queue, with each student's document, how long it has waited, when it's due and its reviewer","w":1600,"h":688}],"headings":["Pick up a request","Write your review","Metrics and settings"],"text":"Students send a résumé, cover letter, personal statement or LinkedIn summary for review. Their requests wait in Document review for counselors and career center admins. Pick up a request On Queue, filter by Status, Document type, Assignee or Waiting at least (days), or tick Overdue only. Open a request, select Claim, then Start review. Once a request is yours, you can hand it to a colleague with Assign to. Career admins can assign any request. Use Mark urgent when the student's deadline is close. Write your review Select a passage in the submitted text and choose Comment on selection, or write a General comment. Then select Add comment.Rate each line of the Checklist: Strong, Satisfactory, Needs work or Not applicable.Write the Overall summary. You need it before you can return the review, and the student sees it exactly as you write it.If you like, upload a marked-up copy under Annotated file. Select Save draft to finish later, or Return to student. The student is told and can send a new version. Earlier versions stay on the page, with your comments. If your school asks for an approved résumé for campus applications, you'll see Approve this résumé when you return one. Tick it to approve that version. Metrics and settings Metrics shows how many reviews each reviewer returned, how fast, how many were on time, and how students rated them. Select Export spreadsheet (CSV) to download it. Career admins set the review target and the checklists under Settings. Reviews are part of the student's education record. They're never shared with employers."},{"slug":"classes-and-rosters","title":"Create a class and import its roster","summary":"Make a class, bring in its students from a spreadsheet, and add a co-teacher.","roles":["teacher","admin"],"group":"People and classes","features":["class-assessments"],"checked":"2026-11-11","order":11,"short":[],"blocks":[{"t":"h2","c":[{"t":"text","v":"Create a class"}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Classes"},{"t":"text","v":" and find "},{"t":"ui","v":"New class"},{"t":"text","v":"."}],[{"t":"text","v":"Enter the "},{"t":"ui","v":"Class name"},{"t":"text","v":", for example \"CS 341, Fall 2026\". The program and graduation year are optional."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Create class"},{"t":"text","v":". You're the class's owner."}]]},{"t":"shot","name":"class-roster","alt":"The New class form on the Classes page, with the class name, program and graduation year","w":592,"h":540},{"t":"h2","c":[{"t":"text","v":"Import the roster"}]},{"t":"p","c":[{"t":"text","v":"On the class page, use "},{"t":"ui","v":"Import roster"},{"t":"text","v":". Either choose a "},{"t":"ui","v":"Spreadsheet (CSV file)"},{"t":"text","v":" or use "},{"t":"ui","v":"Or paste the rows"},{"t":"text","v":", then select "},{"t":"ui","v":"Import"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"The file needs a header row with these columns:"}]},{"t":"ul","items":[[{"t":"code","v":"name"},{"t":"text","v":" and "},{"t":"code","v":"email"},{"t":"text","v":" (required)"}],[{"t":"code","v":"roll_number"},{"t":"text","v":" and "},{"t":"code","v":"branch"},{"t":"text","v":" (optional)"}]]},{"t":"p","c":[{"t":"text","v":"For example:"}]},{"t":"p","c":[{"t":"code","v":"name,email,roll_number"}]},{"t":"p","c":[{"t":"code","v":"Priya Raman,priya@college.edu,CS-101"}]},{"t":"p","c":[{"t":"text","v":"If any row has a problem, nothing is imported and each problem is listed with its row number, so you can fix the file and import again. Files can be up to 5 MB."}]},{"t":"p","c":[{"t":"text","v":"Students sign in with the e-mail address on the roster. The class shows who has signed in."}]},{"t":"h2","c":[{"t":"text","v":"Add a co-teacher"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Add a co-teacher"},{"t":"text","v":", pick a teacher at your school who has already signed in, and select "},{"t":"ui","v":"Add teacher"},{"t":"text","v":". Co-teachers see the class's students and work, and can review and decide."}]},{"t":"note","c":[{"t":"text","v":"To give the class an assessment, use "},{"t":"ui","v":"Give this class an assessment"},{"t":"text","v":" on the class page. See "},{"t":"link","v":"Give an assessment to a class","href":"/help/give-to-a-class"},{"t":"text","v":"."}]}],"headings":["Create a class","Import the roster","Add a co-teacher"],"text":"Create a class Open Classes and find New class.Enter the Class name, for example \"CS 341, Fall 2026\". The program and graduation year are optional.Select Create class. You're the class's owner. Import the roster On the class page, use Import roster. Either choose a Spreadsheet (CSV file) or use Or paste the rows, then select Import. The file needs a header row with these columns: name and email (required)roll_number and branch (optional) For example: name,email,roll_number Priya Raman,priya@college.edu,CS-101 If any row has a problem, nothing is imported and each problem is listed with its row number, so you can fix the file and import again. Files can be up to 5 MB. Students sign in with the e-mail address on the roster. The class shows who has signed in. Add a co-teacher Under Add a co-teacher, pick a teacher at your school who has already signed in, and select Add teacher. Co-teachers see the class's students and work, and can review and decide. To give the class an assessment, use Give this class an assessment on the class page. See Give an assessment to a class."},{"slug":"ask-edulexa","title":"Ask Edulexa or find a mentor","summary":"Ask Edulexa's advisors a question about your career, follow their replies, and find a free mentor in the Edulexa community.","roles":["member"],"group":"Guidance","features":["guidance-desk","mentoring"],"checked":"2026-11-12","order":20,"short":["On the Counseling quiz page, select Ask Edulexa, fill in the short form and send it. You don't need to take the quiz first.","Replies come in My guidance requests and by e-mail. You can answer in either place.","For a mentor, open Mentoring and select Join the community. Mentoring there is free."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Ask Edulexa"}]},{"t":"p","c":[{"t":"text","v":"Not sure which area, course or certification is right for you? Ask a person."}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Counseling quiz"},{"t":"text","v":" from the "},{"t":"ui","v":"Guidance"},{"t":"text","v":" menu. You don't need to take the quiz first."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Ask Edulexa"},{"t":"text","v":"."}],[{"t":"text","v":"Fill in the short form. If you've taken the quiz, you can tick "},{"t":"ui","v":"Also share my latest quiz answers and result (optional)."}],[{"t":"text","v":"Send it."}]]},{"t":"p","c":[{"t":"text","v":"Edulexa's advisors read every request. Some are passed to a community "},{"t":"term","v":"mentor","key":"mentoring"},{"t":"text","v":" who knows the area. Nothing goes to an institute unless you approve it."}]},{"t":"p","c":[{"t":"text","v":"Prefer to ask a particular institute? Select "},{"t":"ui","v":"Talk to a specific institute"},{"t":"text","v":", then the institute's button to ask them. An advisor there contacts you by e-mail."}]},{"t":"h2","c":[{"t":"text","v":"Follow the replies"}]},{"t":"p","c":[{"t":"ui","v":"My guidance requests"},{"t":"text","v":" lists each question you've asked, with its replies and where it stands."}]},{"t":"ul","items":[[{"t":"text","v":"Write back in the box under a request and select "},{"t":"ui","v":"Send"},{"t":"text","v":", or reply to our e-mail. Both end up in the same place."}],[{"t":"text","v":"If an advisor thinks an institute could help, the request says so. Select "},{"t":"ui","v":"Yes, send it"},{"t":"text","v":" to send them your request, or "},{"t":"ui","v":"No, thanks"},{"t":"text","v":"."}],[{"t":"text","v":"To ask about something else, select "},{"t":"ui","v":"Ask something new"},{"t":"text","v":"."}]]},{"t":"h2","c":[{"t":"text","v":"Find a mentor"}]},{"t":"p","c":[{"t":"ui","v":"Mentoring"},{"t":"text","v":" in the "},{"t":"ui","v":"Guidance"},{"t":"text","v":" menu is free mentoring from people in the Edulexa community. The Edulexa team reviews every mentor before you can see them."}]},{"t":"ol","items":[[{"t":"text","v":"Mentors and mentees reach each other by e-mail, so your account needs a verified e-mail address first."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Join the community"},{"t":"text","v":", then "},{"t":"ui","v":"Open mentoring"},{"t":"text","v":"."}],[{"t":"text","v":"Say what you'd like help with, see the mentors who match and why, and ask one. A mentor accepts before you share contact details."}]]},{"t":"p","c":[{"t":"text","v":"How it works once you're matched is in "},{"t":"link","v":"Find a mentor","href":"/help/mentoring"},{"t":"text","v":"."}]},{"t":"h3","c":[{"t":"text","v":"Become a mentor"}]},{"t":"p","c":[{"t":"text","v":"Have experience to share? Select "},{"t":"ui","v":"Apply to mentor"},{"t":"text","v":" and fill in your mentor profile. You choose your topics, how you meet and how many mentees you take. The Edulexa team reviews your profile before members can see it."}]}],"headings":["Ask Edulexa","Follow the replies","Find a mentor","Become a mentor"],"text":"Ask Edulexa Not sure which area, course or certification is right for you? Ask a person. Open Counseling quiz from the Guidance menu. You don't need to take the quiz first.Select Ask Edulexa.Fill in the short form. If you've taken the quiz, you can tick Also share my latest quiz answers and result (optional).Send it. Edulexa's advisors read every request. Some are passed to a community mentor who knows the area. Nothing goes to an institute unless you approve it. Prefer to ask a particular institute? Select Talk to a specific institute, then the institute's button to ask them. An advisor there contacts you by e-mail. Follow the replies My guidance requests lists each question you've asked, with its replies and where it stands. Write back in the box under a request and select Send, or reply to our e-mail. Both end up in the same place.If an advisor thinks an institute could help, the request says so. Select Yes, send it to send them your request, or No, thanks.To ask about something else, select Ask something new. Find a mentor Mentoring in the Guidance menu is free mentoring from people in the Edulexa community. The Edulexa team reviews every mentor before you can see them. Mentors and mentees reach each other by e-mail, so your account needs a verified e-mail address first.Select Join the community, then Open mentoring.Say what you'd like help with, see the mentors who match and why, and ask one. A mentor accepts before you share contact details. How it works once you're matched is in Find a mentor. Become a mentor Have experience to share? Select Apply to mentor and fill in your mentor profile. You choose your topics, how you meet and how many mentees you take. The Edulexa team reviews your profile before members can see it."},{"slug":"campus-jobs-and-interviews","title":"Campus jobs and interviews","summary":"Find jobs employers offer through your school, apply, follow each round, answer an offer, and sign up for on-campus interviews.","roles":["student","alumni"],"group":"Jobs and internships","features":["campus-drives","campus-interviews"],"checked":"2026-11-11","order":20,"short":["The Job board lists jobs your school approved. Select Details and apply, attach your documents, and select Apply.","Follow your rounds and offers under My applications.","Book interview times under Interviews, then Find interviews."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Find a job"}]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"link","v":"Job board","href":"/student/jobs"},{"t":"text","v":" lists the jobs and internships employers offer through your school (campus drives) that your school has approved. Each one is checked against your academic record: "},{"t":"ui","v":"Eligible"},{"t":"text","v":", "},{"t":"ui","v":"Not eligible"},{"t":"text","v":" with the reasons, or "},{"t":"ui","v":"Data missing"},{"t":"text","v":". If your record is wrong, ask your school to correct it."}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Details and apply"},{"t":"text","v":" to see the description, who can apply, and the rounds."}]},{"t":"h2","c":[{"t":"text","v":"Apply"}]},{"t":"ol","items":[[{"t":"text","v":"Attach the documents it asks for: tick files you uploaded before, a résumé "},{"t":"ui","v":"From your library"},{"t":"text","v":", or choose a "},{"t":"ui","v":"Document type"},{"t":"text","v":" and upload a new file."}],[{"t":"text","v":"If the employer is named, tick the box to agree to share your details and documents with it."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Apply"},{"t":"text","v":" (some say "},{"t":"ui","v":"Opt in"},{"t":"text","v":")."}]]},{"t":"p","c":[{"t":"text","v":"Follow it under "},{"t":"link","v":"My applications","href":"/student/jobs/applications"},{"t":"text","v":": each round's result, your interview times and any offer. While it's "},{"t":"ui","v":"Applied"},{"t":"text","v":" or "},{"t":"ui","v":"In selection"},{"t":"text","v":", you can select "},{"t":"ui","v":"Withdraw application"},{"t":"text","v":". That stops sharing your details with the employer."}]},{"t":"h2","c":[{"t":"text","v":"If you get an offer"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Accept"},{"t":"text","v":" or "},{"t":"ui","v":"Decline"},{"t":"text","v":" before the date shown. If you already accepted another offer, "},{"t":"ui","v":"Accept and release my earlier offer"},{"t":"text","v":" declines the earlier one. Some offers come with a letter to sign: type your full name and select "},{"t":"ui","v":"Sign and accept"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Sign up for on-campus interviews"}]},{"t":"p","c":[{"t":"link","v":"Interviews","href":"/student/interviews"},{"t":"text","v":" lists interviews employers hold at your school, for students who meet their requirements or are invited."}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"Find interviews"},{"t":"text","v":", select "},{"t":"ui","v":"Sign up"},{"t":"text","v":"."}],[{"t":"text","v":"Choose an "},{"t":"ui","v":"Interview time"},{"t":"text","v":". Times are in your school's time zone."}],[{"t":"text","v":"The first time with an employer, choose a résumé to share and agree to share your details."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Book this time"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"No time left? Select "},{"t":"ui","v":"Join alternate list"},{"t":"text","v":": you're booked automatically if a time opens up. Your bookings are under "},{"t":"ui","v":"My interviews"},{"t":"text","v":", where you can "},{"t":"ui","v":"Cancel interview"},{"t":"text","v":" until the time shown."}]},{"t":"note","c":[{"t":"text","v":"If you miss too many interviews, new sign-ups are paused until the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" clears it."}]}],"headings":["Find a job","Apply","If you get an offer","Sign up for on-campus interviews"],"text":"Find a job The Job board lists the jobs and internships employers offer through your school (campus drives) that your school has approved. Each one is checked against your academic record: Eligible, Not eligible with the reasons, or Data missing. If your record is wrong, ask your school to correct it. Select Details and apply to see the description, who can apply, and the rounds. Apply Attach the documents it asks for: tick files you uploaded before, a résumé From your library, or choose a Document type and upload a new file.If the employer is named, tick the box to agree to share your details and documents with it.Select Apply (some say Opt in). Follow it under My applications: each round's result, your interview times and any offer. While it's Applied or In selection, you can select Withdraw application. That stops sharing your details with the employer. If you get an offer Select Accept or Decline before the date shown. If you already accepted another offer, Accept and release my earlier offer declines the earlier one. Some offers come with a letter to sign: type your full name and select Sign and accept. Sign up for on-campus interviews Interviews lists interviews employers hold at your school, for students who meet their requirements or are invited. Under Find interviews, select Sign up.Choose an Interview time. Times are in your school's time zone.The first time with an employer, choose a résumé to share and agree to share your details.Select Book this time. No time left? Select Join alternate list: you're booked automatically if a time opens up. Your bookings are under My interviews, where you can Cancel interview until the time shown. If you miss too many interviews, new sign-ups are paused until the career center clears it."},{"slug":"caseload","title":"Your caseload and following up","summary":"See the students assigned to you, why some may need a check-in, and record when you've followed up.","roles":["staff"],"group":"Students and appointments","features":["caseload"],"checked":"2026-11-11","order":20,"short":["Caseload lists your students and flags the ones who may need a check-in, with the reason.","Select a student, follow up, then use \"Mark contacted\" so colleagues can see it.","Signals never decide anything, and students don't see them."],"blocks":[{"t":"p","c":[{"t":"ui","v":"Caseload"},{"t":"text","v":" is for counselors and "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" admins. It lists your students and flags the ones who may need a check-in. Each flag is a "},{"t":"b","v":"signal"},{"t":"text","v":": a simple rule, such as a final-year student with no recent appointment, a message nobody has answered, a returned "},{"t":"term","v":"document review","key":"document-review"},{"t":"text","v":" the student hasn't acted on, or an internship agreement that isn't signed yet."}]},{"t":"h2","c":[{"t":"text","v":"Find students"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Filters"},{"t":"text","v":", choose "},{"t":"ui","v":"My caseload"},{"t":"text","v":", "},{"t":"ui","v":"All students"},{"t":"text","v":", "},{"t":"ui","v":"Unassigned pool"},{"t":"text","v":" or a colleague's caseload. You can narrow the list by "},{"t":"ui","v":"Signal"},{"t":"text","v":" or "},{"t":"ui","v":"Minimum severity"},{"t":"text","v":", and sort it by "},{"t":"ui","v":"Highest severity"},{"t":"text","v":", "},{"t":"ui","v":"Number of signals"},{"t":"text","v":", "},{"t":"ui","v":"Name"},{"t":"text","v":" or "},{"t":"ui","v":"Graduation date"},{"t":"text","v":". Select a student to see their signals and "},{"t":"ui","v":"Recent activity"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Follow up"}]},{"t":"ul","items":[[{"t":"text","v":"Most signals link to the page they come from, for example the student's internship."}],[{"t":"text","v":"After you've been in touch, use "},{"t":"ui","v":"Mark contacted"},{"t":"text","v":": choose "},{"t":"ui","v":"How"},{"t":"text","v":", add a note if you like, and select "},{"t":"ui","v":"Save"},{"t":"text","v":"."}],[{"t":"text","v":"To hide a signal for a while, select "},{"t":"ui","v":"Snooze…"},{"t":"text","v":" and give the number of days and a reason. Snoozes are recorded."}],[{"t":"text","v":"If your school has turned on the AI copilot, "},{"t":"ui","v":"Appointment prep brief"},{"t":"text","v":" sums up the student before a meeting, and "},{"t":"ui","v":"Draft outreach message"},{"t":"text","v":" writes a message for you to edit. Nothing is sent until you tick "},{"t":"ui","v":"I reviewed this message and want to send it"},{"t":"text","v":" and select "},{"t":"ui","v":"Send via messaging"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Notes about a meeting go on the appointment itself. See "},{"t":"link","v":"Set your availability and manage appointments","href":"/help/appointments-and-availability"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Who is in your caseload"}]},{"t":"p","c":[{"t":"text","v":"Career admins assign students with "},{"t":"ui","v":"Caseload rules"},{"t":"text","v":", by major, college or last-name range, or one by one. Students no rule matches stay in the unassigned pool. Admins also set when each signal appears, and turn the copilot on or off, in "},{"t":"ui","v":"Signal & copilot settings"},{"t":"text","v":"."}]}],"headings":["Find students","Follow up","Who is in your caseload"],"text":"Caseload is for counselors and career center admins. It lists your students and flags the ones who may need a check-in. Each flag is a signal: a simple rule, such as a final-year student with no recent appointment, a message nobody has answered, a returned document review the student hasn't acted on, or an internship agreement that isn't signed yet. Find students Under Filters, choose My caseload, All students, Unassigned pool or a colleague's caseload. You can narrow the list by Signal or Minimum severity, and sort it by Highest severity, Number of signals, Name or Graduation date. Select a student to see their signals and Recent activity. Follow up Most signals link to the page they come from, for example the student's internship.After you've been in touch, use Mark contacted: choose How, add a note if you like, and select Save.To hide a signal for a while, select Snooze… and give the number of days and a reason. Snoozes are recorded.If your school has turned on the AI copilot, Appointment prep brief sums up the student before a meeting, and Draft outreach message writes a message for you to edit. Nothing is sent until you tick I reviewed this message and want to send it and select Send via messaging. Notes about a meeting go on the appointment itself. See Set your availability and manage appointments. Who is in your caseload Career admins assign students with Caseload rules, by major, college or last-name range, or one by one. Students no rule matches stay in the unassigned pool. Admins also set when each signal appears, and turn the copilot on or off, in Signal & copilot settings."},{"slug":"counseling-quiz","title":"The counseling quiz and your courses","summary":"Change the quiz questions your members answer, list the courses suggested with their results, and see who asked about a course.","roles":["admissions"],"group":"Forms and the quiz","features":["counselling-quiz"],"checked":"2026-11-12","order":20,"short":["The counseling quiz suggests a career area to your members. It uses Edulexa's standard questions until you save your own.","Under Courses, add the courses you want suggested with each area. Only courses marked Shown to members are suggested.","Inquiries lists the members who asked about a course. They're in your admissions leads too."],"blocks":[{"t":"p","c":[{"t":"text","v":"The counseling quiz asks your members a few questions and suggests the career area that fits them best, with your courses for that area. Open "},{"t":"ui","v":"Counseling quiz"},{"t":"text","v":" under "},{"t":"ui","v":"Forms"},{"t":"text","v":". The page has three tabs: "},{"t":"ui","v":"Questions"},{"t":"text","v":", "},{"t":"ui","v":"Courses"},{"t":"text","v":" and "},{"t":"ui","v":"Inquiries"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Questions"}]},{"t":"p","c":[{"t":"text","v":"Each member answers a set of questions drawn at random from your list. The top of the tab says how many questions are in use and how many each member answers."}]},{"t":"p","c":[{"t":"text","v":"Until you save your own, your institute uses Edulexa's standard questions. To change them:"}]},{"t":"ol","items":[[{"t":"text","v":"Change a "},{"t":"ui","v":"Question"},{"t":"text","v":", or select "},{"t":"ui","v":"Add a question"},{"t":"text","v":"."}],[{"t":"text","v":"For each answer, choose its area under "},{"t":"ui","v":"Points to area"},{"t":"text","v":" and its "},{"t":"ui","v":"Weight"},{"t":"text","v":". Select "},{"t":"ui","v":"Answer"},{"t":"text","v":" under the answers to add another."}],[{"t":"text","v":"Untick "},{"t":"ui","v":"In use"},{"t":"text","v":" to leave a question out without deleting it, or select "},{"t":"ui","v":"Delete"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Save"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Members never see the areas or the weights. Give every area the same number of answers and weights, so the quiz doesn't favor one."}]},{"t":"p","c":[{"t":"text","v":"To go back to Edulexa's standard questions, select "},{"t":"b","v":"Use Edulexa's standard questions"},{"t":"text","v":". Your own questions are removed."}]},{"t":"h2","c":[{"t":"text","v":"Courses"}]},{"t":"p","c":[{"t":"text","v":"Your courses are suggested to your members with their quiz results, best match first. Select "},{"t":"ui","v":"Add a course"},{"t":"text","v":", then fill in its "},{"t":"ui","v":"Name"},{"t":"text","v":", "},{"t":"ui","v":"Description"},{"t":"text","v":" and "},{"t":"ui","v":"Area (matched to quiz results)"},{"t":"text","v":", and, if you like, its "},{"t":"ui","v":"Qualification"},{"t":"text","v":", "},{"t":"ui","v":"Length"},{"t":"text","v":", "},{"t":"ui","v":"Next intake"},{"t":"text","v":" and highlights. Tick "},{"t":"ui","v":"Shown to members"},{"t":"text","v":" and select "},{"t":"ui","v":"Save course"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Each course shows "},{"t":"ui","v":"Shown"},{"t":"text","v":" or "},{"t":"ui","v":"Hidden"},{"t":"text","v":". Select "},{"t":"ui","v":"Edit"},{"t":"text","v":" or "},{"t":"ui","v":"Remove"},{"t":"text","v":" to change it. Inquiries already sent about a removed course are kept."}]},{"t":"p","c":[{"t":"text","v":"Only add accreditation you can show members when they ask."}]},{"t":"h2","c":[{"t":"text","v":"Inquiries"}]},{"t":"p","c":[{"t":"text","v":"When a member asks about one of your courses, they're listed under "},{"t":"ui","v":"Inquiries"},{"t":"text","v":", with the course, the area of their result and their question. "},{"t":"ui","v":"Referred by staff"},{"t":"text","v":" means someone else sent them. Each inquiry also arrives as a "},{"t":"term","v":"lead","key":"lead"},{"t":"text","v":" in your "},{"t":"link","v":"admissions leads","href":"/institute/dashboard"},{"t":"text","v":", where your team follows it up."}]}],"headings":["Questions","Courses","Inquiries"],"text":"The counseling quiz asks your members a few questions and suggests the career area that fits them best, with your courses for that area. Open Counseling quiz under Forms. The page has three tabs: Questions, Courses and Inquiries. Questions Each member answers a set of questions drawn at random from your list. The top of the tab says how many questions are in use and how many each member answers. Until you save your own, your institute uses Edulexa's standard questions. To change them: Change a Question, or select Add a question.For each answer, choose its area under Points to area and its Weight. Select Answer under the answers to add another.Untick In use to leave a question out without deleting it, or select Delete.Select Save. Members never see the areas or the weights. Give every area the same number of answers and weights, so the quiz doesn't favor one. To go back to Edulexa's standard questions, select Use Edulexa's standard questions. Your own questions are removed. Courses Your courses are suggested to your members with their quiz results, best match first. Select Add a course, then fill in its Name, Description and Area (matched to quiz results), and, if you like, its Qualification, Length, Next intake and highlights. Tick Shown to members and select Save course. Each course shows Shown or Hidden. Select Edit or Remove to change it. Inquiries already sent about a removed course are kept. Only add accreditation you can show members when they ask. Inquiries When a member asks about one of your courses, they're listed under Inquiries, with the course, the area of their result and their question. Referred by staff means someone else sent them. Each inquiry also arrives as a lead in your admissions leads, where your team follows it up."},{"slug":"create-an-assessment","title":"Create an assessment","summary":"Pick a template for the kind of work, write the instructions, and publish it.","roles":["teacher","admin"],"group":"Assessments","features":["class-assessments"],"checked":"2026-11-11","order":20,"short":["Open Assessments, choose a template under New assessment, give it a title and select Continue.","Fill in the instructions, the rubric and the viva, then select Publish.","Once students start, the task, rubric and viva are locked."],"blocks":[{"t":"p","c":[{"t":"text","v":"Every assessment works the same way: students hand in their own work, then explain and defend it in a "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":", and you decide the result. The template sets what students hand in and gives you a starting "},{"t":"term","v":"rubric","key":"rubric"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Choose a template"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Assessments"},{"t":"text","v":". Under "},{"t":"ui","v":"New assessment"},{"t":"text","v":", choose one:"}]},{"t":"p","c":[{"t":"b","v":"Any subject"}]},{"t":"ul","items":[[{"t":"ui","v":"Essay"},{"t":"text","v":", "},{"t":"ui","v":"Report"},{"t":"text","v":", "},{"t":"ui","v":"Lab report"},{"t":"text","v":" or "},{"t":"ui","v":"Presentation"},{"t":"text","v":": students hand in a PDF, Word or PowerPoint file, or paste their text. The viva asks about what's in it."}]]},{"t":"p","c":[{"t":"b","v":"Code and exams"}]},{"t":"ul","items":[[{"t":"ui","v":"Project defense"},{"t":"text","v":": students hand in their own GitHub repository or a .zip of their project."}],[{"t":"ui","v":"Coding task"},{"t":"text","v":": students solve a coding task in the browser workspace."}],[{"t":"ui","v":"Written exam plus viva"},{"t":"text","v":": students take a written exam, then explain their answers."}]]},{"t":"p","c":[{"t":"text","v":"Give it a "},{"t":"ui","v":"Title"},{"t":"text","v":" and select "},{"t":"ui","v":"Continue"},{"t":"text","v":". For a coding task or an exam, you then choose which task or exam it uses."}]},{"t":"shot","name":"new-assessment","alt":"The New assessment panel, with the templates for any subject and for code and exams","w":592,"h":1359},{"t":"h2","c":[{"t":"text","v":"Fill in the details"}]},{"t":"ul","items":[[{"t":"ui","v":"Instructions for students"},{"t":"text","v":": what to hand in, what the viva covers, and anything they should prepare."}],[{"t":"text","v":"The "},{"t":"ui","v":"Rubric"},{"t":"text","v":" and the "},{"t":"ui","v":"Viva"},{"t":"text","v":": see "},{"t":"link","v":"Set the rubric and the viva","href":"/help/rubric-and-viva"},{"t":"text","v":"."}],[{"t":"ui","v":"Issue a credential when a student passes"},{"t":"text","v":": on by default; turn it off for practice or homework."}]]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Save changes"},{"t":"text","v":" as you go. When it's ready, select "},{"t":"ui","v":"Publish"},{"t":"text","v":". Then give it to a class: see "},{"t":"link","v":"Give an assessment to a class","href":"/help/give-to-a-class"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"Once students have started, the task, the rubric and the viva are locked, so everyone is assessed the same way. You can still change the title, the instructions and the "},{"t":"term","v":"credential","key":"credential"},{"t":"text","v":" setting. To change more, copy it into a new assessment."}]},{"t":"p","c":[{"t":"text","v":"You can "},{"t":"ui","v":"Archive"},{"t":"text","v":" an assessment you no longer use, and "},{"t":"ui","v":"Restore"},{"t":"text","v":" it later."}]}],"headings":["Choose a template","Fill in the details"],"text":"Every assessment works the same way: students hand in their own work, then explain and defend it in a viva, and you decide the result. The template sets what students hand in and gives you a starting rubric. Choose a template Open Assessments. Under New assessment, choose one: Any subject Essay, Report, Lab report or Presentation: students hand in a PDF, Word or PowerPoint file, or paste their text. The viva asks about what's in it. Code and exams Project defense: students hand in their own GitHub repository or a .zip of their project.Coding task: students solve a coding task in the browser workspace.Written exam plus viva: students take a written exam, then explain their answers. Give it a Title and select Continue. For a coding task or an exam, you then choose which task or exam it uses. Fill in the details Instructions for students: what to hand in, what the viva covers, and anything they should prepare.The Rubric and the Viva: see Set the rubric and the viva.Issue a credential when a student passes: on by default; turn it off for practice or homework. Select Save changes as you go. When it's ready, select Publish. Then give it to a class: see Give an assessment to a class. Once students have started, the task, the rubric and the viva are locked, so everyone is assessed the same way. You can still change the title, the instructions and the credential setting. To change more, copy it into a new assessment. You can Archive an assessment you no longer use, and Restore it later."},{"slug":"document-review","title":"Get your résumé or documents reviewed","summary":"Send a résumé, cover letter or other document to a career counselor, read the comments, and send a new version.","roles":["student","alumni"],"group":"Career help","features":["document-review","resumes"],"checked":"2026-11-11","order":20,"short":["In Document review, select Request a review, add your document and say what it's for.","A counselor sends back a summary, a checklist and comments. You get a notification.","Send a new version as often as you like."],"blocks":[{"t":"p","c":[{"t":"text","v":"A career counselor reads your document and sends back a summary, a checklist and comments. Open "},{"t":"link","v":"Document review","href":"/student/document-review"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Ask for a review"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Request a review"},{"t":"text","v":"."}],[{"t":"text","v":"Choose the "},{"t":"ui","v":"Document type"},{"t":"text","v":": a résumé, cover letter, personal statement, LinkedIn summary or something else."}],[{"t":"text","v":"Under "},{"t":"ui","v":"What it's for"},{"t":"text","v":", say what you're applying for, for example \"Software internships\"."}],[{"t":"text","v":"Choose how to share it: "},{"t":"ui","v":"Upload a file"},{"t":"text","v":" (PDF, Word, PNG, JPEG or text, up to 10 MB), "},{"t":"ui","v":"Paste text"},{"t":"text","v":", or, for a résumé, "},{"t":"ui","v":"From your library"},{"t":"text","v":"."}],[{"t":"text","v":"If you like, paste the job or program description, add notes for the reviewer, and give your deadline. A close deadline gets priority."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Send for review"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The page says when a counselor aims to return it. A résumé file you upload here is also saved in your "},{"t":"link","v":"résumé library","href":"/help/resumes"},{"t":"text","v":"."}]},{"t":"shot","name":"document-review-request","alt":"The Request a review form, with the document type, what it's for, how to share it, and the Send for review button","w":1068,"h":1262},{"t":"h2","c":[{"t":"text","v":"Read the review"}]},{"t":"p","c":[{"t":"text","v":"You get a notification when it's ready. Open it from "},{"t":"ui","v":"My reviews"},{"t":"text","v":". Each version shows:"}]},{"t":"ul","items":[[{"t":"text","v":"the "},{"t":"ui","v":"Summary"},{"t":"text","v":","}],[{"t":"text","v":"the "},{"t":"ui","v":"Checklist"},{"t":"text","v":", with each point rated (for example Strong or Needs work),"}],[{"t":"text","v":"the "},{"t":"ui","v":"Comments"},{"t":"text","v":". On pasted text, each comment points to the passage it's about."}]]},{"t":"p","c":[{"t":"text","v":"The reviewer may also attach a marked-up copy of your file to download."}]},{"t":"p","c":[{"t":"text","v":"If the counselor approves a résumé you sent from your library, it shows "},{"t":"ui","v":"Approved by your school"},{"t":"text","v":" there. Some schools take only approved résumés with job applications."}]},{"t":"h2","c":[{"t":"text","v":"Next steps"}]},{"t":"ul","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Send a new version"},{"t":"text","v":" to have your changes reviewed. Earlier versions and their comments stay on the page."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Mark as done"},{"t":"text","v":" when you're finished."}],[{"t":"text","v":"Tell the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" how it went under "},{"t":"ui","v":"Was this review helpful?"},{"t":"text","v":", then select "},{"t":"ui","v":"Save rating"},{"t":"text","v":"."}]]}],"headings":["Ask for a review","Read the review","Next steps"],"text":"A career counselor reads your document and sends back a summary, a checklist and comments. Open Document review. Ask for a review Select Request a review.Choose the Document type: a résumé, cover letter, personal statement, LinkedIn summary or something else.Under What it's for, say what you're applying for, for example \"Software internships\".Choose how to share it: Upload a file (PDF, Word, PNG, JPEG or text, up to 10 MB), Paste text, or, for a résumé, From your library.If you like, paste the job or program description, add notes for the reviewer, and give your deadline. A close deadline gets priority.Select Send for review. The page says when a counselor aims to return it. A résumé file you upload here is also saved in your résumé library. Read the review You get a notification when it's ready. Open it from My reviews. Each version shows: the Summary,the Checklist, with each point rated (for example Strong or Needs work),the Comments. On pasted text, each comment points to the passage it's about. The reviewer may also attach a marked-up copy of your file to download. If the counselor approves a résumé you sent from your library, it shows Approved by your school there. Some schools take only approved résumés with job applications. Next steps Select Send a new version to have your changes reviewed. Earlier versions and their comments stay on the page.Select Mark as done when you're finished.Tell the career center how it went under Was this review helpful?, then select Save rating."},{"slug":"employer-interviews-and-challenges","title":"Run interview days and challenges","summary":"Ask a school for an on-campus or virtual interview day, invite students and record how each interview went, and invite students to a skills challenge.","roles":["employer"],"group":"Hiring","features":["campus-interviews","employer-challenges"],"checked":"2026-11-12","order":20,"short":["Request an interview schedule. The career center approves it, assigns rooms and opens it for students to sign up.","On the day, check students in, mark no-shows and record each outcome.","Challenges invite students to a skills exercise. You see results only from students who choose to share them."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Ask for an interview day"}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Interview schedules"},{"t":"text","v":" under "},{"t":"ui","v":"Hiring"},{"t":"text","v":" and select "},{"t":"ui","v":"Request a schedule"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Position"},{"t":"text","v":", choose the "},{"t":"ui","v":"School"},{"t":"text","v":", and fill in the "},{"t":"ui","v":"Position title"},{"t":"text","v":" and a "},{"t":"ui","v":"Job posting link"},{"t":"text","v":" to where students read and apply for the job on your own job platform."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Days and format"},{"t":"text","v":", set each day's "},{"t":"ui","v":"Date"},{"t":"text","v":", "},{"t":"ui","v":"Start"},{"t":"text","v":" and "},{"t":"ui","v":"End"},{"t":"text","v":", a lunch break if you like, the "},{"t":"ui","v":"Interview length (minutes)"},{"t":"text","v":" and the "},{"t":"ui","v":"Break between interviews (minutes)"},{"t":"text","v":". For more than one interview at a time, raise "},{"t":"ui","v":"Rooms needed"},{"t":"text","v":". For "},{"t":"ui","v":"Virtual interviews"},{"t":"text","v":", add the "},{"t":"ui","v":"Video meeting link"},{"t":"text","v":". List your "},{"t":"ui","v":"Interviewers"},{"t":"text","v":", one per line."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Who can sign up"},{"t":"text","v":", choose the "},{"t":"ui","v":"Sign-up type"},{"t":"text","v":": "},{"t":"ui","v":"Open to qualified students"},{"t":"text","v":", "},{"t":"ui","v":"Pre-select list"},{"t":"text","v":", or "},{"t":"ui","v":"Pre-select with alternates"},{"t":"text","v":". Add any "},{"t":"ui","v":"Work authorization"},{"t":"text","v":" requirement, majors, graduation dates and degree levels. Students confirm their work authorization themselves; you don't receive their status."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Send request"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" approves or declines your request, assigns rooms and publishes it. Students can then sign up for a time. "},{"t":"ui","v":"My schedules"},{"t":"text","v":" shows each request's status and any note from the career center."}]},{"t":"h2","c":[{"t":"text","v":"Invite students and run the day"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Candidates and details"},{"t":"text","v":" on a schedule."}]},{"t":"ul","items":[[{"t":"b","v":"For a pre-select list:"},{"t":"text","v":" paste the "},{"t":"ui","v":"Student emails"},{"t":"text","v":", for example a column copied from a spreadsheet, and select "},{"t":"ui","v":"Invite students"},{"t":"text","v":". Only students of that school are invited, and you see their details once they accept. With alternates, choose whether each one is invited as primary or alternate under "},{"t":"ui","v":"Invite as"},{"t":"text","v":"."}],[{"t":"ui","v":"Interviews"},{"t":"text","v":" lists each booked time, with the student's details and their résumé to download."}],[{"t":"text","v":"On the day, select "},{"t":"ui","v":"Check in"},{"t":"text","v":" or "},{"t":"ui","v":"Mark no-show"},{"t":"text","v":" for each student, and choose the "},{"t":"ui","v":"Outcome"},{"t":"text","v":": "},{"t":"ui","v":"Offer"},{"t":"text","v":", "},{"t":"ui","v":"No offer"},{"t":"text","v":" or "},{"t":"ui","v":"Pending"},{"t":"text","v":"."}],[{"t":"ui","v":"Withdraw schedule"},{"t":"text","v":" cancels the whole schedule. Booked students are told it was cancelled."}]]},{"t":"h2","c":[{"t":"text","v":"Challenges"}]},{"t":"p","c":[{"t":"text","v":"A challenge invites students to a skills exercise built on one of your coding tasks. It isn't a job posting: you can link to your own job page, and students choose whether to share their results with you. Your company needs approval from at least one school first."}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Challenges"},{"t":"text","v":" under "},{"t":"ui","v":"Hiring"},{"t":"text","v":" and select "},{"t":"ui","v":"New challenge"},{"t":"text","v":"."}],[{"t":"text","v":"Give it a "},{"t":"ui","v":"Title"},{"t":"text","v":" and choose the "},{"t":"ui","v":"Assessment"},{"t":"text","v":": one of your company's "},{"t":"term","v":"work trials","key":"work-trial"},{"t":"text","v":" that passed its check (your recruiters make these on the recruiter portal), one of your company's private coding tasks, or a public one."}],[{"t":"text","v":"Set when it "},{"t":"ui","v":"Opens"},{"t":"text","v":" and "},{"t":"ui","v":"Closes"},{"t":"text","v":". If you like, add who can join, the "},{"t":"ui","v":"Maximum participants"},{"t":"text","v":", a "},{"t":"ui","v":"Link to your job page"},{"t":"text","v":" and a "},{"t":"ui","v":"Prize or recognition"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Save draft"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Manage"},{"t":"text","v":", tick the schools that approved your company, and select "},{"t":"ui","v":"Publish"},{"t":"text","v":". Each school's career center reviews it before students see it."}]]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Manage"},{"t":"text","v":", the results button shows "},{"t":"ui","v":"Participants sharing results"},{"t":"text","v":", with each student's score, tests, "},{"t":"term","v":"integrity signal","key":"integrity-signal"},{"t":"text","v":" and defense, and their "},{"t":"ui","v":"Evidence pack"},{"t":"text","v":". Students who don't share aren't shown."}]},{"t":"p","c":[{"t":"text","v":"To get in touch with a student, select "},{"t":"ui","v":"Invite to talk"},{"t":"text","v":", write a "},{"t":"ui","v":"Message"},{"t":"text","v":" and add a link if you like, such as a scheduling page, then select "},{"t":"ui","v":"Send invitation"},{"t":"text","v":". There's no reply thread: the student decides whether to contact you."}]},{"t":"p","c":[{"t":"text","v":"When it's over, select "},{"t":"ui","v":"Close challenge"},{"t":"text","v":"."}]}],"headings":["Ask for an interview day","Invite students and run the day","Challenges"],"text":"Ask for an interview day Open Interview schedules under Hiring and select Request a schedule.Under Position, choose the School, and fill in the Position title and a Job posting link to where students read and apply for the job on your own job platform.Under Days and format, set each day's Date, Start and End, a lunch break if you like, the Interview length (minutes) and the Break between interviews (minutes). For more than one interview at a time, raise Rooms needed. For Virtual interviews, add the Video meeting link. List your Interviewers, one per line.Under Who can sign up, choose the Sign-up type: Open to qualified students, Pre-select list, or Pre-select with alternates. Add any Work authorization requirement, majors, graduation dates and degree levels. Students confirm their work authorization themselves; you don't receive their status.Select Send request. The career center approves or declines your request, assigns rooms and publishes it. Students can then sign up for a time. My schedules shows each request's status and any note from the career center. Invite students and run the day Select Candidates and details on a schedule. For a pre-select list: paste the Student emails, for example a column copied from a spreadsheet, and select Invite students. Only students of that school are invited, and you see their details once they accept. With alternates, choose whether each one is invited as primary or alternate under Invite as.Interviews lists each booked time, with the student's details and their résumé to download.On the day, select Check in or Mark no-show for each student, and choose the Outcome: Offer, No offer or Pending.Withdraw schedule cancels the whole schedule. Booked students are told it was cancelled. Challenges A challenge invites students to a skills exercise built on one of your coding tasks. It isn't a job posting: you can link to your own job page, and students choose whether to share their results with you. Your company needs approval from at least one school first. Open Challenges under Hiring and select New challenge.Give it a Title and choose the Assessment: one of your company's work trials that passed its check (your recruiters make these on the recruiter portal), one of your company's private coding tasks, or a public one.Set when it Opens and Closes. If you like, add who can join, the Maximum participants, a Link to your job page and a Prize or recognition.Select Save draft.Select Manage, tick the schools that approved your company, and select Publish. Each school's career center reviews it before students see it. Under Manage, the results button shows Participants sharing results, with each student's score, tests, integrity signal and defense, and their Evidence pack. Students who don't share aren't shown. To get in touch with a student, select Invite to talk, write a Message and add a link if you like, such as a scheduling page, then select Send invitation. There's no reply thread: the student decides whether to contact you. When it's over, select Close challenge."},{"slug":"guidance-requests-for-you","title":"Guidance requests handed to you","summary":"Answer the career questions Edulexa's advisors hand to you as a community mentor, or hand one back.","roles":["mentor"],"group":"Guidance requests","features":["guidance-desk"],"checked":"2026-11-12","order":20,"short":["Open Guidance requests for you, read what the person shared, and write your reply.","Your reply reaches them in Edulexa and by e-mail. A note for staff only stays between you and the advisors.","Can't help? Select Hand back to the advisors."],"blocks":[{"t":"p","c":[{"t":"text","v":"People who aren't sure which area or certification to choose can ask Edulexa for guidance. When Edulexa's advisors are busy, they hand some requests to approved community "},{"t":"term","v":"mentors","key":"mentoring"},{"t":"text","v":". You get a notification and an e-mail for each one."}]},{"t":"h2","c":[{"t":"text","v":"Your requests"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"link","v":"Guidance requests for you","href":"/mentor/guidance"},{"t":"text","v":". Each request shows:"}]},{"t":"ul","items":[[{"t":"text","v":"the person's name and where the request is, such as "},{"t":"ui","v":"With a mentor"},{"t":"text","v":" or "},{"t":"ui","v":"Answered"},{"t":"text","v":";"}],[{"t":"ui","v":"What they're unsure about:"},{"t":"text","v":" and their answers to Edulexa's questions;"}],[{"t":"text","v":"their counseling quiz result, if they chose to share it;"}],[{"t":"text","v":"the conversation so far."}]]},{"t":"p","c":[{"t":"text","v":"Files they attached are shown to the advisors only. A request leaves your list once it's resolved or handed back."}]},{"t":"h2","c":[{"t":"text","v":"Reply"}]},{"t":"p","c":[{"t":"text","v":"Write your reply and select "},{"t":"ui","v":"Send"},{"t":"text","v":". The person gets it in Edulexa and by e-mail, and the request shows "},{"t":"ui","v":"Answered"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"You can also reply to the e-mail you received about the request, when it says you can. Replies are taken only from the e-mail address on your mentor profile."}]},{"t":"p","c":[{"t":"text","v":"To leave a message only the advisors can read, tick "},{"t":"ui","v":"Note for staff only (the person doesn't see it)"},{"t":"text","v":", then select "},{"t":"ui","v":"Add note"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Hand it back"}]},{"t":"p","c":[{"t":"text","v":"If you can't help, select "},{"t":"ui","v":"Hand back to the advisors"},{"t":"text","v":". The request goes back to them straight away, and they're told by e-mail. Add a note for staff first if it helps them, for example who could help instead."}]}],"headings":["Your requests","Reply","Hand it back"],"text":"People who aren't sure which area or certification to choose can ask Edulexa for guidance. When Edulexa's advisors are busy, they hand some requests to approved community mentors. You get a notification and an e-mail for each one. Your requests Open Guidance requests for you. Each request shows: the person's name and where the request is, such as With a mentor or Answered;What they're unsure about: and their answers to Edulexa's questions;their counseling quiz result, if they chose to share it;the conversation so far. Files they attached are shown to the advisors only. A request leaves your list once it's resolved or handed back. Reply Write your reply and select Send. The person gets it in Edulexa and by e-mail, and the request shows Answered. You can also reply to the e-mail you received about the request, when it says you can. Replies are taken only from the e-mail address on your mentor profile. To leave a message only the advisors can read, tick Note for staff only (the person doesn't see it), then select Add note. Hand it back If you can't help, select Hand back to the advisors. The request goes back to them straight away, and they're told by e-mail. Add a note for staff first if it helps them, for example who could help instead."},{"slug":"interview-and-speaking-practice","title":"Practice interviews and speaking","summary":"Have a spoken practice interview with an AI interviewer and get a scorecard, or practice answering out loud and see your pace, filler words and pauses.","roles":["member"],"group":"Practice","features":["interview-practice","speaking-practice"],"checked":"2026-11-12","order":20,"short":["Interview practice is a spoken interview for the job you choose, with a scorecard at the end. You pay only for the minutes you use.","Speaking practice measures your pace, filler words and pauses. Only you see the results.","Both are practice only. They don't give a credential."],"blocks":[{"t":"p","c":[{"t":"text","v":"Both kinds of practice need a microphone. If yours doesn't work, see "},{"t":"link","v":"Check your microphone and browser","href":"/help/microphone-and-browser"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"A practice interview"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Interview practice"},{"t":"text","v":" from the "},{"t":"ui","v":"Practice"},{"t":"text","v":" menu."}]},{"t":"ol","items":[[{"t":"ui","v":"1. Choose a track"},{"t":"text","v":", such as software, product management or sales."}],[{"t":"ui","v":"2. Choose an interviewer"},{"t":"text","v":". Each one says "},{"t":"ui","v":"How tough the questions are"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"3. The job"},{"t":"text","v":", enter the "},{"t":"ui","v":"Job title"},{"t":"text","v":" and paste the "},{"t":"ui","v":"Job description or key requirements"},{"t":"text","v":" from any job post. Or select one of the "},{"t":"ui","v":"Example roles"},{"t":"text","v":"."}],[{"t":"text","v":"Enter "},{"t":"ui","v":"Your name"},{"t":"text","v":" and choose an "},{"t":"ui","v":"Interviewer voice"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Start interview"},{"t":"text","v":" and allow the microphone when your browser asks."}]]},{"t":"p","c":[{"t":"text","v":"Talk as you would in a real interview. The interviewer asks follow-up questions, and your words show in the "},{"t":"ui","v":"Live transcript"},{"t":"text","v":". Use "},{"t":"ui","v":"Mute"},{"t":"text","v":" to pause your microphone. When you're done, select "},{"t":"ui","v":"End and get my scorecard"},{"t":"text","v":". If you reach the time limit or your connection drops, the interview ends and you still get your scorecard. "},{"t":"ui","v":"Cancel"},{"t":"text","v":" ends it without a scorecard."}]},{"t":"p","c":[{"t":"text","v":"The scorecard shows your "},{"t":"ui","v":"Overall readiness"},{"t":"text","v":", your "},{"t":"ui","v":"Strengths"},{"t":"text","v":", "},{"t":"ui","v":"What to improve"},{"t":"text","v":" and the whole "},{"t":"ui","v":"Transcript"},{"t":"text","v":". You can copy or download the transcript. Select "},{"t":"ui","v":"Practice again"},{"t":"text","v":" for the same job, or "},{"t":"ui","v":"Set up a new role"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"You pay only for the minutes you use. When you start, a whole session's worth of your "},{"t":"term","v":"voice minutes","key":"voice-minutes"},{"t":"text","v":" is set aside, up to the session limit shown in "},{"t":"link","v":"Pricing and minutes","href":"/pricing"},{"t":"text","v":", so you can't run out partway. When the interview ends, the minutes you didn't use go back to your balance, and the scorecard shows how many you used. Each interview counts in whole minutes, rounded up: a 4 minute 10 second interview uses 5 minutes. If no answers were recorded, or the interview didn't connect, no minutes are used. It's for practice only: it doesn't give a "},{"t":"term","v":"credential","key":"credential"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Speaking practice"}]},{"t":"p","c":[{"t":"ui","v":"Speaking practice"},{"t":"text","v":" helps with how you speak, not what you say. It measures your pace (words a minute), filler words such as \"um\", your pauses, and how long you take to start. It doesn't judge emotion, stress or confidence."}]},{"t":"ol","items":[[{"t":"text","v":"The first time, read what's measured and select "},{"t":"ui","v":"Turn on speaking practice"},{"t":"text","v":"."}],[{"t":"text","v":"Pick a "},{"t":"ui","v":"Question"},{"t":"text","v":", or write "},{"t":"ui","v":"Or your own question"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Start answering"},{"t":"text","v":", answer out loud, then select "},{"t":"ui","v":"Stop and see feedback"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Your feedback shows straight away. "},{"t":"ui","v":"Across your recent answers"},{"t":"text","v":" shows your averages, and "},{"t":"ui","v":"Your answers"},{"t":"text","v":" lists each one."}]},{"t":"ul","items":[[{"t":"text","v":"Your recording stays in your browser. To count words, your browser turns your answer into text, and Edulexa doesn't keep that text. Chrome, Edge and Safari can count words. In other browsers, only pauses and your start time are measured."}],[{"t":"text","v":"Only you see your results. They're never shown to recruiters or institutes, or used in any score."}],[{"t":"text","v":"Your measurements are kept for 180 days. Select "},{"t":"ui","v":"Delete my answers"},{"t":"text","v":" at any time, or "},{"t":"ui","v":"Turn off speaking practice"},{"t":"text","v":" to stop and delete them."}]]},{"t":"p","c":[{"t":"text","v":"Speaking practice isn't offered in the EU and EEA, where the law limits voice analysis in education. It's also off when Edulexa can't tell which country you're in."}]},{"t":"p","c":[{"t":"text","v":"Next step: prove your skills in an exam or a coding challenge. See "},{"t":"link","v":"Exams, coding challenges and your GitHub work","href":"/help/exams-and-challenges"},{"t":"text","v":"."}]}],"headings":["A practice interview","Speaking practice"],"text":"Both kinds of practice need a microphone. If yours doesn't work, see Check your microphone and browser. A practice interview Open Interview practice from the Practice menu. 1. Choose a track, such as software, product management or sales.2. Choose an interviewer. Each one says How tough the questions are.Under 3. The job, enter the Job title and paste the Job description or key requirements from any job post. Or select one of the Example roles.Enter Your name and choose an Interviewer voice.Select Start interview and allow the microphone when your browser asks. Talk as you would in a real interview. The interviewer asks follow-up questions, and your words show in the Live transcript. Use Mute to pause your microphone. When you're done, select End and get my scorecard. If you reach the time limit or your connection drops, the interview ends and you still get your scorecard. Cancel ends it without a scorecard. The scorecard shows your Overall readiness, your Strengths, What to improve and the whole Transcript. You can copy or download the transcript. Select Practice again for the same job, or Set up a new role. You pay only for the minutes you use. When you start, a whole session's worth of your voice minutes is set aside, up to the session limit shown in Pricing and minutes, so you can't run out partway. When the interview ends, the minutes you didn't use go back to your balance, and the scorecard shows how many you used. Each interview counts in whole minutes, rounded up: a 4 minute 10 second interview uses 5 minutes. If no answers were recorded, or the interview didn't connect, no minutes are used. It's for practice only: it doesn't give a credential. Speaking practice Speaking practice helps with how you speak, not what you say. It measures your pace (words a minute), filler words such as \"um\", your pauses, and how long you take to start. It doesn't judge emotion, stress or confidence. The first time, read what's measured and select Turn on speaking practice.Pick a Question, or write Or your own question.Select Start answering, answer out loud, then select Stop and see feedback. Your feedback shows straight away. Across your recent answers shows your averages, and Your answers lists each one. Your recording stays in your browser. To count words, your browser turns your answer into text, and Edulexa doesn't keep that text. Chrome, Edge and Safari can count words. In other browsers, only pauses and your start time are measured.Only you see your results. They're never shown to recruiters or institutes, or used in any score.Your measurements are kept for 180 days. Select Delete my answers at any time, or Turn off speaking practice to stop and delete them. Speaking practice isn't offered in the EU and EEA, where the law limits voice analysis in education. It's also off when Edulexa can't tell which country you're in. Next step: prove your skills in an exam or a coding challenge. See Exams, coding challenges and your GitHub work."},{"slug":"jobs-drives-and-interviews","title":"Run campus drives and interview schedules","summary":"Follow a campus drive from approval to offers, and run on-campus interview days from the employer's request to check-in.","roles":["staff"],"group":"Employers and jobs","features":["campus-drives","campus-interviews"],"checked":"2026-11-11","order":20,"short":["Approved campus drives take applications. Open a drive to set its deadline, close applications and follow its rounds.","In Interview schedules, approve an employer's request, assign rooms and publish it so students can sign up.","On the day, check students in and mark no-shows."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Campus drives"}]},{"t":"p","c":[{"t":"text","v":"A "},{"t":"term","v":"campus drive","key":"campus-drive"},{"t":"text","v":" is a job an employer sent your school. Once it's approved (see "},{"t":"link","v":"Approve employers and their jobs","href":"/help/employers-and-approvals"},{"t":"text","v":"), eligible students can apply."}]},{"t":"p","c":[{"t":"text","v":"Open a drive from "},{"t":"ui","v":"Campus drives"},{"t":"text","v":" to:"}]},{"t":"ul","items":[[{"t":"text","v":"Change the deadline under "},{"t":"ui","v":"Change the deadline"},{"t":"text","v":", then select "},{"t":"ui","v":"Save changes"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Close applications"},{"t":"text","v":", or "},{"t":"ui","v":"Open applications"},{"t":"text","v":" again."}],[{"t":"text","v":"Follow the selection with the employer: its rounds, the applicants and their results, interview slots and offers."}]]},{"t":"p","c":[{"t":"text","v":"To add a drive for a company that recruits through your office, use the "},{"t":"ui","v":"New drive"},{"t":"text","v":" tab. It's approved and open to students straight away."}]},{"t":"h2","c":[{"t":"text","v":"On-campus interview schedules"}]},{"t":"p","c":[{"t":"text","v":"Employers ask for an interview day at your school. Open "},{"t":"ui","v":"Interview schedules"},{"t":"text","v":" from the "},{"t":"ui","v":"Students"},{"t":"text","v":" menu."}]},{"t":"ol","items":[[{"t":"text","v":"On "},{"t":"ui","v":"Schedules"},{"t":"text","v":", select "},{"t":"ui","v":"Manage"},{"t":"text","v":" on a request and choose "},{"t":"ui","v":"Approve"},{"t":"text","v":" or "},{"t":"ui","v":"Decline"},{"t":"text","v":", with a note to the employer if you like."}],[{"t":"text","v":"Assign a room for each day, then select "},{"t":"ui","v":"Save rooms"},{"t":"text","v":". Add your rooms first on the "},{"t":"ui","v":"Rooms"},{"t":"text","v":" tab."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Publish"},{"t":"text","v":". Students can then sign up for a time."}]]},{"t":"p","c":[{"t":"text","v":"On the day, open "},{"t":"ui","v":"Interview day"},{"t":"text","v":" to see every interview, print the agendas with "},{"t":"ui","v":"Printable agendas"},{"t":"text","v":", and select "},{"t":"ui","v":"Check in"},{"t":"text","v":" or "},{"t":"ui","v":"No-show"},{"t":"text","v":" for each student. If you cancel a student's interview, the next alternate is booked automatically."}]},{"t":"h2","c":[{"t":"text","v":"No-shows"}]},{"t":"p","c":[{"t":"text","v":"Your school can pause sign-ups for students who miss too many interviews. They're listed on "},{"t":"ui","v":"No-shows"},{"t":"text","v":"; select "},{"t":"ui","v":"Clear"},{"t":"text","v":" to let a student sign up again. A career admin sets the limit and the cancellation cutoff on "},{"t":"ui","v":"Settings"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Who does what"}]},{"t":"p","c":[{"t":"text","v":"Career admins and employer relations staff change drives and run their selection, and they approve, assign rooms to, publish and cancel interview schedules. Every career staff member can see drives and schedules, add a drive, check students in and mark no-shows."}]},{"t":"p","c":[{"t":"link","v":"Interview reports","href":"/career-center/interviews/reports"},{"t":"text","v":" show slots offered, bookings, attendance and offers by employer."}]}],"headings":["Campus drives","On-campus interview schedules","No-shows","Who does what"],"text":"Campus drives A campus drive is a job an employer sent your school. Once it's approved (see Approve employers and their jobs), eligible students can apply. Open a drive from Campus drives to: Change the deadline under Change the deadline, then select Save changes.Select Close applications, or Open applications again.Follow the selection with the employer: its rounds, the applicants and their results, interview slots and offers. To add a drive for a company that recruits through your office, use the New drive tab. It's approved and open to students straight away. On-campus interview schedules Employers ask for an interview day at your school. Open Interview schedules from the Students menu. On Schedules, select Manage on a request and choose Approve or Decline, with a note to the employer if you like.Assign a room for each day, then select Save rooms. Add your rooms first on the Rooms tab.Select Publish. Students can then sign up for a time. On the day, open Interview day to see every interview, print the agendas with Printable agendas, and select Check in or No-show for each student. If you cancel a student's interview, the next alternate is booked automatically. No-shows Your school can pause sign-ups for students who miss too many interviews. They're listed on No-shows; select Clear to let a student sign up again. A career admin sets the limit and the cancellation cutoff on Settings. Who does what Career admins and employer relations staff change drives and run their selection, and they approve, assign rooms to, publish and cancel interview schedules. Every career staff member can see drives and schedules, add a drive, check students in and mark no-shows. Interview reports show slots offered, bookings, attendance and offers by employer."},{"slug":"member-resumes","title":"Résumés, job check and cover letters","summary":"Keep your résumés in one place, build one with lines Edulexa has verified, check it against a job, and draft a cover letter for that job.","roles":["member"],"group":"Your record","features":["resumes"],"checked":"2026-11-12","order":20,"short":["In Résumés, select Upload résumé (PDF or Word, up to 5 MB) or Build a résumé.","Job check lists what a job asks for and shows where your résumé mentions each one. There's no score.","Cover letters drafts a letter for one job from your résumé. Read it closely and make it yours."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Your résumé library"}]},{"t":"p","c":[{"t":"ui","v":"Résumés"},{"t":"text","v":" keeps all your résumés in one place."}]},{"t":"ul","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Upload résumé"},{"t":"text","v":" and choose a PDF or Word (.docx) file, up to 5 MB. Edulexa reads its text. If it can't (a scanned page, for example), the résumé shows "},{"t":"ui","v":"Couldn't read text"},{"t":"text","v":", and Job check and Cover letters can't use it. You can still download it and send it as it is."}],[{"t":"text","v":"Or select "},{"t":"ui","v":"Build a résumé"},{"t":"text","v":", then "},{"t":"ui","v":"Start from your record"},{"t":"text","v":" (your name and e-mail address) or "},{"t":"ui","v":"Start blank"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"For an uploaded résumé:"}]},{"t":"ul","items":[[{"t":"ui","v":"Upload a new version"},{"t":"text","v":" when you change it. Older versions are kept under "},{"t":"ui","v":"Versions and where they went"},{"t":"text","v":"."}],[{"t":"ui","v":"AI feedback"},{"t":"text","v":" suggests stronger lines. They're only suggestions: change what helps, in your own words."}],[{"t":"ui","v":"Turn into a built résumé"},{"t":"text","v":" to edit it here."}],[{"t":"ui","v":"Archive"},{"t":"text","v":" puts away one you don't use. Restore it from "},{"t":"ui","v":"Archived"},{"t":"text","v":" at any time."}]]},{"t":"h2","c":[{"t":"text","v":"Build a résumé"}]},{"t":"p","c":[{"t":"text","v":"Edulexa lays it out for you. Add sections and lines, then select "},{"t":"ui","v":"Save version"},{"t":"text","v":". Each save keeps a version you can "},{"t":"ui","v":"Download PDF"},{"t":"text","v":" or "},{"t":"ui","v":"Download Word"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Verified evidence"},{"t":"text","v":" are lines drafted from your "},{"t":"term","v":"credentials","key":"credential"},{"t":"text","v":". Select "},{"t":"ui","v":"Add to résumé"},{"t":"text","v":" to use one. It prints with a Verified mark that links to the proof. You can change the wording, but changing a number removes the mark."}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"AI help"},{"t":"text","v":":"}]},{"t":"ul","items":[[{"t":"ui","v":"Get feedback on each line"},{"t":"text","v":"."}],[{"t":"ui","v":"Tailor to a job"},{"t":"text","v":": choose a saved job check, select "},{"t":"ui","v":"Suggest changes for this job"},{"t":"text","v":", tick the ones you want, and select "},{"t":"ui","v":"Apply the ones I chose"},{"t":"text","v":". Then look them over and save a version."}]]},{"t":"p","c":[{"t":"text","v":"Each AI request uses one of your AI uses for the month. The page shows how many you have left."}]},{"t":"h2","c":[{"t":"text","v":"Check it against a job"}]},{"t":"p","c":[{"t":"ui","v":"Job check"},{"t":"text","v":" shows where your résumé mentions what a job asks for."}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"New job check"},{"t":"text","v":". Enter the "},{"t":"ui","v":"Job title"},{"t":"text","v":", the "},{"t":"ui","v":"Company (optional)"},{"t":"text","v":" and the "},{"t":"ui","v":"Job description"},{"t":"text","v":"."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Requirements, one per line"},{"t":"text","v":", list what the job asks for, or select "},{"t":"ui","v":"Suggest requirements"},{"t":"text","v":" to have the AI copy them from the description. Check the list."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Check this résumé"},{"t":"text","v":", choose a résumé, then select "},{"t":"ui","v":"Save and check"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Each requirement shows "},{"t":"ui","v":"Mentioned"},{"t":"text","v":" or "},{"t":"ui","v":"Not found"},{"t":"text","v":". There's no score: a mention isn't proof, and add something missing only if it's true."}]},{"t":"h2","c":[{"t":"text","v":"Draft a cover letter"}]},{"t":"ol","items":[[{"t":"text","v":"In "},{"t":"ui","v":"Cover letters"},{"t":"text","v":", select "},{"t":"ui","v":"Draft a cover letter"},{"t":"text","v":"."}],[{"t":"text","v":"Choose the résumé under "},{"t":"ui","v":"Based on this résumé"},{"t":"text","v":", and the job under "},{"t":"ui","v":"For this job"},{"t":"text","v":": a saved job check, or "},{"t":"ui","v":"A job I'll paste below"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Draft with AI"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The draft uses only what your résumé says. Read it closely and make it yours, then select "},{"t":"ui","v":"Save version"},{"t":"text","v":". Download it with "},{"t":"ui","v":"Download PDF"},{"t":"text","v":" or "},{"t":"ui","v":"Download Word"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Want a person's view on where to go next? See "},{"t":"link","v":"Ask Edulexa or find a mentor","href":"/help/ask-edulexa"},{"t":"text","v":"."}]}],"headings":["Your résumé library","Build a résumé","Check it against a job","Draft a cover letter"],"text":"Your résumé library Résumés keeps all your résumés in one place. Select Upload résumé and choose a PDF or Word (.docx) file, up to 5 MB. Edulexa reads its text. If it can't (a scanned page, for example), the résumé shows Couldn't read text, and Job check and Cover letters can't use it. You can still download it and send it as it is.Or select Build a résumé, then Start from your record (your name and e-mail address) or Start blank. For an uploaded résumé: Upload a new version when you change it. Older versions are kept under Versions and where they went.AI feedback suggests stronger lines. They're only suggestions: change what helps, in your own words.Turn into a built résumé to edit it here.Archive puts away one you don't use. Restore it from Archived at any time. Build a résumé Edulexa lays it out for you. Add sections and lines, then select Save version. Each save keeps a version you can Download PDF or Download Word. Under Verified evidence are lines drafted from your credentials. Select Add to résumé to use one. It prints with a Verified mark that links to the proof. You can change the wording, but changing a number removes the mark. Under AI help: Get feedback on each line.Tailor to a job: choose a saved job check, select Suggest changes for this job, tick the ones you want, and select Apply the ones I chose. Then look them over and save a version. Each AI request uses one of your AI uses for the month. The page shows how many you have left. Check it against a job Job check shows where your résumé mentions what a job asks for. Select New job check. Enter the Job title, the Company (optional) and the Job description.Under Requirements, one per line, list what the job asks for, or select Suggest requirements to have the AI copy them from the description. Check the list.Under Check this résumé, choose a résumé, then select Save and check. Each requirement shows Mentioned or Not found. There's no score: a mention isn't proof, and add something missing only if it's true. Draft a cover letter In Cover letters, select Draft a cover letter.Choose the résumé under Based on this résumé, and the job under For this job: a saved job check, or A job I'll paste below.Select Draft with AI. The draft uses only what your résumé says. Read it closely and make it yours, then select Save version. Download it with Download PDF or Download Word. Want a person's view on where to go next? See Ask Edulexa or find a mentor."},{"slug":"recruiter-evidence-packs","title":"Review an evidence pack and decide","summary":"Open a candidate's evidence pack, read what's in it, and record Advance, Hold or Decline with your reasons.","roles":["recruiter"],"group":"Reviewing candidates","features":["evidence-packs"],"checked":"2026-11-12","order":20,"short":["Evidence packs lists the work waiting for a decision. Open one to see the tests, the code, AI use, integrity signals and the defense.","Choose Advance, Hold or Decline and write your rationale, at least 20 characters.","Integrity signals are things to talk about with the candidate, not proof."],"blocks":[{"t":"p","c":[{"t":"text","v":"Every piece of work handed in for a coding challenge or a "},{"t":"term","v":"work trial","key":"work-trial"},{"t":"text","v":" gets an "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" pack. It brings together what you need to decide fairly. Edulexa doesn't advance or turn down anyone: a reviewer records every "},{"t":"term","v":"decision","key":"decision"},{"t":"text","v":", with a rationale."}]},{"t":"h2","c":[{"t":"text","v":"Find the work"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Evidence packs"},{"t":"text","v":" under "},{"t":"ui","v":"Review"},{"t":"text","v":". The "},{"t":"ui","v":"Evidence review queue"},{"t":"text","v":" shows the work "},{"t":"ui","v":"Awaiting decision"},{"t":"text","v":" first. You can narrow it by "},{"t":"ui","v":"Challenge"},{"t":"text","v":", by "},{"t":"ui","v":"Integrity signals"},{"t":"text","v":" or by "},{"t":"ui","v":"Decision"},{"t":"text","v":". Select a candidate's name to open their pack."}]},{"t":"h2","c":[{"t":"text","v":"What's in the pack"}]},{"t":"ul","items":[[{"t":"b","v":"At the top:"},{"t":"text","v":" the task, its "},{"t":"ui","v":"AI policy"},{"t":"text","v":", when the work was handed in, how long the candidate spent editing, and the "},{"t":"ui","v":"Evidence version"},{"t":"text","v":"."}],[{"t":"ui","v":"The code compared with the explanation"},{"t":"text","v":": whether the code and the defense tell the same story. For example, the code passes most tests but the candidate struggled to explain it."}],[{"t":"b","v":"Tests:"},{"t":"text","v":" which tests passed. For a work trial, "},{"t":"ui","v":"Planted defects"},{"t":"text","v":" shows which bugs the candidate fixed."}],[{"t":"ui","v":"Code changes"},{"t":"text","v":": what the candidate changed, file by file."}],[{"t":"ui","v":"AI assistant usage"},{"t":"text","v":": when AI was allowed, each question the candidate asked and how much of the final code came from the assistant."}],[{"t":"ui","v":"Integrity signals"},{"t":"text","v":": patterns worth talking about, such as code pasted from outside the editor, or code much like another candidate's. Each one says how much it adds to the signal score. Many have innocent explanations."}],[{"t":"ui","v":"Defense (voice or written)"},{"t":"text","v":": the score, the recording, and the questions and answers."}],[{"t":"ui","v":"Approved accommodations"},{"t":"text","v":" and "},{"t":"ui","v":"Candidate appeals"},{"t":"text","v":", if there are any."}],[{"t":"ui","v":"Decision history"},{"t":"text","v":": every decision recorded so far."}]]},{"t":"p","c":[{"t":"text","v":"The pack never includes voice sentiment or emotion analysis. Demographic data is only used in combined bias audit figures."}]},{"t":"h2","c":[{"t":"text","v":"Record your decision"}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"Record your decision"},{"t":"text","v":", choose "},{"t":"ui","v":"Advance"},{"t":"text","v":", "},{"t":"ui","v":"Hold"},{"t":"text","v":" or "},{"t":"ui","v":"Decline"},{"t":"text","v":"."}],[{"t":"text","v":"In "},{"t":"ui","v":"Rationale (shared with your team and connected ATS)"},{"t":"text","v":", write what in the evidence supports your decision. It needs at least 20 characters."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Submit decision"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"If the evidence changed after you opened the pack, for example because the defense just finished, Edulexa asks you to look again. Select "},{"t":"ui","v":"Reload evidence"},{"t":"text","v":", review it, and decide. An earlier decision stays in the history, marked "},{"t":"ui","v":"Evidence has changed since this decision"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"To keep a copy, select "},{"t":"ui","v":"Print / Save as PDF"},{"t":"text","v":". Candidates can "},{"t":"term","v":"appeal","key":"appeal"},{"t":"text","v":" your decision."}]}],"headings":["Find the work","What's in the pack","Record your decision"],"text":"Every piece of work handed in for a coding challenge or a work trial gets an evidence pack. It brings together what you need to decide fairly. Edulexa doesn't advance or turn down anyone: a reviewer records every decision, with a rationale. Find the work Open Evidence packs under Review. The Evidence review queue shows the work Awaiting decision first. You can narrow it by Challenge, by Integrity signals or by Decision. Select a candidate's name to open their pack. What's in the pack At the top: the task, its AI policy, when the work was handed in, how long the candidate spent editing, and the Evidence version.The code compared with the explanation: whether the code and the defense tell the same story. For example, the code passes most tests but the candidate struggled to explain it.Tests: which tests passed. For a work trial, Planted defects shows which bugs the candidate fixed.Code changes: what the candidate changed, file by file.AI assistant usage: when AI was allowed, each question the candidate asked and how much of the final code came from the assistant.Integrity signals: patterns worth talking about, such as code pasted from outside the editor, or code much like another candidate's. Each one says how much it adds to the signal score. Many have innocent explanations.Defense (voice or written): the score, the recording, and the questions and answers.Approved accommodations and Candidate appeals, if there are any.Decision history: every decision recorded so far. The pack never includes voice sentiment or emotion analysis. Demographic data is only used in combined bias audit figures. Record your decision Under Record your decision, choose Advance, Hold or Decline.In Rationale (shared with your team and connected ATS), write what in the evidence supports your decision. It needs at least 20 characters.Select Submit decision. If the evidence changed after you opened the pack, for example because the defense just finished, Edulexa asks you to look again. Select Reload evidence, review it, and decide. An earlier decision stays in the history, marked Evidence has changed since this decision. To keep a copy, select Print / Save as PDF. Candidates can appeal your decision."},{"slug":"recruiter-validity-and-bias","title":"Check validity and bias, and share outcomes","summary":"Record how the people you hired are doing, see whether scores predict that, check results for differences between groups, and choose whether to add your outcomes to the public report.","roles":["recruiter"],"group":"Fairness","features":["validity","transparency"],"checked":"2026-11-12","order":20,"short":["Record each hire's outcome, so you can see whether assessment scores predict how people do in the job.","The bias audit data compares groups of candidates. An impact ratio below 0.80 should be looked into.","Sharing your outcomes in the public transparency report is optional and off until you switch it on."],"blocks":[{"t":"p","c":[{"t":"ui","v":"Validity & bias audit"},{"t":"text","v":" under "},{"t":"ui","v":"Fairness"},{"t":"text","v":" helps you check two things: whether assessment scores predict how people do in the job, and whether results differ between groups of candidates."}]},{"t":"h2","c":[{"t":"text","v":"Record hiring outcomes"}]},{"t":"ol","items":[[{"t":"text","v":"Under "},{"t":"ui","v":"Record a hiring outcome"},{"t":"text","v":", enter the "},{"t":"ui","v":"Candidate email"},{"t":"text","v":"."}],[{"t":"text","v":"Tick "},{"t":"ui","v":"Hired"},{"t":"text","v":" if you hired them. When you know them, add their "},{"t":"ui","v":"Manager performance rating"},{"t":"text","v":", from 1 to 5, and whether they were "},{"t":"ui","v":"Retained after 90 days"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Save outcome"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The outcome is linked to the candidate's most recent piece of work."}]},{"t":"h2","c":[{"t":"text","v":"Do scores predict outcomes?"}]},{"t":"p","c":[{"t":"ui","v":"Predictive validity"},{"t":"text","v":" compares the share of tests passed and the "},{"t":"term","v":"voice defense","key":"voice-defense"},{"t":"text","v":" score with the manager's rating and with staying 90 days. For each pair it shows the number of hires, the correlation (how closely the two go together), its "},{"t":"ui","v":"Likely range (95%)"},{"t":"text","v":", and an "},{"t":"ui","v":"Interpretation"},{"t":"text","v":" in plain words. You need at least 30 hires with outcomes for a meaningful figure. To see one coding challenge, choose it in the list."}]},{"t":"h2","c":[{"t":"text","v":"Bias audit data"}]},{"t":"p","c":[{"t":"ui","v":"Bias audit data"},{"t":"text","v":" covers candidates who chose to describe themselves, by gender, race or ethnicity, age band and disability. For each group it shows:"}]},{"t":"ul","items":[[{"t":"ui","v":"Selection rate"},{"t":"text","v":": the share a person advanced."}],[{"t":"ui","v":"Scoring rate"},{"t":"text","v":": the share whose voice defense score is above the middle score of everyone."}],[{"t":"ui","v":"Impact ratio"},{"t":"text","v":": the group's rate divided by the highest group's rate. Below 0.80 is marked, because it fails the four-fifths rule and should be looked into."}]]},{"t":"p","c":[{"t":"text","v":"Describing themselves is voluntary for candidates, and the data is only reported as combined figures. Groups of fewer than 5 candidates aren't shown, to protect their privacy. Choose a challenge and dates if you like, then select "},{"t":"ui","v":"Download spreadsheet (CSV)"},{"t":"text","v":" to give the data to your auditor."}]},{"t":"note","c":[{"t":"text","v":"Under New York City's Local Law 144, the bias audit itself must be done by an independent auditor, and its summary published before use. This page gives you the data for it."}]},{"t":"h2","c":[{"t":"text","v":"Share your outcomes in the public report"}]},{"t":"p","c":[{"t":"text","v":"Edulexa's public transparency report shows whether assessment scores predict how people do in the job. Open "},{"t":"ui","v":"Transparency"},{"t":"text","v":" under "},{"t":"ui","v":"Fairness"},{"t":"text","v":" and switch on "},{"t":"ui","v":"Include our hire-outcome data"},{"t":"text","v":" to add yours. It's off until you switch it on."}]},{"t":"p","c":[{"t":"text","v":"Your outcomes are combined with those of other employers who take part. Your company is never named, and nothing is published until enough employers and hires take part. You can switch it off at any time. Reports already published don't change."}]}],"headings":["Record hiring outcomes","Do scores predict outcomes?","Bias audit data","Share your outcomes in the public report"],"text":"Validity & bias audit under Fairness helps you check two things: whether assessment scores predict how people do in the job, and whether results differ between groups of candidates. Record hiring outcomes Under Record a hiring outcome, enter the Candidate email.Tick Hired if you hired them. When you know them, add their Manager performance rating, from 1 to 5, and whether they were Retained after 90 days.Select Save outcome. The outcome is linked to the candidate's most recent piece of work. Do scores predict outcomes? Predictive validity compares the share of tests passed and the voice defense score with the manager's rating and with staying 90 days. For each pair it shows the number of hires, the correlation (how closely the two go together), its Likely range (95%), and an Interpretation in plain words. You need at least 30 hires with outcomes for a meaningful figure. To see one coding challenge, choose it in the list. Bias audit data Bias audit data covers candidates who chose to describe themselves, by gender, race or ethnicity, age band and disability. For each group it shows: Selection rate: the share a person advanced.Scoring rate: the share whose voice defense score is above the middle score of everyone.Impact ratio: the group's rate divided by the highest group's rate. Below 0.80 is marked, because it fails the four-fifths rule and should be looked into. Describing themselves is voluntary for candidates, and the data is only reported as combined figures. Groups of fewer than 5 candidates aren't shown, to protect their privacy. Choose a challenge and dates if you like, then select Download spreadsheet (CSV) to give the data to your auditor. Under New York City's Local Law 144, the bias audit itself must be done by an independent auditor, and its summary published before use. This page gives you the data for it. Share your outcomes in the public report Edulexa's public transparency report shows whether assessment scores predict how people do in the job. Open Transparency under Fairness and switch on Include our hire-outcome data to add yours. It's off until you switch it on. Your outcomes are combined with those of other employers who take part. Your company is never named, and nothing is published until enough employers and hires take part. You can switch it off at any time. Reports already published don't change."},{"slug":"resume-book","title":"Share a résumé book with employers","summary":"Open your school's résumé book, see which employers opened each résumé, and take an entry out when you need to.","roles":["staff"],"group":"Documents and résumés","features":["resume-books"],"checked":"2026-11-11","order":20,"short":["A career admin opens the résumé book in Settings, under Résumés.","Students choose whether to add a résumé. Only employers you approved can browse it.","Every time an employer opens a résumé, it's counted and recorded in the privacy log."],"blocks":[{"t":"p","c":[{"t":"text","v":"The résumé book holds résumés your students chose to share with the employers your school approved. Employers browse it by program, degree and graduation year."}]},{"t":"h2","c":[{"t":"text","v":"Open the résumé book"}]},{"t":"p","c":[{"t":"text","v":"A career admin opens it in "},{"t":"ui","v":"Settings"},{"t":"text","v":", under "},{"t":"ui","v":"Résumés"},{"t":"text","v":": tick "},{"t":"ui","v":"Open the résumé book"},{"t":"text","v":" and select "},{"t":"ui","v":"Save settings"},{"t":"text","v":". This option shows only while "},{"t":"ui","v":"Students use Edulexa's résumé tools"},{"t":"text","v":" is ticked."}]},{"t":"p","c":[{"t":"text","v":"Students then decide for themselves. Each one who wants to adds a résumé from their own "},{"t":"ui","v":"Résumés"},{"t":"text","v":" page and agrees to share it. If your school asks for approved résumés, they can only add one a reviewer approved in "},{"t":"link","v":"document review","href":"/help/staff-document-review"},{"t":"text","v":". Students can leave the book at any time."}]},{"t":"h2","c":[{"t":"text","v":"See who's in it"}]},{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Résumé book"},{"t":"text","v":" from the "},{"t":"ui","v":"Employers and jobs"},{"t":"text","v":" menu. For each student it shows their program, when they added their résumé, and how many times employers opened it, with the last date."}]},{"t":"p","c":[{"t":"text","v":"Every résumé an employer opens is recorded in your school's privacy log."}]},{"t":"h2","c":[{"t":"text","v":"Take a résumé out"}]},{"t":"p","c":[{"t":"text","v":"If a résumé shouldn't be there, select "},{"t":"ui","v":"Take out"},{"t":"text","v":" and write a "},{"t":"ui","v":"Reason for the student"},{"t":"text","v":". Employers stop seeing it at once. The student sees your reason and can add a résumé again."}]},{"t":"p","c":[{"t":"text","v":"Career admins, counselors and employer relations staff can all see the résumé book and take résumés out."}]},{"t":"h2","c":[{"t":"text","v":"Which employers see it"}]},{"t":"p","c":[{"t":"text","v":"Only employers your school approved. See "},{"t":"link","v":"Approve employers","href":"/help/employers-and-approvals"},{"t":"text","v":"."}]}],"headings":["Open the résumé book","See who's in it","Take a résumé out","Which employers see it"],"text":"The résumé book holds résumés your students chose to share with the employers your school approved. Employers browse it by program, degree and graduation year. Open the résumé book A career admin opens it in Settings, under Résumés: tick Open the résumé book and select Save settings. This option shows only while Students use Edulexa's résumé tools is ticked. Students then decide for themselves. Each one who wants to adds a résumé from their own Résumés page and agrees to share it. If your school asks for approved résumés, they can only add one a reviewer approved in document review. Students can leave the book at any time. See who's in it Open Résumé book from the Employers and jobs menu. For each student it shows their program, when they added their résumé, and how many times employers opened it, with the last date. Every résumé an employer opens is recorded in your school's privacy log. Take a résumé out If a résumé shouldn't be there, select Take out and write a Reason for the student. Employers stop seeing it at once. The student sees your reason and can add a résumé again. Career admins, counselors and employer relations staff can all see the résumé book and take résumés out. Which employers see it Only employers your school approved. See Approve employers."},{"slug":"your-account","title":"Your account, language and look","summary":"Your account page (name, password, two-step sign-in), your account menu, your language and US or British English, and light or dark.","roles":["everyone"],"group":"Account and settings","features":["interface-languages","sign-in"],"checked":"2026-11-11","order":20,"short":["Open your account menu (your initials, top right) and select Your account to change your name or password, or add an authenticator app or a passkey.","The language list at the top chooses US or British English.","For light or dark, use the sun and moon button, or Appearance in your account menu."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Your account menu"}]},{"t":"p","c":[{"t":"text","v":"Select the circle with your initials at the top right. It shows your name and e-mail address, and:"}]},{"t":"ul","items":[[{"t":"ui","v":"Your account"},{"t":"text","v":": your name, e-mail address, sign-in, and where you study or work. See below."}],[{"t":"text","v":"your other account pages. If you use Edulexa on your own, these are "},{"t":"ui","v":"Pricing and minutes"},{"t":"text","v":", "},{"t":"ui","v":"Privacy and your data"},{"t":"text","v":", "},{"t":"ui","v":"Fairness self-ID"},{"t":"text","v":" and "},{"t":"ui","v":"Transparency report"},{"t":"text","v":". At a school, your privacy and notification pages are in your school's menu."}],[{"t":"ui","v":"Switch to"},{"t":"text","v":", if you work in more than one area. See "},{"t":"link","v":"More than one school or role","href":"/help/switch-schools-and-roles"},{"t":"text","v":"."}],[{"t":"ui","v":"Appearance"},{"t":"text","v":", for light or dark."}],[{"t":"ui","v":"Sign out"},{"t":"text","v":"."}]]},{"t":"h2","c":[{"t":"text","v":"Language and spelling"}]},{"t":"p","c":[{"t":"text","v":"At the top of the page, next to the light and dark button, is the language list. It shows the language you're using, such as "},{"t":"ui","v":"English (US)"},{"t":"text","v":"."}]},{"t":"ul","items":[[{"t":"text","v":"Choose "},{"t":"ui","v":"English (US)"},{"t":"text","v":" or "},{"t":"b","v":"English (UK)"},{"t":"text","v":" for British spelling (\"color\" or \"colour\"). If you haven't chosen, you get your school's choice, or US English."}],[{"t":"text","v":"Spanish, Hindi and Arabic are being prepared. Each one is added to the list once a native speaker has checked it. If you see a language marked "},{"t":"b","v":"(preview)"},{"t":"text","v":", it's a draft, and some words may be wrong."}]]},{"t":"p","c":[{"t":"text","v":"Your choice applies to every page, and this browser remembers it."}]},{"t":"h2","c":[{"t":"text","v":"Light or dark"}]},{"t":"p","c":[{"t":"text","v":"Select the sun or moon button at the top of the page. Or open your account menu and, under "},{"t":"ui","v":"Appearance"},{"t":"text","v":", choose "},{"t":"ui","v":"Light"},{"t":"text","v":", "},{"t":"ui","v":"Dark"},{"t":"text","v":" or "},{"t":"ui","v":"System"},{"t":"text","v":" (the same as your computer or phone)."}]},{"t":"h2","c":[{"t":"text","v":"Your account page"}]},{"t":"p","c":[{"t":"text","v":"Open your account menu and select "},{"t":"ui","v":"Your account"},{"t":"text","v":". It shows your name and e-mail address, and every school or company you belong to on Edulexa, with your role there."}]},{"t":"ul","items":[[{"t":"b","v":"Your name:"},{"t":"text","v":" select "},{"t":"ui","v":"Change your name"},{"t":"text","v":". The sign-in page opens with your name; change it and save, and you come back here."}],[{"t":"b","v":"Your password:"},{"t":"text","v":" next to "},{"t":"ui","v":"Change your password"},{"t":"text","v":", select "},{"t":"ui","v":"Open"},{"t":"text","v":". Enter your new password twice. It needs at least 12 characters, and can't be your e-mail address or one of your last five passwords."}],[{"t":"b","v":"Two-step sign-in:"},{"t":"text","v":" next to "},{"t":"ui","v":"Set up an authenticator app"},{"t":"text","v":", select "},{"t":"ui","v":"Open"},{"t":"text","v":", and scan the code with an app on your phone. From then on you enter a code from the app each time you sign in. Or choose "},{"t":"ui","v":"Add a passkey"},{"t":"text","v":" to sign in with your fingerprint, face or your device's PIN."}]]},{"t":"p","c":[{"t":"text","v":"If you sign in with your school's account (your school's own sign-in page), your school manages your password. Change it the way your school tells you."}]},{"t":"h3","c":[{"t":"text","v":"Your e-mail address"}]},{"t":"p","c":[{"t":"text","v":"Your e-mail address links you to your school, so you can't change it yourself. To ask for a change, see "},{"t":"link","v":"Get help and contact support","href":"/help/help-and-support"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Forgot your password and can't sign in? Use "},{"t":"b","v":"Forgot Password?"},{"t":"text","v":" on the sign-in page. See "},{"t":"link","v":"Sign in and sign out","href":"/help/sign-in"},{"t":"text","v":"."}]}],"headings":["Your account menu","Language and spelling","Light or dark","Your account page","Your e-mail address"],"text":"Your account menu Select the circle with your initials at the top right. It shows your name and e-mail address, and: Your account: your name, e-mail address, sign-in, and where you study or work. See below.your other account pages. If you use Edulexa on your own, these are Pricing and minutes, Privacy and your data, Fairness self-ID and Transparency report. At a school, your privacy and notification pages are in your school's menu.Switch to, if you work in more than one area. See More than one school or role.Appearance, for light or dark.Sign out. Language and spelling At the top of the page, next to the light and dark button, is the language list. It shows the language you're using, such as English (US). Choose English (US) or English (UK) for British spelling (\"color\" or \"colour\"). If you haven't chosen, you get your school's choice, or US English.Spanish, Hindi and Arabic are being prepared. Each one is added to the list once a native speaker has checked it. If you see a language marked (preview), it's a draft, and some words may be wrong. Your choice applies to every page, and this browser remembers it. Light or dark Select the sun or moon button at the top of the page. Or open your account menu and, under Appearance, choose Light, Dark or System (the same as your computer or phone). Your account page Open your account menu and select Your account. It shows your name and e-mail address, and every school or company you belong to on Edulexa, with your role there. Your name: select Change your name. The sign-in page opens with your name; change it and save, and you come back here.Your password: next to Change your password, select Open. Enter your new password twice. It needs at least 12 characters, and can't be your e-mail address or one of your last five passwords.Two-step sign-in: next to Set up an authenticator app, select Open, and scan the code with an app on your phone. From then on you enter a code from the app each time you sign in. Or choose Add a passkey to sign in with your fingerprint, face or your device's PIN. If you sign in with your school's account (your school's own sign-in page), your school manages your password. Change it the way your school tells you. Your e-mail address Your e-mail address links you to your school, so you can't change it yourself. To ask for a change, see Get help and contact support. Forgot your password and can't sign in? Use Forgot Password? on the sign-in page. See Sign in and sign out."},{"slug":"rubric-and-viva","title":"Set the rubric and the viva","summary":"Decide what a good answer shows, how much each part counts, and how the viva runs.","roles":["teacher","admin"],"group":"Assessments","features":["class-assessments"],"checked":"2026-11-11","order":21,"short":["The rubric: 2 to 8 criteria, each scored 0 to 100, weights adding up to 100.","The viva: 3 to 10 questions, by voice or in writing, in the language you choose.","Students are judged on understanding, never on accent, grammar or spelling."],"blocks":[{"t":"h2","c":[{"t":"text","v":"The rubric"}]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"ui","v":"Rubric"},{"t":"text","v":" is the list of what you'll score, each from 0 to 100. Each template starts with its own criteria; an essay, for example, starts with the argument, the "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" and sources, understanding their own essay, handling other views, and explaining clearly."}]},{"t":"ul","items":[[{"t":"text","v":"Change any criterion's name, what a strong answer shows, and its weight."}],[{"t":"text","v":"Use "},{"t":"ui","v":"Add a criterion"},{"t":"text","v":" for more (between 2 and 8 criteria)."}],[{"t":"text","v":"The weights must add up to 100. The builder shows the running total."}]]},{"t":"p","c":[{"t":"text","v":"When you decide, you score each criterion, and the weighted score out of 100 is worked out for you."}]},{"t":"h2","c":[{"t":"text","v":"The viva"}]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"ui","v":"Viva"},{"t":"text","v":" is a short oral examination about the student's own work. An AI examiner asks the questions, one at a time, each about what the student handed in. It never gives hints, answers or scores."}]},{"t":"ul","items":[[{"t":"ui","v":"How students answer"},{"t":"text","v":": "},{"t":"ui","v":"By voice"},{"t":"text","v":", "},{"t":"ui","v":"In writing"},{"t":"text","v":", or "},{"t":"ui","v":"The student chooses"},{"t":"text","v":"."}],[{"t":"ui","v":"Questions"},{"t":"text","v":": between 3 and 10."}],[{"t":"ui","v":"Minutes"},{"t":"text","v":": about how long a voice "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":" lasts, between 5 and 30."}],[{"t":"ui","v":"Language"},{"t":"text","v":": the viva's language, or "},{"t":"ui","v":"Each student's own choice"},{"t":"text","v":" from their settings."}]]},{"t":"p","c":[{"t":"text","v":"Students are judged on understanding, never on accent, grammar or spelling."}]},{"t":"note","c":[{"t":"text","v":"Voice vivas use your school's "},{"t":"term","v":"AI voice minutes","key":"voice-minutes"},{"t":"text","v":". When there are none left, or voice doesn't work for a student, they answer in writing instead, and you see that it was written. See "},{"t":"link","v":"AI voice minutes and billing","href":"/help/billing-and-voice-minutes"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"A change task (code only)"}]},{"t":"p","c":[{"t":"text","v":"Project and coding assessments can also ask for one small change to the student's own code before the viva. See "},{"t":"link","v":"Add a change task","href":"/help/change-task"},{"t":"text","v":"."}]}],"headings":["The rubric","The viva","A change task (code only)"],"text":"The rubric The Rubric is the list of what you'll score, each from 0 to 100. Each template starts with its own criteria; an essay, for example, starts with the argument, the evidence and sources, understanding their own essay, handling other views, and explaining clearly. Change any criterion's name, what a strong answer shows, and its weight.Use Add a criterion for more (between 2 and 8 criteria).The weights must add up to 100. The builder shows the running total. When you decide, you score each criterion, and the weighted score out of 100 is worked out for you. The viva The Viva is a short oral examination about the student's own work. An AI examiner asks the questions, one at a time, each about what the student handed in. It never gives hints, answers or scores. How students answer: By voice, In writing, or The student chooses.Questions: between 3 and 10.Minutes: about how long a voice viva lasts, between 5 and 30.Language: the viva's language, or Each student's own choice from their settings. Students are judged on understanding, never on accent, grammar or spelling. Voice vivas use your school's AI voice minutes. When there are none left, or voice doesn't work for a student, they answer in writing instead, and you see that it was written. See AI voice minutes and billing. A change task (code only) Project and coding assessments can also ask for one small change to the student's own code before the viva. See Add a change task."},{"slug":"change-task","title":"Add a change task","summary":"Before the viva, ask for one small, timed change to the student's own code, checked by tests.","roles":["teacher","admin"],"group":"Assessments","features":["class-assessments"],"checked":"2026-11-11","order":22,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"A "},{"t":"term","v":"change task","key":"change-task"},{"t":"text","v":" shows whether students can work with their own code: someone who didn't write it usually can't change it quickly. It's available for "},{"t":"ui","v":"Project defense"},{"t":"text","v":" and "},{"t":"ui","v":"Coding task"},{"t":"text","v":" assessments."}]},{"t":"h2","c":[{"t":"text","v":"Turn it on"}]},{"t":"p","c":[{"t":"text","v":"In the assessment's "},{"t":"ui","v":"Change task"},{"t":"text","v":" section, tick "},{"t":"ui","v":"Ask for a small change to their own code"},{"t":"text","v":" and set the "},{"t":"ui","v":"Minutes for the change"},{"t":"text","v":" (between 10 and 60)."}]},{"t":"p","c":[{"t":"text","v":"Turning it on adds a criterion for the change (15%) to the "},{"t":"term","v":"rubric","key":"rubric"},{"t":"text","v":" and scales the others down to fit. You can edit it like any other criterion."}]},{"t":"h2","c":[{"t":"text","v":"What students get"}]},{"t":"p","c":[{"t":"text","v":"After a student hands in their work, the AI writes a short change request for their code and checks that it can be done. When it's ready, the student starts it; the clock runs from then. They work in the coding workspace on a copy of their own code, with the AI assistant off, and hand in their change. Hidden tests check it."}]},{"t":"h2","c":[{"t":"text","v":"What you see"}]},{"t":"p","c":[{"t":"text","v":"On the student's "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" page you see the request, how long they took, which tests passed, and exactly what they changed. If their change touched the tests themselves, you're told the results can't be trusted."}]},{"t":"note","c":[{"t":"text","v":"If the student's language isn't supported, or the change can't be prepared, the change task is skipped and the student goes straight to the "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":"; its criterion then doesn't count for them."}]}],"headings":["Turn it on","What students get","What you see"],"text":"A change task shows whether students can work with their own code: someone who didn't write it usually can't change it quickly. It's available for Project defense and Coding task assessments. Turn it on In the assessment's Change task section, tick Ask for a small change to their own code and set the Minutes for the change (between 10 and 60). Turning it on adds a criterion for the change (15%) to the rubric and scales the others down to fit. You can edit it like any other criterion. What students get After a student hands in their work, the AI writes a short change request for their code and checks that it can be done. When it's ready, the student starts it; the clock runs from then. They work in the coding workspace on a copy of their own code, with the AI assistant off, and hand in their change. Hidden tests check it. What you see On the student's evidence page you see the request, how long they took, which tests passed, and exactly what they changed. If their change touched the tests themselves, you're told the results can't be trusted. If the student's language isn't supported, or the change can't be prepared, the change task is skipped and the student goes straight to the viva; its criterion then doesn't count for them."},{"slug":"give-to-a-class","title":"Give an assessment to a class","summary":"Set when it opens and when it's due; students are e-mailed and see it in their list.","roles":["teacher","admin"],"group":"Assessments","features":["class-assessments"],"checked":"2026-11-11","order":23,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"An assessment must be published before you can give it to a class. See "},{"t":"link","v":"Create an assessment","href":"/help/create-an-assessment"},{"t":"text","v":"."}]},{"t":"ol","items":[[{"t":"text","v":"On the assessment, find "},{"t":"ui","v":"Give it to"},{"t":"text","v":" and "},{"t":"ui","v":"Choose a class"},{"t":"text","v":"."}],[{"t":"text","v":"Leave "},{"t":"ui","v":"Opens (optional)"},{"t":"text","v":" empty to open it now, or pick a date and time."}],[{"t":"text","v":"Set when it's "},{"t":"ui","v":"Due"},{"t":"text","v":"."}],[{"t":"text","v":"Decide whether to "},{"t":"ui","v":"Accept late work (marked late)"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Give to class"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Students are e-mailed when you give it to the class, and reminded before the due date. They find it under "},{"t":"ui","v":"My assessments"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"You can give the same assessment to several classes, each with its own dates. Each class then has its own page of students and their work."}]},{"t":"h2","c":[{"t":"text","v":"Following the class"}]},{"t":"p","c":[{"t":"text","v":"The class's page shows every student and where they are: "},{"t":"ui","v":"Not started"},{"t":"text","v":", "},{"t":"ui","v":"Working on it"},{"t":"text","v":", "},{"t":"ui","v":"Viva next"},{"t":"text","v":", "},{"t":"ui","v":"Ready for review"},{"t":"text","v":" and "},{"t":"ui","v":"Decided"},{"t":"text","v":". Open a student's "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" from there, or use the "},{"t":"ui","v":"Review"},{"t":"text","v":" page for everything waiting across your classes."}]},{"t":"note","c":[{"t":"text","v":"To withdraw it from a class before anyone has started, use "},{"t":"ui","v":"Take back"},{"t":"text","v":"."}]}],"headings":["Following the class"],"text":"An assessment must be published before you can give it to a class. See Create an assessment. On the assessment, find Give it to and Choose a class.Leave Opens (optional) empty to open it now, or pick a date and time.Set when it's Due.Decide whether to Accept late work (marked late).Select Give to class. Students are e-mailed when you give it to the class, and reminded before the due date. They find it under My assessments. You can give the same assessment to several classes, each with its own dates. Each class then has its own page of students and their work. Following the class The class's page shows every student and where they are: Not started, Working on it, Viva next, Ready for review and Decided. Open a student's evidence from there, or use the Review page for everything waiting across your classes. To withdraw it from a class before anyone has started, use Take back."},{"slug":"employer-resume-books","title":"Browse a school's résumé book","summary":"Find students' résumés in the résumé books of schools that approved your company, and know what's recorded when you open one.","roles":["employer"],"group":"Hiring","features":["resume-books"],"checked":"2026-11-12","order":30,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"A "},{"t":"term","v":"résumé book","key":"resume-book"},{"t":"text","v":" holds the résumés students chose to share with the employers their school approved. A school's book shows in "},{"t":"ui","v":"Résumé books"},{"t":"text","v":" once the school approves your company and opens its book."}]},{"t":"ol","items":[[{"t":"text","v":"Open "},{"t":"ui","v":"Résumé books"},{"t":"text","v":" under "},{"t":"ui","v":"Hiring"},{"t":"text","v":" and select a school."}],[{"t":"text","v":"Narrow the list by "},{"t":"ui","v":"Program"},{"t":"text","v":", "},{"t":"ui","v":"Degree"},{"t":"text","v":" and "},{"t":"ui","v":"Graduation year"},{"t":"text","v":", or type "},{"t":"ui","v":"Words in the résumé"},{"t":"text","v":". Then select "},{"t":"ui","v":"Search"},{"t":"text","v":"."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Open résumé"},{"t":"text","v":" to download it."}]]},{"t":"p","c":[{"t":"text","v":"Each résumé you open, and each search that finds one, is recorded and shown to the student and their school."}]},{"t":"p","c":[{"t":"text","v":"Students can leave the book at any time, and the school can take a résumé out. Either way, it disappears from your list straight away."}]},{"t":"p","c":[{"t":"text","v":"If no books show, ask more schools for approval on "},{"t":"ui","v":"Schools"},{"t":"text","v":". See "},{"t":"link","v":"Set up your company and ask to recruit at a school","href":"/help/employer-getting-started"},{"t":"text","v":"."}]}],"headings":[],"text":"A résumé book holds the résumés students chose to share with the employers their school approved. A school's book shows in Résumé books once the school approves your company and opens its book. Open Résumé books under Hiring and select a school.Narrow the list by Program, Degree and Graduation year, or type Words in the résumé. Then select Search.Select Open résumé to download it. Each résumé you open, and each search that finds one, is recorded and shown to the student and their school. Students can leave the book at any time, and the school can take a résumé out. Either way, it disappears from your list straight away. If no books show, ask more schools for approval on Schools. See Set up your company and ask to recruit at a school."},{"slug":"internships","title":"Internships for credit","summary":"Find an internship, register it for academic credit, sign the learning agreement, log your hours and write your reflections.","roles":["student"],"group":"Jobs and internships","features":["internships","campus-drives"],"checked":"2026-11-11","order":30,"short":["Find internships on the Job board and apply like any job.","For credit, select Register an experience under Internships, then Submit for approval.","Once approved, sign the agreement, log your hours each week and write your reflections."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Find an internship"}]},{"t":"p","c":[{"t":"text","v":"Internships offered through your school are on the "},{"t":"link","v":"Job board","href":"/student/jobs"},{"t":"text","v":", marked "},{"t":"ui","v":"Internship"},{"t":"text","v":". You apply as for any job: see "},{"t":"link","v":"Campus jobs and interviews","href":"/help/campus-jobs-and-interviews"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Register it for credit"}]},{"t":"p","c":[{"t":"text","v":"If your school gives academic credit for internships, open "},{"t":"link","v":"Internships","href":"/student/experiences"},{"t":"text","v":":"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Register an experience"},{"t":"text","v":"."}],[{"t":"text","v":"Choose the credit program and the organization (or enter a new one). Add your site supervisor and their work email, your role, your dates, hours per week and what you want to learn."}],[{"t":"text","v":"Save, upload any documents the program asks for, then select "},{"t":"ui","v":"Submit for approval"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"A faculty member approves it first, then the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":". To change something, select "},{"t":"ui","v":"Edit details"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Sign the learning agreement"}]},{"t":"p","c":[{"t":"text","v":"Once it's approved, you, your site supervisor and your faculty member each sign the learning agreement. Type your full name, tick that you agree, and select "},{"t":"ui","v":"Sign agreement"},{"t":"text","v":". Your supervisor signs from a link sent by email, without an account. If details in the agreement change later, everyone signs again."}]},{"t":"h2","c":[{"t":"text","v":"While you work"}]},{"t":"p","c":[{"t":"text","v":"From your start date, "},{"t":"ui","v":"Log hours"},{"t":"text","v":" each week. Your supervisor approves them. Answer the reflection questions and select "},{"t":"ui","v":"Save reflection"},{"t":"text","v":". Your faculty member may comment."}]},{"t":"h2","c":[{"t":"text","v":"What your school tracks"}]},{"t":"p","c":[{"t":"text","v":"The page shows each step: "},{"t":"ui","v":"Submitted"},{"t":"text","v":", approved, "},{"t":"ui","v":"Agreement signed"},{"t":"text","v":", "},{"t":"ui","v":"Active"},{"t":"text","v":", "},{"t":"ui","v":"Evaluations"},{"t":"text","v":" and "},{"t":"ui","v":"Completed"},{"t":"text","v":". Your supervisor is asked for a midterm evaluation when you start and a final one after your end date. Your faculty member then records your grade. The page also shows your approved hours against the hours needed, and everything that happened, with dates."}]},{"t":"p","c":[{"t":"text","v":"You can "},{"t":"ui","v":"Withdraw"},{"t":"text","v":" at any step before it's completed."}]},{"t":"note","c":[{"t":"text","v":"On an F-1 visa? The career center can approve only after the CPT dates on your I-20 and your school's approval date for it are recorded."}]}],"headings":["Find an internship","Register it for credit","Sign the learning agreement","While you work","What your school tracks"],"text":"Find an internship Internships offered through your school are on the Job board, marked Internship. You apply as for any job: see Campus jobs and interviews. Register it for credit If your school gives academic credit for internships, open Internships: Select Register an experience.Choose the credit program and the organization (or enter a new one). Add your site supervisor and their work email, your role, your dates, hours per week and what you want to learn.Save, upload any documents the program asks for, then select Submit for approval. A faculty member approves it first, then the career center. To change something, select Edit details. Sign the learning agreement Once it's approved, you, your site supervisor and your faculty member each sign the learning agreement. Type your full name, tick that you agree, and select Sign agreement. Your supervisor signs from a link sent by email, without an account. If details in the agreement change later, everyone signs again. While you work From your start date, Log hours each week. Your supervisor approves them. Answer the reflection questions and select Save reflection. Your faculty member may comment. What your school tracks The page shows each step: Submitted, approved, Agreement signed, Active, Evaluations and Completed. Your supervisor is asked for a midterm evaluation when you start and a final one after your end date. Your faculty member then records your grade. The page also shows your approved hours against the hours needed, and everything that happened, with dates. You can Withdraw at any step before it's completed. On an F-1 visa? The career center can approve only after the CPT dates on your I-20 and your school's approval date for it are recorded."},{"slug":"internships-and-placements","title":"Internships and placements","summary":"Review internships for credit, keep supervisors on track, and record your school's drives, offers and academic records under Placements.","roles":["staff"],"group":"Employers and jobs","features":["internships","placement-office"],"checked":"2026-11-11","order":30,"short":["Students register an internship for credit. After faculty approve it, the career center approves it and the learning agreement goes out for signatures.","Send the site supervisor a link to sign, approve hours and evaluate.","Placements keeps your school's own record of drives, offers and academic records."],"blocks":[{"t":"h2","c":[{"t":"text","v":"Internships for credit"}]},{"t":"p","c":[{"t":"text","v":"Students register an internship with its documents. Open "},{"t":"ui","v":"Internships"},{"t":"text","v":" from the "},{"t":"ui","v":"Employers and jobs"},{"t":"text","v":" menu. The "},{"t":"ui","v":"Dashboard"},{"t":"text","v":" shows what needs attention, such as agreements not fully signed and overdue evaluations. The "},{"t":"ui","v":"Review queue"},{"t":"text","v":" lists every internship."}]},{"t":"h3","c":[{"t":"text","v":"Approve an internship"}]},{"t":"p","c":[{"t":"text","v":"Open an internship. Under "},{"t":"ui","v":"Career-center review"},{"t":"text","v":" you'll see whether faculty have approved it and whether the required documents are in. For F-1 students whose program needs it, record the CPT dates first."}]},{"t":"p","c":[{"t":"text","v":"When everything is ready, select "},{"t":"ui","v":"Approve"},{"t":"text","v":". The learning agreement is created and sent for signatures. To turn it down, select "},{"t":"ui","v":"Decline"},{"t":"text","v":" with a comment the student sees."}]},{"t":"p","c":[{"t":"text","v":"Counselors and career admins approve internships. Career admins also set up the credit programs on the "},{"t":"ui","v":"Programs"},{"t":"text","v":" tab."}]},{"t":"h3","c":[{"t":"text","v":"Work with the site supervisor"}]},{"t":"p","c":[{"t":"text","v":"Supervisors don't need an account. Under "},{"t":"ui","v":"Site supervisor links"},{"t":"text","v":", send them a link to confirm and sign the agreement, approve hours, or fill in an evaluation. Each link does one job and expires after 30 days. When the internship is under way, "},{"t":"ui","v":"Open final evaluations now"},{"t":"text","v":" asks the supervisor for the final evaluation."}]},{"t":"h2","c":[{"t":"text","v":"Placements"}]},{"t":"p","c":[{"t":"ui","v":"Placements"},{"t":"text","v":" is your school's own record of "},{"t":"term","v":"campus drives","key":"campus-drive"},{"t":"text","v":", rounds, offers and packages. Companies don't post jobs here, and students don't apply here. Jobs employers send you are under "},{"t":"link","v":"Campus drives","href":"/help/jobs-drives-and-interviews"},{"t":"text","v":"."}]},{"t":"ul","items":[[{"t":"ui","v":"Record a drive"},{"t":"text","v":" with the criteria the company published, then open it to see who's eligible and record each round."}],[{"t":"text","v":"Add offers from a drive on its page. Use "},{"t":"ui","v":"Record an off-campus offer"},{"t":"text","v":" for the rest."}],[{"t":"text","v":"Career admins import "},{"t":"ui","v":"Academic records"},{"t":"text","v":", which the eligibility lists need."}]]},{"t":"p","c":[{"t":"text","v":"Students see their own results and offers on "},{"t":"ui","v":"My placement record"},{"t":"text","v":". Accepted offers become placements on the "},{"t":"link","v":"Outcomes","href":"/help/reports-and-outcomes"},{"t":"text","v":" page."}]}],"headings":["Internships for credit","Approve an internship","Work with the site supervisor","Placements"],"text":"Internships for credit Students register an internship with its documents. Open Internships from the Employers and jobs menu. The Dashboard shows what needs attention, such as agreements not fully signed and overdue evaluations. The Review queue lists every internship. Approve an internship Open an internship. Under Career-center review you'll see whether faculty have approved it and whether the required documents are in. For F-1 students whose program needs it, record the CPT dates first. When everything is ready, select Approve. The learning agreement is created and sent for signatures. To turn it down, select Decline with a comment the student sees. Counselors and career admins approve internships. Career admins also set up the credit programs on the Programs tab. Work with the site supervisor Supervisors don't need an account. Under Site supervisor links, send them a link to confirm and sign the agreement, approve hours, or fill in an evaluation. Each link does one job and expires after 30 days. When the internship is under way, Open final evaluations now asks the supervisor for the final evaluation. Placements Placements is your school's own record of campus drives, rounds, offers and packages. Companies don't post jobs here, and students don't apply here. Jobs employers send you are under Campus drives. Record a drive with the criteria the company published, then open it to see who's eligible and record each round.Add offers from a drive on its page. Use Record an off-campus offer for the rest.Career admins import Academic records, which the eligibility lists need. Students see their own results and offers on My placement record. Accepted offers become placements on the Outcomes page."},{"slug":"member-campus","title":"Campus","summary":"See coding tasks a school gives you, find out how campus jobs work, and check your connection before a voice interview.","roles":["member"],"group":"Your record","features":["campus-cohorts"],"checked":"2026-11-12","order":30,"short":["Campus is under Your record. It shows coding tasks a school or training program gives you, once one adds your e-mail address.","Campus jobs come through a school's career center, so they're only for that school's students and graduates.","Before a voice interview, select Check my connection."],"blocks":[{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Your record"},{"t":"text","v":" and select "},{"t":"ui","v":"Campus"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Tasks from your school"}]},{"t":"p","c":[{"t":"text","v":"Some schools and training programs give their students coding tasks on Edulexa. When one adds your e-mail address to a class or group, its tasks show under "},{"t":"ui","v":"Tasks from your school"},{"t":"text","v":", with the date each one opens and is due."}]},{"t":"p","c":[{"t":"text","v":"If no school has added you, you see "},{"t":"ui","v":"No tasks from a school yet"},{"t":"text","v":". Nothing is wrong: you don't need a school to practice. Select "},{"t":"ui","v":"Try a coding challenge"},{"t":"text","v":" or "},{"t":"ui","v":"Practice an interview"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"A school's task has three steps:"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Start"},{"t":"text","v":" (later "},{"t":"ui","v":"Continue"},{"t":"text","v":") and write or fix code in the browser. Your changes are saved as you go."}],[{"t":"text","v":"Submit it. Hidden tests run on your code, and your score is the share of tests that pass."}],[{"t":"text","v":"Explain your code in a short voice conversation with an AI interviewer. You need a microphone and a quiet place."}]]},{"t":"p","c":[{"t":"text","v":"Your test and defense scores then show on the task. The school sees them too, with a readiness level: "},{"t":"ui","v":"Ready"},{"t":"text","v":", "},{"t":"ui","v":"Nearly ready"},{"t":"text","v":" or "},{"t":"ui","v":"Needs practice"},{"t":"text","v":"."}]},{"t":"h3","c":[{"t":"text","v":"Defense language"}]},{"t":"p","c":[{"t":"text","v":"Once a school has added you, "},{"t":"ui","v":"Defense language"},{"t":"text","v":" shows on Campus. Choose the language you'd like to explain your code in and select "},{"t":"ui","v":"Save"},{"t":"text","v":". You can still change it when the conversation starts."}]},{"t":"h2","c":[{"t":"text","v":"Jobs through a school"}]},{"t":"p","c":[{"t":"text","v":"Employers offer campus jobs, internships and interviews through a school's "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":", so only that school's students and graduates can apply. Edulexa doesn't list jobs for people without a school."}]},{"t":"ul","items":[[{"t":"text","v":"If your school uses Edulexa, sign in with the e-mail address your school has for you. "},{"t":"ui","v":"My school"},{"t":"text","v":" then shows under "},{"t":"ui","v":"Switch to"},{"t":"text","v":" in your account menu, and Campus shows "},{"t":"ui","v":"Open My school"},{"t":"text","v":"."}],[{"t":"text","v":"Applying for a job you found somewhere else? Select "},{"t":"ui","v":"Check your résumé against a job"},{"t":"text","v":" to see where your résumé meets its requirements. See "},{"t":"link","v":"Résumés, job check and cover letters","href":"/help/member-resumes"},{"t":"text","v":"."}]]},{"t":"h2","c":[{"t":"text","v":"Check your connection"}]},{"t":"p","c":[{"t":"text","v":"Before a voice interview or a defense, select "},{"t":"ui","v":"Check my connection"},{"t":"text","v":". It runs 5 quick checks and a small download, and uses very little data. You see one of:"}]},{"t":"ul","items":[[{"t":"ui","v":"Good"},{"t":"text","v":": you're ready."}],[{"t":"ui","v":"Usable, with care"},{"t":"text","v":": close other apps and tabs, especially video, and stay close to your Wi-Fi router."}],[{"t":"ui","v":"Try a better network"},{"t":"text","v":": move closer to your router, use a wired connection or find a stronger mobile signal, then check again."}]]},{"t":"note","c":[{"t":"text","v":"To check your microphone, see "},{"t":"link","v":"Check your microphone and browser","href":"/help/microphone-and-browser"},{"t":"text","v":"."}]}],"headings":["Tasks from your school","Defense language","Jobs through a school","Check your connection"],"text":"Open Your record and select Campus. Tasks from your school Some schools and training programs give their students coding tasks on Edulexa. When one adds your e-mail address to a class or group, its tasks show under Tasks from your school, with the date each one opens and is due. If no school has added you, you see No tasks from a school yet. Nothing is wrong: you don't need a school to practice. Select Try a coding challenge or Practice an interview. A school's task has three steps: Select Start (later Continue) and write or fix code in the browser. Your changes are saved as you go.Submit it. Hidden tests run on your code, and your score is the share of tests that pass.Explain your code in a short voice conversation with an AI interviewer. You need a microphone and a quiet place. Your test and defense scores then show on the task. The school sees them too, with a readiness level: Ready, Nearly ready or Needs practice. Defense language Once a school has added you, Defense language shows on Campus. Choose the language you'd like to explain your code in and select Save. You can still change it when the conversation starts. Jobs through a school Employers offer campus jobs, internships and interviews through a school's career center, so only that school's students and graduates can apply. Edulexa doesn't list jobs for people without a school. If your school uses Edulexa, sign in with the e-mail address your school has for you. My school then shows under Switch to in your account menu, and Campus shows Open My school.Applying for a job you found somewhere else? Select Check your résumé against a job to see where your résumé meets its requirements. See Résumés, job check and cover letters. Check your connection Before a voice interview or a defense, select Check my connection. It runs 5 quick checks and a small download, and uses very little data. You see one of: Good: you're ready.Usable, with care: close other apps and tabs, especially video, and stay close to your Wi-Fi router.Try a better network: move closer to your router, use a wired connection or find a stronger mobile signal, then check again. To check your microphone, see Check your microphone and browser."},{"slug":"messages","title":"Message the career center","summary":"Write to your career center, reply in a conversation, and find earlier messages.","roles":["student","alumni"],"group":"Career help","features":["messaging"],"checked":"2026-11-11","order":30,"short":["In Messages, select Message the career center, add a subject and your message, and select Send.","Answers come back in the same conversation, and you get a notification."],"blocks":[{"t":"p","c":[{"t":"link","v":"Messages","href":"/student/messages"},{"t":"text","v":" holds your private conversations with the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":". While you have an active mentorship, your conversation with your "},{"t":"term","v":"mentor","key":"mentoring"},{"t":"text","v":" is here too. Only you and the people in a conversation can read it."}]},{"t":"h2","c":[{"t":"text","v":"Start a conversation"}]},{"t":"ol","items":[[{"t":"text","v":"Select "},{"t":"ui","v":"Message the career center"},{"t":"text","v":"."}],[{"t":"text","v":"Write a "},{"t":"ui","v":"Subject"},{"t":"text","v":" and your "},{"t":"ui","v":"Message"},{"t":"text","v":". You can attach one file: PDF, Word, PNG, JPEG or text, up to 10 MB."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Send"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"Someone at the career center answers in the same conversation. You get a notification when they do."}]},{"t":"h2","c":[{"t":"text","v":"Reply and keep track"}]},{"t":"p","c":[{"t":"text","v":"Open a conversation from the list, write under "},{"t":"ui","v":"Reply"},{"t":"text","v":", and select "},{"t":"ui","v":"Send"},{"t":"text","v":". Each of your messages shows "},{"t":"ui","v":"Sent"},{"t":"text","v":", then "},{"t":"ui","v":"Seen"},{"t":"text","v":" once it's been read. To find an older message, use "},{"t":"ui","v":"Search messages"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"When your question is answered, select "},{"t":"ui","v":"Close conversation"},{"t":"text","v":". If you write in it again later, it opens again."}]},{"t":"note","c":[{"t":"text","v":"Never send passwords, or numbers from official papers such as a passport, in messages."}]},{"t":"p","c":[{"t":"text","v":"A conversation with a mentor takes new messages only while the mentorship is active. After it ends, you can still read it. See "},{"t":"link","v":"Find a mentor","href":"/help/mentoring"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"If a message is wrong"}]},{"t":"p","c":[{"t":"text","v":"If a message is rude, unsafe or spam, select "},{"t":"ui","v":"Report"},{"t":"text","v":" next to it, choose a reason, and select "},{"t":"ui","v":"Send report"},{"t":"text","v":". The career center reviews every report."}]},{"t":"h2","c":[{"t":"text","v":"Announcements by email"}]},{"t":"p","c":[{"t":"text","v":"The career center also emails announcements to groups of students. Each one has a link at the bottom to stop that kind of announcement. You still get emails about your own conversations and appointments."}]}],"headings":["Start a conversation","Reply and keep track","If a message is wrong","Announcements by email"],"text":"Messages holds your private conversations with the career center. While you have an active mentorship, your conversation with your mentor is here too. Only you and the people in a conversation can read it. Start a conversation Select Message the career center.Write a Subject and your Message. You can attach one file: PDF, Word, PNG, JPEG or text, up to 10 MB.Select Send. Someone at the career center answers in the same conversation. You get a notification when they do. Reply and keep track Open a conversation from the list, write under Reply, and select Send. Each of your messages shows Sent, then Seen once it's been read. To find an older message, use Search messages. When your question is answered, select Close conversation. If you write in it again later, it opens again. Never send passwords, or numbers from official papers such as a passport, in messages. A conversation with a mentor takes new messages only while the mentorship is active. After it ends, you can still read it. See Find a mentor. If a message is wrong If a message is rude, unsafe or spam, select Report next to it, choose a reason, and select Send report. The career center reviews every report. Announcements by email The career center also emails announcements to groups of students. Each one has a link at the bottom to stop that kind of announcement. You still get emails about your own conversations and appointments."},{"slug":"notifications","title":"Notifications and e-mails","summary":"What Edulexa tells you in the app and by e-mail, and how to choose which ones you get.","roles":["everyone"],"group":"Account and settings","features":["notifications","messaging","chat-sms"],"checked":"2026-11-11","order":30,"short":["The bell at the top of the page opens your notifications.","Under Notification preferences, untick In app or Email for any kind you don't want.","Announcements from a career center have an unsubscribe link at the bottom of the e-mail."],"blocks":[{"t":"p","c":[{"t":"text","v":"The bell at the top of the page shows how many notifications you haven't read. Select it to see them all. You'll also find "},{"t":"ui","v":"Notifications"},{"t":"text","v":" under "},{"t":"ui","v":"More settings"},{"t":"text","v":" on "},{"t":"link","v":"Your account","href":"/help/your-account"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"What you're told about"}]},{"t":"p","c":[{"t":"text","v":"Things that are new for you or need you: for example, a new assessment, a "},{"t":"term","v":"decision","key":"decision"},{"t":"text","v":" on your work, a booked or cancelled appointment, or a reviewed document."}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Open"},{"t":"text","v":" to go to it, or "},{"t":"ui","v":"Mark read"},{"t":"text","v":". Each notification also comes by e-mail, unless you turn that off."}]},{"t":"h2","c":[{"t":"text","v":"Choose what you get"}]},{"t":"p","c":[{"t":"text","v":"At the bottom of the notifications page, under "},{"t":"ui","v":"Notification preferences"},{"t":"text","v":", each kind of notification you've had has two boxes: "},{"t":"ui","v":"In app"},{"t":"text","v":" and "},{"t":"ui","v":"Email"},{"t":"text","v":". Untick a box to stop that kind; it's saved at once."}]},{"t":"note","c":[{"t":"text","v":"On a phone with data saving on, the preferences load only when you ask: select "},{"t":"b","v":"Load notification settings"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Announcements from your career center"}]},{"t":"p","c":[{"t":"term","v":"Career centers","key":"career-center"},{"t":"text","v":" send announcements by e-mail to groups of students and graduates. Each one has an unsubscribe link at the bottom. It opens "},{"t":"ui","v":"Email preferences"},{"t":"text","v":", where you can stop that kind of announcement, or select "},{"t":"ui","v":"Unsubscribe from all campaign emails"},{"t":"text","v":". E-mails about your own appointments, conversations and requests still come."}]},{"t":"h2","c":[{"t":"text","v":"WhatsApp and text messages"}]},{"t":"p","c":[{"t":"text","v":"If your school has turned them on, students can get short reminders on WhatsApp or by text message. Open "},{"t":"ui","v":"Chat & SMS"},{"t":"text","v":", enter your mobile number, agree, and select "},{"t":"ui","v":"Send me a code"},{"t":"text","v":". Enter the code and select "},{"t":"ui","v":"Confirm"},{"t":"text","v":". To stop, select "},{"t":"ui","v":"Turn off WhatsApp"},{"t":"text","v":" (or SMS), or reply STOP to any message."}]},{"t":"h2","c":[{"t":"text","v":"Without a school"}]},{"t":"p","c":[{"t":"text","v":"If you use Edulexa on your own, or as a recruiter, "},{"t":"term","v":"mentor","key":"mentoring"},{"t":"text","v":" or admissions counselor, the bell is at the top of your pages too. Your notifications page works the same way, with the same choices."}]}],"headings":["What you're told about","Choose what you get","Announcements from your career center","WhatsApp and text messages","Without a school"],"text":"The bell at the top of the page shows how many notifications you haven't read. Select it to see them all. You'll also find Notifications under More settings on Your account. What you're told about Things that are new for you or need you: for example, a new assessment, a decision on your work, a booked or cancelled appointment, or a reviewed document. Select Open to go to it, or Mark read. Each notification also comes by e-mail, unless you turn that off. Choose what you get At the bottom of the notifications page, under Notification preferences, each kind of notification you've had has two boxes: In app and Email. Untick a box to stop that kind; it's saved at once. On a phone with data saving on, the preferences load only when you ask: select Load notification settings. Announcements from your career center Career centers send announcements by e-mail to groups of students and graduates. Each one has an unsubscribe link at the bottom. It opens Email preferences, where you can stop that kind of announcement, or select Unsubscribe from all campaign emails. E-mails about your own appointments, conversations and requests still come. WhatsApp and text messages If your school has turned them on, students can get short reminders on WhatsApp or by text message. Open Chat & SMS, enter your mobile number, agree, and select Send me a code. Enter the code and select Confirm. To stop, select Turn off WhatsApp (or SMS), or reply STOP to any message. Without a school If you use Edulexa on your own, or as a recruiter, mentor or admissions counselor, the bell is at the top of your pages too. Your notifications page works the same way, with the same choices."},{"slug":"review-the-evidence","title":"Review a student's evidence","summary":"Read the work, the viva and the AI's suggested scores, and look at the points worth asking about.","roles":["teacher","admin"],"group":"Reviewing and deciding","features":["class-assessments"],"checked":"2026-11-11","order":30,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"Open "},{"t":"ui","v":"Review"},{"t":"text","v":" to see every "},{"t":"term","v":"attempt","key":"attempt"},{"t":"text","v":" waiting for your "},{"t":"term","v":"decision","key":"decision"},{"t":"text","v":" across your classes, oldest first. Work handed in after the due date is marked "},{"t":"ui","v":"Late"},{"t":"text","v":". Select "},{"t":"ui","v":"Review"},{"t":"text","v":" next to a student to see their evidence."}]},{"t":"shot","name":"review-queue","alt":"The Review page's To decide tab, with three lab reports waiting for a decision, oldest first, and one marked Late","w":1600,"h":639},{"t":"h2","c":[{"t":"text","v":"What the evidence page shows"}]},{"t":"ul","items":[[{"t":"b","v":"The work."},{"t":"text","v":" Whatever the student handed in: the text of their document by page or slide (with "},{"t":"ui","v":"Download the original"},{"t":"text","v":"), their repository or project files, their coding task with its tests, or their exam answers."}],[{"t":"b","v":"The change task"},{"t":"text","v":", if the assessment has one."}],[{"t":"b","v":"The viva."},{"t":"text","v":" Every question and answer, whether it was by voice or in writing, and how long it took."}],[{"t":"text","v":"The "},{"t":"ui","v":"Suggested scores"},{"t":"text","v":": the AI's suggestion for each criterion, with a short reason and, where it can, a quote from the student's own answers or work. It's only a suggestion: students never see it, and you decide."}],[{"t":"text","v":"The "},{"t":"ui","v":"Points to talk about"},{"t":"text","v":": patterns worth asking the student about, for example work much like another student's, answers read out from the document, or a "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":" answered in writing after voice failed. They're not findings, and nothing here decides anything."}]]},{"t":"shot","name":"suggested-scores","alt":"The Suggested scores on a student's evidence page, with a score and a short reason for each criterion, and quotes from the student's work and viva","w":502,"h":1359},{"t":"note","c":[{"t":"text","v":"Each time you open a student's evidence, it's recorded, as it is for any student record."}]},{"t":"p","c":[{"t":"text","v":"When you're ready, decide on the same page. See "},{"t":"link","v":"Decide and handle appeals","href":"/help/decide-and-appeals"},{"t":"text","v":"."}]}],"headings":["What the evidence page shows"],"text":"Open Review to see every attempt waiting for your decision across your classes, oldest first. Work handed in after the due date is marked Late. Select Review next to a student to see their evidence. What the evidence page shows The work. Whatever the student handed in: the text of their document by page or slide (with Download the original), their repository or project files, their coding task with its tests, or their exam answers.The change task, if the assessment has one.The viva. Every question and answer, whether it was by voice or in writing, and how long it took.The Suggested scores: the AI's suggestion for each criterion, with a short reason and, where it can, a quote from the student's own answers or work. It's only a suggestion: students never see it, and you decide.The Points to talk about: patterns worth asking the student about, for example work much like another student's, answers read out from the document, or a viva answered in writing after voice failed. They're not findings, and nothing here decides anything. Each time you open a student's evidence, it's recorded, as it is for any student record. When you're ready, decide on the same page. See Decide and handle appeals."},{"slug":"staff-messages","title":"Message students","summary":"Answer students in the shared inbox, start a conversation, keep notes only staff can see, and send announcements to groups.","roles":["staff"],"group":"Students and appointments","features":["messaging"],"checked":"2026-11-11","order":30,"short":["Messages & campaigns is one inbox shared by all career staff.","Assign a conversation to yourself so colleagues know who's answering, and close it when it's done.","Use Campaigns to send one announcement to a group of students or alumni."],"blocks":[{"t":"p","c":[{"t":"ui","v":"Messages & campaigns"},{"t":"text","v":" is the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":"'s shared inbox. Every career staff member can use it."}]},{"t":"h2","c":[{"t":"text","v":"Answer a conversation"}]},{"t":"p","c":[{"t":"text","v":"On "},{"t":"ui","v":"Inbox"},{"t":"text","v":", choose what to "},{"t":"ui","v":"Show"},{"t":"text","v":": "},{"t":"ui","v":"All open"},{"t":"text","v":", "},{"t":"ui","v":"Unassigned"},{"t":"text","v":", "},{"t":"ui","v":"Assigned to me"},{"t":"text","v":", "},{"t":"ui","v":"Closed"},{"t":"text","v":" or "},{"t":"ui","v":"Everything"},{"t":"text","v":". You can also search by subject, student or text. Select a conversation to read it."}]},{"t":"p","c":[{"t":"text","v":"In a conversation you can:"}]},{"t":"ul","items":[[{"t":"text","v":"Write your answer under "},{"t":"ui","v":"Reply"},{"t":"text","v":", attach a file if you need to, and select "},{"t":"ui","v":"Send"},{"t":"text","v":"."}],[{"t":"text","v":"Tick "},{"t":"ui","v":"Internal note"},{"t":"text","v":" to write something only staff can see, then select "},{"t":"ui","v":"Add note"},{"t":"text","v":"."}],[{"t":"text","v":"Choose who it's "},{"t":"ui","v":"Assigned to"},{"t":"text","v":", so your colleagues know who's answering."}],[{"t":"ui","v":"Close"},{"t":"text","v":" it when it's done. If the student writes again, it opens again."}]]},{"t":"h2","c":[{"t":"text","v":"Start a conversation"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Message a student"},{"t":"text","v":", find the student or alumnus by name, email or student number, then write a "},{"t":"ui","v":"Subject"},{"t":"text","v":" and "},{"t":"ui","v":"Message"},{"t":"text","v":" and select "},{"t":"ui","v":"Send"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Send an announcement"}]},{"t":"p","c":[{"t":"text","v":"On "},{"t":"ui","v":"Campaigns"},{"t":"text","v":", select "},{"t":"ui","v":"New campaign"},{"t":"text","v":". Choose email, an in-app notification or both, write the message, and choose "},{"t":"ui","v":"Who receives it"},{"t":"text","v":", for example by graduation date or major. Select "},{"t":"ui","v":"Preview recipients"},{"t":"text","v":" to check who gets it, then "},{"t":"ui","v":"Send now"},{"t":"text","v":", "},{"t":"ui","v":"Schedule"},{"t":"text","v":" it, or "},{"t":"ui","v":"Save draft"},{"t":"text","v":". Students can unsubscribe from each category of email."}]},{"t":"h2","c":[{"t":"text","v":"Reported messages"}]},{"t":"p","c":[{"t":"text","v":"When someone reports a message, it appears on "},{"t":"ui","v":"Reports"},{"t":"text","v":". Read the conversation, then "},{"t":"ui","v":"Mark resolved"},{"t":"text","v":" with a note. Counselors and career admins resolve reports."}]}],"headings":["Answer a conversation","Start a conversation","Send an announcement","Reported messages"],"text":"Messages & campaigns is the career center's shared inbox. Every career staff member can use it. Answer a conversation On Inbox, choose what to Show: All open, Unassigned, Assigned to me, Closed or Everything. You can also search by subject, student or text. Select a conversation to read it. In a conversation you can: Write your answer under Reply, attach a file if you need to, and select Send.Tick Internal note to write something only staff can see, then select Add note.Choose who it's Assigned to, so your colleagues know who's answering.Close it when it's done. If the student writes again, it opens again. Start a conversation Select Message a student, find the student or alumnus by name, email or student number, then write a Subject and Message and select Send. Send an announcement On Campaigns, select New campaign. Choose email, an in-app notification or both, write the message, and choose Who receives it, for example by graduation date or major. Select Preview recipients to check who gets it, then Send now, Schedule it, or Save draft. Students can unsubscribe from each category of email. Reported messages When someone reports a message, it appears on Reports. Read the conversation, then Mark resolved with a note. Counselors and career admins resolve reports."},{"slug":"decide-and-appeals","title":"Decide and handle appeals","summary":"Score each criterion, choose pass, resubmit or fail, and answer a student's appeal.","roles":["teacher","admin"],"group":"Reviewing and deciding","features":["class-assessments"],"checked":"2026-11-11","order":31,"short":[],"blocks":[{"t":"h2","c":[{"t":"text","v":"Decide"}]},{"t":"p","c":[{"t":"text","v":"Under "},{"t":"ui","v":"Your decision"},{"t":"text","v":" on the student's "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" page:"}]},{"t":"ol","items":[[{"t":"text","v":"Score each criterion with a whole number from 0 to 100. Each starts from the AI's suggestion when there is one; change any you disagree with. The weighted score is worked out for you."}],[{"t":"text","v":"Choose "},{"t":"ui","v":"Pass"},{"t":"text","v":", "},{"t":"ui","v":"Resubmit"},{"t":"text","v":" or "},{"t":"ui","v":"Fail"},{"t":"text","v":"."}],[{"t":"text","v":"Write a "},{"t":"ui","v":"Comment for the student"},{"t":"text","v":". It's needed to ask for a resubmission or to fail, so the student knows why."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Save decision"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The student sees your "},{"t":"term","v":"decision","key":"decision"},{"t":"text","v":", your scores and your comment. They never see the AI's suggestions."}]},{"t":"ul","items":[[{"t":"b","v":"Pass:"},{"t":"text","v":" if the assessment issues "},{"t":"term","v":"credentials","key":"credential"},{"t":"text","v":", a signed credential is added to the student's "},{"t":"term","v":"wallet","key":"wallet"},{"t":"text","v":". Anyone can verify it."}],[{"t":"b","v":"Resubmit:"},{"t":"text","v":" the student can hand in again, even after the due date. Their next "},{"t":"term","v":"attempt","key":"attempt"},{"t":"text","v":" starts fresh, with your feedback shown to them."}],[{"t":"b","v":"Fail:"},{"t":"text","v":" the student is told they didn't pass, and that they can "},{"t":"term","v":"appeal","key":"appeal"},{"t":"text","v":"."}]]},{"t":"note","c":[{"t":"text","v":"If the student's work or "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":" changes after you decide, the evidence page says so."}]},{"t":"h2","c":[{"t":"text","v":"Appeals"}]},{"t":"p","c":[{"t":"text","v":"A student can appeal a decision once, within 14 days. Appeals appear under "},{"t":"ui","v":"Appeals"},{"t":"text","v":" on the "},{"t":"ui","v":"Review"},{"t":"text","v":" page. You can't answer an appeal of your own decision: another teacher of the class, or a school admin, does."}]},{"t":"p","c":[{"t":"text","v":"Open the appeal, read the student's reason, and write a "},{"t":"ui","v":"Response to the student"},{"t":"text","v":". Then either "},{"t":"ui","v":"Keep the decision"},{"t":"text","v":" or "},{"t":"ui","v":"Change it"},{"t":"text","v":" and "},{"t":"ui","v":"Save the new decision"},{"t":"text","v":". The student sees your response."}]}],"headings":["Decide","Appeals"],"text":"Decide Under Your decision on the student's evidence page: Score each criterion with a whole number from 0 to 100. Each starts from the AI's suggestion when there is one; change any you disagree with. The weighted score is worked out for you.Choose Pass, Resubmit or Fail.Write a Comment for the student. It's needed to ask for a resubmission or to fail, so the student knows why.Select Save decision. The student sees your decision, your scores and your comment. They never see the AI's suggestions. Pass: if the assessment issues credentials, a signed credential is added to the student's wallet. Anyone can verify it.Resubmit: the student can hand in again, even after the due date. Their next attempt starts fresh, with your feedback shown to them.Fail: the student is told they didn't pass, and that they can appeal. If the student's work or viva changes after you decide, the evidence page says so. Appeals A student can appeal a decision once, within 14 days. Appeals appear under Appeals on the Review page. You can't answer an appeal of your own decision: another teacher of the class, or a school admin, does. Open the appeal, read the student's reason, and write a Response to the student. Then either Keep the decision or Change it and Save the new decision. The student sees your response."},{"slug":"mentoring","title":"Find a mentor","summary":"Find an alum or a professional to mentor you, ask them, and what happens once you're matched.","roles":["student","alumni"],"group":"Career help","features":["mentoring"],"checked":"2026-11-11","order":40,"short":["In Mentoring, pick a mentor from Suggested for you or Browse mentors, and ask them.","Say why you chose them and what your goals are. You can withdraw until they accept.","Once matched, message each other, log your meetings, and finish with feedback."],"blocks":[{"t":"p","c":[{"t":"text","v":"Mentors are alumni and professionals your "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" has approved. They volunteer, so be clear about what you'd like help with. Open "},{"t":"link","v":"Mentoring","href":"/student/mentoring"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Find a mentor"}]},{"t":"p","c":[{"t":"ui","v":"Suggested for you"},{"t":"text","v":" lists mentors who fit what you want. Select "},{"t":"ui","v":"Edit what I'm looking for"},{"t":"text","v":" to choose topics, industries and fields of work, then "},{"t":"ui","v":"Save preferences"},{"t":"text","v":". Suggestions also use the major on your "},{"t":"link","v":"career record","href":"/student/record"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Or search under "},{"t":"ui","v":"Browse mentors"},{"t":"text","v":". Each mentor shows what they help with and how many spots are open."}]},{"t":"h2","c":[{"t":"text","v":"Ask for mentoring"}]},{"t":"ol","items":[[{"t":"text","v":"On a mentor's card, select "},{"t":"b","v":"Ask for mentoring"},{"t":"text","v":"."}],[{"t":"text","v":"Introduce yourself and say why you chose them. Add your goals, one per line (up to 5)."}],[{"t":"text","v":"Tick the box to agree that your name, email and phone are shared with the mentor if you both accept."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Send request"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"The request shows under "},{"t":"ui","v":"My mentorships"},{"t":"text","v":" as "},{"t":"ui","v":"Waiting for mentor"},{"t":"text","v":". At some schools the career center confirms each match first: "},{"t":"ui","v":"Waiting for career center"},{"t":"text","v":". You can have only a few requests waiting at once. Changed your mind? Select "},{"t":"ui","v":"Withdraw request"},{"t":"text","v":" before it's accepted."}]},{"t":"h2","c":[{"t":"text","v":"Once you're matched"}]},{"t":"p","c":[{"t":"text","v":"The mentorship becomes "},{"t":"ui","v":"Active"},{"t":"text","v":", and you both see each other's contact details. Then you can:"}]},{"t":"ul","items":[[{"t":"text","v":"send private messages, here or in "},{"t":"link","v":"Messages","href":"/help/messages"},{"t":"text","v":". The career center reads them only if one of you reports a problem."}],[{"t":"ui","v":"Log a session"},{"t":"text","v":" after you meet. Notes are private to the two of you; a short summary for the career center is optional."}],[{"t":"ui","v":"Edit goals"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"When you're done, select "},{"t":"ui","v":"Mark completed"},{"t":"text","v":", or "},{"t":"ui","v":"End early"},{"t":"text","v":". Then leave a rating and select "},{"t":"ui","v":"Send feedback"},{"t":"text","v":". Only the career center sees it."}]},{"t":"note","c":[{"t":"text","v":"If something feels wrong, select "},{"t":"ui","v":"Report a problem"},{"t":"text","v":". You can also block the mentor, which ends the mentorship."}]},{"t":"p","c":[{"t":"text","v":"If you're an alum, you can mentor students too: select "},{"t":"ui","v":"Become a mentor"},{"t":"text","v":" on your "},{"t":"link","v":"alumni home page","href":"/alumni"},{"t":"text","v":"."}]}],"headings":["Find a mentor","Ask for mentoring","Once you're matched"],"text":"Mentors are alumni and professionals your career center has approved. They volunteer, so be clear about what you'd like help with. Open Mentoring. Find a mentor Suggested for you lists mentors who fit what you want. Select Edit what I'm looking for to choose topics, industries and fields of work, then Save preferences. Suggestions also use the major on your career record. Or search under Browse mentors. Each mentor shows what they help with and how many spots are open. Ask for mentoring On a mentor's card, select Ask for mentoring.Introduce yourself and say why you chose them. Add your goals, one per line (up to 5).Tick the box to agree that your name, email and phone are shared with the mentor if you both accept.Select Send request. The request shows under My mentorships as Waiting for mentor. At some schools the career center confirms each match first: Waiting for career center. You can have only a few requests waiting at once. Changed your mind? Select Withdraw request before it's accepted. Once you're matched The mentorship becomes Active, and you both see each other's contact details. Then you can: send private messages, here or in Messages. The career center reads them only if one of you reports a problem.Log a session after you meet. Notes are private to the two of you; a short summary for the career center is optional.Edit goals. When you're done, select Mark completed, or End early. Then leave a rating and select Send feedback. Only the career center sees it. If something feels wrong, select Report a problem. You can also block the mentor, which ends the mentorship. If you're an alum, you can mentor students too: select Become a mentor on your alumni home page."},{"slug":"results-credentials-lms","title":"Results, credentials and grades in your LMS","summary":"See a class's results, download them, withdraw a credential, and send grades to Canvas, Moodle or Blackboard.","roles":["teacher","admin"],"group":"Results","features":["class-assessments","credentials","lms-lti"],"checked":"2026-11-11","order":40,"short":[],"blocks":[{"t":"h2","c":[{"t":"text","v":"A class's results"}]},{"t":"p","c":[{"t":"text","v":"The class's page for an assessment shows its "},{"t":"ui","v":"Results"},{"t":"text","v":" from your "},{"t":"term","v":"decisions","key":"decision"},{"t":"text","v":": how many passed, were asked to resubmit or didn't pass, the average and middle scores, and the average for each "},{"t":"term","v":"rubric","key":"rubric"},{"t":"text","v":" criterion. Use "},{"t":"ui","v":"Download results (spreadsheet)"},{"t":"text","v":" for a spreadsheet of every student."}]},{"t":"h2","c":[{"t":"text","v":"Credentials"}]},{"t":"p","c":[{"t":"text","v":"When a student passes an assessment that issues "},{"t":"term","v":"credentials","key":"credential"},{"t":"text","v":", a signed credential goes into their "},{"t":"term","v":"wallet","key":"wallet"},{"t":"text","v":", with a public page anyone can use to check it."}]},{"t":"p","c":[{"t":"text","v":"If a credential was issued by mistake, open the student's "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" and use "},{"t":"ui","v":"Withdraw the credential"},{"t":"text","v":", with the reason. Its page then shows it's no longer valid."}]},{"t":"h2","c":[{"t":"text","v":"Grades in your LMS"}]},{"t":"p","c":[{"t":"text","v":"If your school uses Canvas, Moodle or Blackboard, Edulexa can send each decision's score to the course gradebook (LTI 1.3). Your school sets up the connection once with Edulexa's team. Then:"}]},{"t":"ol","items":[[{"t":"text","v":"In your course, add the Edulexa activity and pick this assessment."}],[{"t":"text","v":"Each student opens it once from the course, so the gradebook knows who they are."}],[{"t":"text","v":"Every decision sends the score to the gradebook."}]]},{"t":"p","c":[{"t":"text","v":"The class's page shows each student's grade: sent, waiting to send, not sent, or not linked yet (the student hasn't opened it from the course). If one wasn't sent, select "},{"t":"ui","v":"Send again"},{"t":"text","v":"."}]}],"headings":["A class's results","Credentials","Grades in your LMS"],"text":"A class's results The class's page for an assessment shows its Results from your decisions: how many passed, were asked to resubmit or didn't pass, the average and middle scores, and the average for each rubric criterion. Use Download results (spreadsheet) for a spreadsheet of every student. Credentials When a student passes an assessment that issues credentials, a signed credential goes into their wallet, with a public page anyone can use to check it. If a credential was issued by mistake, open the student's evidence and use Withdraw the credential, with the reason. Its page then shows it's no longer valid. Grades in your LMS If your school uses Canvas, Moodle or Blackboard, Edulexa can send each decision's score to the course gradebook (LTI 1.3). Your school sets up the connection once with Edulexa's team. Then: In your course, add the Edulexa activity and pick this assessment.Each student opens it once from the course, so the gradebook knows who they are.Every decision sends the score to the gradebook. The class's page shows each student's grade: sent, waiting to send, not sent, or not linked yet (the student hasn't opened it from the course). If one wasn't sent, select Send again."},{"slug":"switch-schools-and-roles","title":"More than one school or role","summary":"If you belong to more than one school, or have more than one role, how to move between them.","roles":["everyone"],"group":"Account and settings","features":["career-core"],"checked":"2026-11-11","order":40,"short":["More than one school: choose the school from the list at the top of your school's pages.","More than one role: open your account menu and use Switch to."],"blocks":[{"t":"h2","c":[{"t":"text","v":"More than one school"}]},{"t":"p","c":[{"t":"text","v":"If you belong to more than one school in the same role, for example as a counselor at two colleges, a list at the top of your school's pages shows the school you're working in. Choose the other school, and the page opens again with that school's menu, people and look."}]},{"t":"p","c":[{"t":"text","v":"This browser remembers your choice. On another computer or browser, choose again. If the list shows "},{"t":"ui","v":"Choose school…"},{"t":"text","v":", pick a school before you go on: until you do, some pages can't tell which school you mean."}]},{"t":"h2","c":[{"t":"text","v":"More than one role"}]},{"t":"p","c":[{"t":"text","v":"When you sign in, Edulexa opens the area for your main role. To move to another area, open your account menu (the circle with your initials, top right). Under "},{"t":"ui","v":"Switch to"},{"t":"text","v":" are the other areas you can work in, such as:"}]},{"t":"ul","items":[[{"t":"ui","v":"Career center"},{"t":"text","v":", if you're on a "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":"'s staff;"}],[{"t":"ui","v":"Faculty"},{"t":"text","v":", if you teach;"}],[{"t":"ui","v":"Employer"},{"t":"text","v":", if you also recruit for a company at a school;"}],[{"t":"ui","v":"My school"},{"t":"text","v":", if you also study at a school, or graduated from one, on Edulexa;"}],[{"t":"ui","v":"Practice and results"},{"t":"text","v":", for your own practice;"}],[{"t":"ui","v":"Recruiter portal"},{"t":"text","v":", if you also recruit;"}],[{"t":"ui","v":"Institute"},{"t":"text","v":", if you also work at a guidance institute."}]]},{"t":"p","c":[{"t":"ui","v":"Switch to"},{"t":"text","v":" shows only when there's another area for you."}]},{"t":"h3","c":[{"t":"text","v":"Career center staff who also teach"}]},{"t":"p","c":[{"t":"text","v":"If you're on a career center's staff and also teach, you start in the career center. To open your classes, select "},{"t":"ui","v":"Faculty"},{"t":"text","v":" under "},{"t":"ui","v":"Switch to"},{"t":"text","v":". To go back, select "},{"t":"ui","v":"Career center"},{"t":"text","v":". School admins also find "},{"t":"ui","v":"Class reviews"},{"t":"text","v":" and "},{"t":"ui","v":"Assessment results"},{"t":"text","v":" in the career center's menu."}]},{"t":"p","c":[{"t":"link","v":"Your account","href":"/help/your-account"},{"t":"text","v":" lists every school and role you have."}]},{"t":"h2","c":[{"t":"text","v":"A school or role is missing"}]},{"t":"p","c":[{"t":"text","v":"Your school admin adds people and gives them their roles. Ask them first. See "},{"t":"link","v":"Add people to your school","href":"/help/add-people"},{"t":"text","v":"."}]}],"headings":["More than one school","More than one role","Career center staff who also teach","A school or role is missing"],"text":"More than one school If you belong to more than one school in the same role, for example as a counselor at two colleges, a list at the top of your school's pages shows the school you're working in. Choose the other school, and the page opens again with that school's menu, people and look. This browser remembers your choice. On another computer or browser, choose again. If the list shows Choose school…, pick a school before you go on: until you do, some pages can't tell which school you mean. More than one role When you sign in, Edulexa opens the area for your main role. To move to another area, open your account menu (the circle with your initials, top right). Under Switch to are the other areas you can work in, such as: Career center, if you're on a career center's staff;Faculty, if you teach;Employer, if you also recruit for a company at a school;My school, if you also study at a school, or graduated from one, on Edulexa;Practice and results, for your own practice;Recruiter portal, if you also recruit;Institute, if you also work at a guidance institute. Switch to shows only when there's another area for you. Career center staff who also teach If you're on a career center's staff and also teach, you start in the career center. To open your classes, select Faculty under Switch to. To go back, select Career center. School admins also find Class reviews and Assessment results in the career center's menu. Your account lists every school and role you have. A school or role is missing Your school admin adds people and gives them their roles. Ask them first. See Add people to your school."},{"slug":"pilot-results","title":"Read your assessment results","summary":"Completion, review time, how often the AI's suggestions matched your teachers, points raised, appeals and students' answers.","roles":["admin","teacher"],"group":"Results","features":["class-assessments"],"checked":"2026-11-11","order":41,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"The results page brings together every assessment in a period. Teachers find it under "},{"t":"ui","v":"Results"},{"t":"text","v":" and see their own classes. School admins find it under "},{"t":"ui","v":"Assessment results"},{"t":"text","v":" and see the whole school."}]},{"t":"p","c":[{"t":"text","v":"If your school is in a pilot, the page covers the pilot's dates; otherwise choose the dates you want."}]},{"t":"h2","c":[{"t":"text","v":"What it shows"}]},{"t":"ul","items":[[{"t":"b","v":"Completion:"},{"t":"text","v":" how many students were in the classes, started, handed in, finished the "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":", and have a "},{"t":"term","v":"decision","key":"decision"},{"t":"text","v":"."}],[{"t":"b","v":"Review time:"},{"t":"text","v":" how long teachers spent actively on each student's "},{"t":"term","v":"evidence","key":"evidence"},{"t":"text","v":" before deciding. Only time with the page open, in front and in use is counted."}],[{"t":"b","v":"The AI and your teachers:"},{"t":"text","v":" how often the AI's suggested scores were within 5 points of the teacher's final score, how often they were left unchanged, and the average difference."}],[{"t":"b","v":"Points to talk about:"},{"t":"text","v":" how often the evidence raised each kind of point."}],[{"t":"b","v":"Appeals:"},{"t":"text","v":" how many are open, upheld or changed."}],[{"t":"b","v":"Students' answers:"},{"t":"text","v":" after the viva, students can answer two questions (was it fair, and did the viva reflect their own work) and leave a comment. Answers are anonymous: they're kept without the student or the "},{"t":"term","v":"attempt","key":"attempt"},{"t":"text","v":", and shown only once there are at least 3."}]]},{"t":"p","c":[{"t":"text","v":"Each assessment has its own figures below the totals, and the whole page can be downloaded as a spreadsheet for a review meeting."}]}],"headings":["What it shows"],"text":"The results page brings together every assessment in a period. Teachers find it under Results and see their own classes. School admins find it under Assessment results and see the whole school. If your school is in a pilot, the page covers the pilot's dates; otherwise choose the dates you want. What it shows Completion: how many students were in the classes, started, handed in, finished the viva, and have a decision.Review time: how long teachers spent actively on each student's evidence before deciding. Only time with the page open, in front and in use is counted.The AI and your teachers: how often the AI's suggested scores were within 5 points of the teacher's final score, how often they were left unchanged, and the average difference.Points to talk about: how often the evidence raised each kind of point.Appeals: how many are open, upheld or changed.Students' answers: after the viva, students can answer two questions (was it fair, and did the viva reflect their own work) and leave a comment. Answers are anonymous: they're kept without the student or the attempt, and shown only once there are at least 3. Each assessment has its own figures below the totals, and the whole page can be downloaded as a spreadsheet for a review meeting."},{"slug":"billing-and-voice-minutes","title":"AI voice minutes and billing","summary":"Your plan, its monthly AI voice minutes, buying more in packs of 100, and changing or cancelling the plan.","roles":["admin"],"group":"Billing","features":["school-plans"],"checked":"2026-11-11","order":50,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"Schools that signed up online manage their plan on the "},{"t":"ui","v":"Billing"},{"t":"text","v":" page. If Edulexa's team set your school up on a contract, Billing says so instead: contact us about invoices or changes."}]},{"t":"h2","c":[{"t":"text","v":"AI voice minutes"}]},{"t":"p","c":[{"t":"text","v":"Voice "},{"t":"term","v":"vivas","key":"viva"},{"t":"text","v":" use AI voice minutes. Your plan includes a number each month, and Billing shows how many you've used. When none are left, students answer the viva in writing instead; nothing else stops."}]},{"t":"p","c":[{"t":"text","v":"If you need more, use "},{"t":"ui","v":"Buy 100 minutes"},{"t":"text","v":". You pay once: by card, or in India by card or UPI. Bought minutes:"}]},{"t":"ul","items":[[{"t":"text","v":"are added as soon as the payment is confirmed;"}],[{"t":"text","v":"are used after your plan's monthly minutes;"}],[{"t":"text","v":"are kept from month to month until your plan ends."}]]},{"t":"h2","c":[{"t":"text","v":"Change or cancel your plan"}]},{"t":"ul","items":[[{"t":"ui","v":"Change plan"},{"t":"text","v":" to move between plans, paid monthly or yearly ("},{"t":"ui","v":"Yearly: 2 months free"},{"t":"text","v":")."}],[{"t":"ui","v":"Card and invoices"},{"t":"text","v":" (card payments) opens the page for your card and invoices."}],[{"t":"ui","v":"Cancel plan"},{"t":"text","v":": your school stays open until the end of the trial or the period you've paid for, then becomes read-only. Bought voice minutes end with the plan."}]]},{"t":"note","c":[{"t":"text","v":"A read-only school can still sign in, see and export everything until its data is deleted. Choose a plan and "},{"t":"ui","v":"Pay and reopen"},{"t":"text","v":" to carry on."}]}],"headings":["AI voice minutes","Change or cancel your plan"],"text":"Schools that signed up online manage their plan on the Billing page. If Edulexa's team set your school up on a contract, Billing says so instead: contact us about invoices or changes. AI voice minutes Voice vivas use AI voice minutes. Your plan includes a number each month, and Billing shows how many you've used. When none are left, students answer the viva in writing instead; nothing else stops. If you need more, use Buy 100 minutes. You pay once: by card, or in India by card or UPI. Bought minutes: are added as soon as the payment is confirmed;are used after your plan's monthly minutes;are kept from month to month until your plan ends. Change or cancel your plan Change plan to move between plans, paid monthly or yearly (Yearly: 2 months free).Card and invoices (card payments) opens the page for your card and invoices.Cancel plan: your school stays open until the end of the trial or the period you've paid for, then becomes read-only. Bought voice minutes end with the plan. A read-only school can still sign in, see and export everything until its data is deleted. Choose a plan and Pay and reopen to carry on."},{"slug":"microphone-and-browser","title":"Check your microphone and browser","summary":"Get ready for a voice viva or speaking practice: allow the microphone, check it hears you, and what to do if voice doesn't work.","roles":["everyone"],"group":"Account and settings","features":["class-assessments","speaking-practice"],"checked":"2026-11-11","order":50,"short":["Find a quiet place, and close anything else that uses your microphone.","Allow the microphone when your browser asks.","If voice doesn't work, answer the viva in writing."],"blocks":[{"t":"p","c":[{"t":"text","v":"Voice "},{"t":"term","v":"vivas","key":"viva"},{"t":"text","v":" and speaking practice use your microphone. There's no separate test page, but you can check it in a minute."}]},{"t":"h2","c":[{"t":"text","v":"Before you start"}]},{"t":"ul","items":[[{"t":"text","v":"Find a quiet place. A headset with a microphone helps in a noisy room."}],[{"t":"text","v":"Close other windows or apps that use the microphone, such as a video call."}],[{"t":"text","v":"Do the viva in one window or tab only. If it's open somewhere else, the page asks you to end it there first."}]]},{"t":"h2","c":[{"t":"text","v":"Allow the microphone"}]},{"t":"p","c":[{"t":"text","v":"When you select "},{"t":"ui","v":"Start the viva by voice"},{"t":"text","v":", or "},{"t":"ui","v":"Start answering"},{"t":"text","v":" in speaking practice, your browser asks to use the microphone. Choose to allow it."}]},{"t":"p","c":[{"t":"text","v":"If you blocked it before, the page says your browser didn't let it use the microphone. Select the icon next to the site's address in your browser, allow the microphone, and reload the page."}]},{"t":"h2","c":[{"t":"text","v":"Check that it hears you"}]},{"t":"ul","items":[[{"t":"text","v":"In "},{"t":"link","v":"Speaking practice","href":"/prep/delivery"},{"t":"text","v":", a bar next to "},{"t":"ui","v":"Listening"},{"t":"text","v":" moves while you talk. If the page says it didn't hear an answer, check that the right microphone is selected in your computer's sound settings."}],[{"t":"text","v":"In a voice viva, what you say appears on the screen as you go. If your words appear, your microphone works."}]]},{"t":"h2","c":[{"t":"text","v":"Which browser"}]},{"t":"p","c":[{"t":"text","v":"Edulexa doesn't list supported browsers. Speaking practice counts your words with the browser's own speech recognition, which Chrome, Edge and Safari have. In other browsers it measures only your pauses and when you started."}]},{"t":"h2","c":[{"t":"text","v":"If voice doesn't work"}]},{"t":"p","c":[{"t":"text","v":"In the viva, select "},{"t":"ui","v":"Answer in writing"},{"t":"text","v":", or "},{"t":"ui","v":"Voice didn't work? Answer in writing"},{"t":"text","v":" if that's what the page shows. Your teacher sees that voice failed, so it doesn't count against you. See "},{"t":"link","v":"Do the viva","href":"/help/the-viva"},{"t":"text","v":"."}]}],"headings":["Before you start","Allow the microphone","Check that it hears you","Which browser","If voice doesn't work"],"text":"Voice vivas and speaking practice use your microphone. There's no separate test page, but you can check it in a minute. Before you start Find a quiet place. A headset with a microphone helps in a noisy room.Close other windows or apps that use the microphone, such as a video call.Do the viva in one window or tab only. If it's open somewhere else, the page asks you to end it there first. Allow the microphone When you select Start the viva by voice, or Start answering in speaking practice, your browser asks to use the microphone. Choose to allow it. If you blocked it before, the page says your browser didn't let it use the microphone. Select the icon next to the site's address in your browser, allow the microphone, and reload the page. Check that it hears you In Speaking practice, a bar next to Listening moves while you talk. If the page says it didn't hear an answer, check that the right microphone is selected in your computer's sound settings.In a voice viva, what you say appears on the screen as you go. If your words appear, your microphone works. Which browser Edulexa doesn't list supported browsers. Speaking practice counts your words with the browser's own speech recognition, which Chrome, Edge and Safari have. In other browsers it measures only your pauses and when you started. If voice doesn't work In the viva, select Answer in writing, or Voice didn't work? Answer in writing if that's what the page shows. Your teacher sees that voice failed, so it doesn't count against you. See Do the viva."},{"slug":"download-or-delete-your-data","title":"Download or delete your data","summary":"Download a copy of everything in your Edulexa account, or delete your data.","roles":["admin","teacher","staff","member","recruiter","employer","admissions","mentor"],"group":"Your data and privacy","features":["member-privacy"],"checked":"2026-11-12","order":60,"short":["Open Privacy and your data, from your account menu or from Your account under More settings.","Select Download my data for a copy of everything in your account.","To delete your data, type DELETE MY DATA and select Delete my data. This can't be undone."],"blocks":[{"t":"p","c":[{"t":"link","v":"Privacy and your data","href":"/settings/privacy"},{"t":"text","v":" is where you download a copy of your data, or delete it. These are your rights under privacy laws."}]},{"t":"h2","c":[{"t":"text","v":"Open it"}]},{"t":"ul","items":[[{"t":"b","v":"If you use Edulexa on your own:"},{"t":"text","v":" open your account menu (your initials, top right) and select "},{"t":"ui","v":"Privacy and your data"},{"t":"text","v":"."}],[{"t":"b","v":"Everyone else:"},{"t":"text","v":" open your account menu, select "},{"t":"ui","v":"Your account"},{"t":"text","v":", and under "},{"t":"ui","v":"More settings"},{"t":"text","v":" select "},{"t":"ui","v":"Privacy and your data"},{"t":"text","v":"."}]]},{"t":"h2","c":[{"t":"text","v":"Download a copy"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Download my data"},{"t":"text","v":". You get one file with everything in your account: your profile, your assessments and practice, the work you handed in, interviews, scores and feedback, "},{"t":"term","v":"credentials","key":"credential"},{"t":"text","v":", "},{"t":"term","v":"appeals","key":"appeal"},{"t":"text","v":" and "},{"t":"term","v":"accommodations","key":"accommodation"},{"t":"text","v":", and the records schools, employers and the law keep about you. The file's name ends in .json, and it opens in a web browser."}]},{"t":"p","c":[{"t":"text","v":"Two things aren't in it: the details of integrity checks, and reviewers' private notes. The file says why, and how to ask for them."}]},{"t":"h2","c":[{"t":"text","v":"Delete your data"}]},{"t":"p","c":[{"t":"text","v":"Download a copy first if you want one. Deleting can't be undone. The page shows what happens to each kind of record:"}]},{"t":"ul","items":[[{"t":"ui","v":"Deleted"},{"t":"text","v":": for example what you did in the code editor, interview transcripts, your résumés and your feedback."}],[{"t":"ui","v":"Your name removed"},{"t":"text","v":": your name becomes \"Deleted user\", your e-mail address is replaced, and credentials you earned are revoked."}],[{"t":"ui","v":"Kept, without your name"},{"t":"text","v":": the code you handed in, test results, defense scores and employers' "},{"t":"term","v":"decisions","key":"decision"},{"t":"text","v":" stay, because employers must be able to show how they decided. They no longer carry your name or e-mail address."}],[{"t":"ui","v":"Handled by others, or kept by law"},{"t":"text","v":": we ask any school that holds records about you to delete them, and the school decides. Records the law requires us to keep stay, without your name, until their time is up."}]]},{"t":"p","c":[{"t":"text","v":"To go ahead, type DELETE MY DATA in the box, exactly as shown, and select "},{"t":"ui","v":"Delete my data"},{"t":"text","v":". The page then shows how many records were deleted, which schools were asked to delete theirs, and what this didn't cover. Then select "},{"t":"ui","v":"Sign out"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"Your sign-in (your e-mail address and password) is kept separately. To delete it too, contact Edulexa support: see "},{"t":"link","v":"Get help and contact support","href":"/help/help-and-support"},{"t":"text","v":". Until then, signing in again takes you back to your emptied account."}]}],"headings":["Open it","Download a copy","Delete your data"],"text":"Privacy and your data is where you download a copy of your data, or delete it. These are your rights under privacy laws. Open it If you use Edulexa on your own: open your account menu (your initials, top right) and select Privacy and your data.Everyone else: open your account menu, select Your account, and under More settings select Privacy and your data. Download a copy Select Download my data. You get one file with everything in your account: your profile, your assessments and practice, the work you handed in, interviews, scores and feedback, credentials, appeals and accommodations, and the records schools, employers and the law keep about you. The file's name ends in .json, and it opens in a web browser. Two things aren't in it: the details of integrity checks, and reviewers' private notes. The file says why, and how to ask for them. Delete your data Download a copy first if you want one. Deleting can't be undone. The page shows what happens to each kind of record: Deleted: for example what you did in the code editor, interview transcripts, your résumés and your feedback.Your name removed: your name becomes \"Deleted user\", your e-mail address is replaced, and credentials you earned are revoked.Kept, without your name: the code you handed in, test results, defense scores and employers' decisions stay, because employers must be able to show how they decided. They no longer carry your name or e-mail address.Handled by others, or kept by law: we ask any school that holds records about you to delete them, and the school decides. Records the law requires us to keep stay, without your name, until their time is up. To go ahead, type DELETE MY DATA in the box, exactly as shown, and select Delete my data. The page then shows how many records were deleted, which schools were asked to delete theirs, and what this didn't cover. Then select Sign out. Your sign-in (your e-mail address and password) is kept separately. To delete it too, contact Edulexa support: see Get help and contact support. Until then, signing in again takes you back to your emptied account."},{"slug":"privacy-requests","title":"Answer students' privacy requests","summary":"Handle a student's request for a copy of their data, a correction or deletion, within your school's deadline.","roles":["admin","staff"],"group":"Your data and privacy","features":["career-privacy"],"checked":"2026-11-11","order":60,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"Students ask for a copy of their data, a correction or deletion from their privacy page. A request also arrives when a student deletes their Edulexa account: it lists the records your school holds about them, such as class "},{"t":"term","v":"attempts","key":"attempt"},{"t":"text","v":", documents and "},{"t":"term","v":"roster","key":"roster"},{"t":"text","v":" entries."}]},{"t":"p","c":[{"t":"text","v":"Requests are on the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":"'s privacy page, under "},{"t":"ui","v":"Privacy requests"},{"t":"text","v":" and "},{"t":"ui","v":"Request queue"},{"t":"text","v":". Each shows when it's due; overdue ones are marked. Your school sets how many days you have under "},{"t":"ui","v":"Days to answer requests"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Handle a request"}]},{"t":"p","c":[{"t":"text","v":"Open the request and select "},{"t":"ui","v":"Start"},{"t":"text","v":". Then:"}]},{"t":"ul","items":[[{"t":"b","v":"A copy of their data:"},{"t":"text","v":" use "},{"t":"ui","v":"Preview export"},{"t":"text","v":" to check it, then "},{"t":"ui","v":"Release export to the student"},{"t":"text","v":". They download it from their privacy page."}],[{"t":"b","v":"A correction:"},{"t":"text","v":" make the change, then "},{"t":"ui","v":"Mark corrected"},{"t":"text","v":" with a "},{"t":"ui","v":"Note to the student"},{"t":"text","v":"."}],[{"t":"b","v":"Deletion:"},{"t":"text","v":" use "},{"t":"ui","v":"Show erasure plan"},{"t":"text","v":" to see exactly what would be deleted, table by table. To go ahead, "},{"t":"ui","v":"Type ERASE to confirm"},{"t":"text","v":" and select "},{"t":"ui","v":"Erase and complete"},{"t":"text","v":". Erasure can't be undone. Records the law requires your school to keep are kept, as the plan shows."}]]},{"t":"p","c":[{"t":"text","v":"To refuse a request, use "},{"t":"ui","v":"Decline"},{"t":"text","v":" with a note explaining why. Every step is kept in the request's audit trail."}]}],"headings":["Handle a request"],"text":"Students ask for a copy of their data, a correction or deletion from their privacy page. A request also arrives when a student deletes their Edulexa account: it lists the records your school holds about them, such as class attempts, documents and roster entries. Requests are on the career center's privacy page, under Privacy requests and Request queue. Each shows when it's due; overdue ones are marked. Your school sets how many days you have under Days to answer requests. Handle a request Open the request and select Start. Then: A copy of their data: use Preview export to check it, then Release export to the student. They download it from their privacy page.A correction: make the change, then Mark corrected with a Note to the student.Deletion: use Show erasure plan to see exactly what would be deleted, table by table. To go ahead, Type ERASE to confirm and select Erase and complete. Erasure can't be undone. Records the law requires your school to keep are kept, as the plan shows. To refuse a request, use Decline with a note explaining why. Every step is kept in the request's audit trail."},{"slug":"your-data","title":"Your data and privacy","summary":"See and control how your school uses your data, ask for a copy, a correction or deletion, and delete your account.","roles":["student","alumni"],"group":"Your data and privacy","features":["career-privacy","member-privacy"],"checked":"2026-11-12","order":61,"short":[],"blocks":[{"t":"h2","c":[{"t":"text","v":"At your school"}]},{"t":"p","c":[{"t":"text","v":"Your school's privacy page is in the "},{"t":"term","v":"career center","key":"career-center"},{"t":"text","v":" under your account: "},{"t":"link","v":"Privacy","href":"/student/privacy"},{"t":"text","v":"."}]},{"t":"ul","items":[[{"t":"b","v":"How your data is used:"},{"t":"text","v":" uses that need your consent are listed, each with an on/off switch. Withdrawing stops the use from then on."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Your data rights"},{"t":"text","v":", at "},{"t":"ui","v":"What do you want?"},{"t":"text","v":" choose a copy of your data, a correction, or deletion, add any details, and select "},{"t":"ui","v":"Send request"},{"t":"text","v":". Your school's career office answers within the time shown."}],[{"t":"text","v":"Under "},{"t":"ui","v":"Your data requests"},{"t":"text","v":", follow your requests, and "},{"t":"ui","v":"Download"},{"t":"text","v":" your copy when it's ready."}]]},{"t":"p","c":[{"t":"text","v":"If you're under the age your country sets, a parent or guardian may need to agree first."}]},{"t":"h2","c":[{"t":"text","v":"Your Edulexa account"}]},{"t":"p","c":[{"t":"text","v":"To download everything in your account, or delete it, go to "},{"t":"link","v":"Privacy and your data","href":"/settings/privacy"},{"t":"text","v":" (the steps are in "},{"t":"link","v":"Download or delete your data","href":"/help/download-or-delete-your-data"},{"t":"text","v":"). Deleting your account removes your own activity. Records your school holds about your class work, such as your "},{"t":"term","v":"attempts","key":"attempt"},{"t":"text","v":" and documents, are the school's: your deletion sends the school a request to erase them, and the school completes it."}]}],"headings":["At your school","Your Edulexa account"],"text":"At your school Your school's privacy page is in the career center under your account: Privacy. How your data is used: uses that need your consent are listed, each with an on/off switch. Withdrawing stops the use from then on.Under Your data rights, at What do you want? choose a copy of your data, a correction, or deletion, add any details, and select Send request. Your school's career office answers within the time shown.Under Your data requests, follow your requests, and Download your copy when it's ready. If you're under the age your country sets, a parent or guardian may need to agree first. Your Edulexa account To download everything in your account, or delete it, go to Privacy and your data (the steps are in Download or delete your data). Deleting your account removes your own activity. Records your school holds about your class work, such as your attempts and documents, are the school's: your deletion sends the school a request to erase them, and the school completes it."},{"slug":"hand-in-your-work","title":"Hand in your work","summary":"Start the assessment and hand in a document, a GitHub repository, a project, a coding task or an exam.","roles":["student"],"group":"Handing in","features":["class-assessments"],"checked":"2026-11-11","order":70,"short":["Open the assessment under My assessments and select Start.","Upload your file, paste your text, or hand in your project, coding task or exam.","You can replace it until your viva starts."],"blocks":[{"t":"p","c":[{"t":"text","v":"Your assessments are under "},{"t":"ui","v":"My assessments"},{"t":"text","v":". Open one to see what to do, how you're assessed, and when it's due. When you're ready, select "},{"t":"ui","v":"Start"},{"t":"text","v":"."}]},{"t":"shot","name":"my-assessments","alt":"My assessments, with an open project and an essay that opens later to do, and a lab report waiting for the teacher","w":1600,"h":883},{"t":"p","c":[{"t":"text","v":"How you hand in depends on the assessment:"}]},{"t":"h2","c":[{"t":"text","v":"An essay, report, lab report or presentation"}]},{"t":"p","c":[{"t":"text","v":"Choose your file (PDF, Word or PowerPoint, up to 25 MB) and select "},{"t":"ui","v":"Upload and hand in"},{"t":"text","v":". Or use "},{"t":"ui","v":"Paste the text instead"},{"t":"text","v":" and "},{"t":"ui","v":"Hand in this text"},{"t":"text","v":" (50 words at least)."}]},{"t":"p","c":[{"t":"text","v":"The "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":"'s questions are about what's in your file, so it needs readable text. A scan or a photo of your pages can't be read: save your work as a PDF with text, upload the Word or PowerPoint file, or paste the text. Old formats such as .doc and .ppt need saving as .docx, .pptx or PDF first."}]},{"t":"h2","c":[{"t":"text","v":"A project"}]},{"t":"ul","items":[[{"t":"text","v":"A GitHub repository, under "},{"t":"ui","v":"Hand in a GitHub repository"},{"t":"text","v":": enter "},{"t":"ui","v":"Your GitHub username"},{"t":"text","v":" and the "},{"t":"ui","v":"Repository"},{"t":"text","v":", then select "},{"t":"ui","v":"Check the repository"},{"t":"text","v":". To show it's yours, add the code you're given to your GitHub profile bio (or a public gist's description), then select "},{"t":"ui","v":"I've added it, check now"},{"t":"text","v":". You can remove the code afterwards."}],[{"t":"text","v":"A .zip, under "},{"t":"ui","v":"Or upload your project"},{"t":"text","v":": your project folder zipped, up to 25 MB, without dependencies or build output such as node_modules."}]]},{"t":"h2","c":[{"t":"text","v":"A coding task or an exam"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Open the coding task"},{"t":"text","v":" or "},{"t":"ui","v":"Open the exam"},{"t":"text","v":", do it there, then come back and select "},{"t":"ui","v":"Hand in my solution"},{"t":"text","v":" or "},{"t":"ui","v":"Hand in my exam"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"You can replace what you handed in until your viva starts. From then on, your work is fixed, because the questions are about it."}]},{"t":"p","c":[{"t":"text","v":"Next comes the viva (and, for some coding assessments, a short "},{"t":"term","v":"change task","key":"change-task"},{"t":"text","v":" first). See "},{"t":"link","v":"Do the viva","href":"/help/the-viva"},{"t":"text","v":"."}]}],"headings":["An essay, report, lab report or presentation","A project","A coding task or an exam"],"text":"Your assessments are under My assessments. Open one to see what to do, how you're assessed, and when it's due. When you're ready, select Start. How you hand in depends on the assessment: An essay, report, lab report or presentation Choose your file (PDF, Word or PowerPoint, up to 25 MB) and select Upload and hand in. Or use Paste the text instead and Hand in this text (50 words at least). The viva's questions are about what's in your file, so it needs readable text. A scan or a photo of your pages can't be read: save your work as a PDF with text, upload the Word or PowerPoint file, or paste the text. Old formats such as .doc and .ppt need saving as .docx, .pptx or PDF first. A project A GitHub repository, under Hand in a GitHub repository: enter Your GitHub username and the Repository, then select Check the repository. To show it's yours, add the code you're given to your GitHub profile bio (or a public gist's description), then select I've added it, check now. You can remove the code afterwards.A .zip, under Or upload your project: your project folder zipped, up to 25 MB, without dependencies or build output such as node_modules. A coding task or an exam Select Open the coding task or Open the exam, do it there, then come back and select Hand in my solution or Hand in my exam. You can replace what you handed in until your viva starts. From then on, your work is fixed, because the questions are about it. Next comes the viva (and, for some coding assessments, a short change task first). See Do the viva."},{"slug":"change-task-student","title":"Do the change task","summary":"For some coding assessments, you make one small, timed change to your own code before the viva.","roles":["student"],"group":"Handing in","features":["class-assessments"],"checked":"2026-11-11","order":71,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"Some coding assessments ask you to make one small change to your own code before the "},{"t":"term","v":"viva","key":"viva"},{"t":"text","v":". It shows you know your code well enough to change it."}]},{"t":"ol","items":[[{"t":"text","v":"After you hand in your work, the change task is prepared from your own code. This usually takes a minute or two; the page updates by itself."}],[{"t":"text","v":"When it's ready, the page shows how many minutes you'll have. You see what to change only when you start, and the clock runs from then. Select "},{"t":"ui","v":"Start the change task (20 minutes)"},{"t":"text","v":" (your time may differ)."}],[{"t":"text","v":"Select "},{"t":"ui","v":"Open the workspace (new tab)"},{"t":"text","v":". You work on a copy of your code, with the AI assistant off."}],[{"t":"text","v":"Make the change, run the tests, and submit in the workspace. Then come back and select "},{"t":"ui","v":"Hand in the change"},{"t":"text","v":"."}]]},{"t":"p","c":[{"t":"text","v":"If time runs out before you hand in, whatever you submitted last in the workspace counts. Then the viva comes next: see "},{"t":"link","v":"Do the viva","href":"/help/the-viva"},{"t":"text","v":"."}]},{"t":"note","c":[{"t":"text","v":"Once your change task has started, the work you handed in can't be replaced."}]}],"headings":[],"text":"Some coding assessments ask you to make one small change to your own code before the viva. It shows you know your code well enough to change it. After you hand in your work, the change task is prepared from your own code. This usually takes a minute or two; the page updates by itself.When it's ready, the page shows how many minutes you'll have. You see what to change only when you start, and the clock runs from then. Select Start the change task (20 minutes) (your time may differ).Select Open the workspace (new tab). You work on a copy of your code, with the AI assistant off.Make the change, run the tests, and submit in the workspace. Then come back and select Hand in the change. If time runs out before you hand in, whatever you submitted last in the workspace counts. Then the viva comes next: see Do the viva. Once your change task has started, the work you handed in can't be replaced."},{"slug":"the-viva","title":"Do the viva","summary":"Explain your own work by voice or in writing. What to expect, and what to do if voice doesn't work.","roles":["student"],"group":"The viva","features":["class-assessments"],"checked":"2026-11-11","order":72,"short":["A few questions about your own work, one at a time, by voice or in writing.","Explain in your own words: spelling, grammar and accent don't count.","If voice doesn't work, answer in writing: it doesn't count against you."],"blocks":[{"t":"p","c":[{"t":"text","v":"The viva is a short oral examination about the work you handed in. An AI examiner asks a few questions, one at a time: why you made a choice, what a part of your work means, or how you'd answer an objection. It doesn't give hints or scores. Your teacher reads the whole viva and decides your result."}]},{"t":"h2","c":[{"t":"text","v":"By voice"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Start the viva by voice"},{"t":"text","v":" and allow your browser to use the microphone. Answer each question out loud; you see what's said as you go. When you've answered the last question, select "},{"t":"ui","v":"End the viva and hand in"},{"t":"text","v":"."}]},{"t":"p","c":[{"t":"text","v":"Find a quiet place, and give yourself the time the assessment page shows."}]},{"t":"h2","c":[{"t":"text","v":"In writing"}]},{"t":"p","c":[{"t":"text","v":"Select "},{"t":"ui","v":"Answer in writing"},{"t":"text","v":", or it's offered automatically when the viva is in writing. Type each answer and select "},{"t":"ui","v":"Send answer"},{"t":"text","v":"; the last one is "},{"t":"ui","v":"Send my last answer and hand in"},{"t":"text","v":"."}]},{"t":"h2","c":[{"t":"text","v":"Tips"}]},{"t":"ul","items":[[{"t":"text","v":"Explain in your own words. Spelling, grammar and accent don't count; understanding does."}],[{"t":"text","v":"Talk about your own work, in detail. It's fine to say what you'd do differently."}],[{"t":"text","v":"Don't read your work out. Your teacher can see when answers are mostly copied from it."}]]},{"t":"h2","c":[{"t":"text","v":"If voice doesn't work"}]},{"t":"p","c":[{"t":"text","v":"If the call doesn't connect, or nothing you said was kept, use "},{"t":"ui","v":"Voice didn't work? Answer in writing"},{"t":"text","v":". Your teacher sees that you answered in writing after voice failed, so it doesn't count against you."}]},{"t":"p","c":[{"t":"text","v":"After the viva, you may be asked "},{"t":"ui","v":"Two quick questions"},{"t":"text","v":" about the assessment. Your answers are anonymous. Then your teacher decides: see "},{"t":"link","v":"Your result and appeals","href":"/help/results-and-appeals"},{"t":"text","v":"."}]}],"headings":["By voice","In writing","Tips","If voice doesn't work"],"text":"The viva is a short oral examination about the work you handed in. An AI examiner asks a few questions, one at a time: why you made a choice, what a part of your work means, or how you'd answer an objection. It doesn't give hints or scores. Your teacher reads the whole viva and decides your result. By voice Select Start the viva by voice and allow your browser to use the microphone. Answer each question out loud; you see what's said as you go. When you've answered the last question, select End the viva and hand in. Find a quiet place, and give yourself the time the assessment page shows. In writing Select Answer in writing, or it's offered automatically when the viva is in writing. Type each answer and select Send answer; the last one is Send my last answer and hand in. Tips Explain in your own words. Spelling, grammar and accent don't count; understanding does.Talk about your own work, in detail. It's fine to say what you'd do differently.Don't read your work out. Your teacher can see when answers are mostly copied from it. If voice doesn't work If the call doesn't connect, or nothing you said was kept, use Voice didn't work? Answer in writing. Your teacher sees that you answered in writing after voice failed, so it doesn't count against you. After the viva, you may be asked Two quick questions about the assessment. Your answers are anonymous. Then your teacher decides: see Your result and appeals."},{"slug":"results-and-appeals","title":"Your result and appeals","summary":"See your teacher's decision and comment, find your credential, appeal once, or hand in again.","roles":["student"],"group":"After the decision","features":["class-assessments","credentials"],"checked":"2026-11-11","order":80,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"When your teacher has decided, the assessment page under "},{"t":"ui","v":"My assessments"},{"t":"text","v":" shows your result: your score for each part of the "},{"t":"term","v":"rubric","key":"rubric"},{"t":"text","v":", your overall score out of 100, and your teacher's comment."}]},{"t":"h2","c":[{"t":"text","v":"If you passed"}]},{"t":"p","c":[{"t":"text","v":"If the assessment issues "},{"t":"term","v":"credentials","key":"credential"},{"t":"text","v":", a signed credential is added to your "},{"t":"term","v":"wallet","key":"wallet"},{"t":"text","v":". Select "},{"t":"ui","v":"View your credential"},{"t":"text","v":" to see it, or open "},{"t":"ui","v":"Your wallet"},{"t":"text","v":" for all of them. Each has a public page you can share; anyone can check it's real."}]},{"t":"h2","c":[{"t":"text","v":"If you're asked to resubmit"}]},{"t":"p","c":[{"t":"text","v":"You can hand in again, even after the due date. Select "},{"t":"ui","v":"Start attempt 2"},{"t":"text","v":" (or the next number). Your teacher's feedback on the "},{"t":"term","v":"attempt","key":"attempt"},{"t":"text","v":" before stays on the page while you work."}]},{"t":"h2","c":[{"t":"text","v":"If you think the decision is wrong"}]},{"t":"p","c":[{"t":"text","v":"You can appeal once, within 14 days. Select "},{"t":"ui","v":"Appeal"},{"t":"text","v":", explain why the decision should change, and select "},{"t":"ui","v":"Send appeal"},{"t":"text","v":". Another teacher of your class, or a school admin, looks at it and answers on the same page. They either keep the decision or change it."}]},{"t":"note","c":[{"t":"text","v":"Once you start a new attempt, you can no longer appeal the decision on the one before."}]}],"headings":["If you passed","If you're asked to resubmit","If you think the decision is wrong"],"text":"When your teacher has decided, the assessment page under My assessments shows your result: your score for each part of the rubric, your overall score out of 100, and your teacher's comment. If you passed If the assessment issues credentials, a signed credential is added to your wallet. Select View your credential to see it, or open Your wallet for all of them. Each has a public page you can share; anyone can check it's real. If you're asked to resubmit You can hand in again, even after the due date. Select Start attempt 2 (or the next number). Your teacher's feedback on the attempt before stays on the page while you work. If you think the decision is wrong You can appeal once, within 14 days. Select Appeal, explain why the decision should change, and select Send appeal. Another teacher of your class, or a school admin, looks at it and answers on the same page. They either keep the decision or change it. Once you start a new attempt, you can no longer appeal the decision on the one before."},{"slug":"words-we-use","title":"Words we use","summary":"Short, plain explanations of the words you meet in Edulexa and in these guides.","roles":["everyone"],"group":"Getting started","features":["help-center"],"checked":"2026-11-11","order":90,"short":[],"blocks":[{"t":"p","c":[{"t":"text","v":"Some words in Edulexa have a special meaning, or are new to many people. Here they are in plain words, with a guide to read next where there is one."}]},{"t":"glossary"}],"headings":[],"text":"Some words in Edulexa have a special meaning, or are new to many people. Here they are in plain words, with a guide to read next where there is one."}],"es":[],"hi":[],"ar":[]};

export const HELP_AUDIENCES: HelpAudience[] = [{"id":"admin","groups":["Getting started","People and classes","Assessments","Reviewing and deciding","Results","Billing","Account and settings","Your data and privacy"],"steps":["getting-started","add-people","classes-and-rosters","create-an-assessment","give-to-a-class","pilot-results"]},{"id":"teacher","groups":["Getting started","People and classes","Assessments","Reviewing and deciding","Results","Account and settings","Your data and privacy"],"steps":["create-an-assessment","rubric-and-viva","give-to-a-class","review-the-evidence","decide-and-appeals","results-credentials-lms"]},{"id":"staff","groups":["Getting started","Students and appointments","Documents and résumés","Employers and jobs","Reports","Account and settings","Your data and privacy"],"steps":["staff-getting-started","appointments-and-availability","caseload","staff-document-review","employers-and-approvals","jobs-drives-and-interviews","reports-and-outcomes"]},{"id":"student","groups":["Getting started","Handing in","The viva","After the decision","Your credentials","Career help","Jobs and internships","Account and settings","Your data and privacy"],"steps":["hand-in-your-work","the-viva","results-and-appeals"]},{"id":"alumni","groups":["Getting started","Career help","Jobs and internships","Your credentials","Mentoring","Account and settings","Your data and privacy"],"steps":[]},{"id":"member","groups":["Getting started","Guidance","Practice","Prove your skills","Your record","Account and settings","Your data and privacy"],"steps":["member-getting-started","career-direction","daily-practice","interview-and-speaking-practice","exams-and-challenges","member-results-and-credentials","member-resumes"]},{"id":"recruiter","groups":["Getting started","Assessments","Reviewing candidates","Fairness","Account and settings","Your data and privacy"],"steps":["recruiter-getting-started","recruiter-send-an-assessment","recruiter-results-and-proctoring","recruiter-evidence-packs","recruiter-appeals-and-accommodations","recruiter-validity-and-bias"]},{"id":"employer","groups":["Getting started","Hiring","Account and settings","Your data and privacy"],"steps":["employer-getting-started","employer-jobs-and-drives","employer-interviews-and-challenges","employer-resume-books"]},{"id":"admissions","groups":["Getting started","Forms and the quiz","Leads","Account and settings","Your data and privacy"],"steps":["institute-setup","guidance-forms","admissions-leads"]},{"id":"mentor","groups":["Getting started","Guidance requests","Mentoring","Account and settings","Your data and privacy"],"steps":[]}];

export const HELP_GLOSSARY: Record<string, HelpGlossaryEntry[]> = {"en":[{"key":"accommodation","term":"accommodation","means":"A change that makes an assessment fair for someone, such as extra time, or a written defense instead of a spoken one."},{"key":"appeal","term":"appeal","means":"Asking for a decision to be looked at again. For a class assessment, you can appeal once, within 14 days.","see":"results-and-appeals"},{"key":"applicant-tracking-system","term":"applicant tracking system","means":"The system a company uses to manage job applicants, such as Greenhouse, Lever or Workday. Edulexa can send results to it.","see":"recruiter-getting-started"},{"key":"attempt","term":"attempt","means":"One go at an assessment, from starting it to the teacher's decision. If you're asked to resubmit, you start a new attempt.","see":"hand-in-your-work"},{"key":"campus-drive","term":"campus drive","means":"A company's hiring round at a school. Students apply, some are shortlisted and interviewed, and some get an offer.","see":"campus-jobs-and-interviews"},{"key":"career-center","term":"career center","means":"Your school's career office. Its staff help with appointments, résumés, jobs and internships.","see":"appointments"},{"key":"caseload","term":"caseload","means":"The students a career counselor is assigned to look after.","see":"caseload"},{"key":"change-task","term":"change task","means":"For some coding assessments, one small, timed change you make to your own code before the viva. It shows you know your code well.","see":"change-task-student"},{"key":"credential","term":"credential","means":"A signed record of something you passed. It has its own page, so anyone you share it with can check it's real.","see":"credentials-and-passport"},{"key":"decision","term":"decision","means":"A person's result for a piece of work. A teacher passes the work, sends it back to be handed in again, or fails it. A recruiter advances a candidate, holds them, or declines them.","see":"results-and-appeals"},{"key":"document-review","term":"document review","means":"Sending your résumé, cover letter or another document to your career center, so a counselor can comment on it.","see":"document-review"},{"key":"evidence","term":"evidence","means":"Everything a teacher or reviewer looks at before deciding, such as the work handed in and the viva. For coding work, it also shows the tests and how the code was written.","see":"review-the-evidence"},{"key":"evidence-pack","term":"evidence pack","means":"Everything a recruiter needs to decide on a candidate's coding work, in one place, such as the tests, the code changes, AI use, integrity signals and the defense.","see":"recruiter-evidence-packs"},{"key":"impact-ratio","term":"impact ratio","means":"One group's rate divided by the highest group's rate. Below 0.80 suggests one group may be treated less fairly, and should be looked into.","see":"recruiter-validity-and-bias"},{"key":"integrity-signal","term":"integrity signal","means":"A pattern in a candidate's work worth talking about with them, such as text pasted from outside the editor. It isn't proof of cheating, and many have innocent explanations.","see":"recruiter-evidence-packs"},{"key":"lead","term":"lead","means":"Someone who asked a guidance institute about its courses or for career guidance, or sent its website form. The admissions team follows each one up.","see":"admissions-leads"},{"key":"lms","term":"LMS","means":"Your school's online course system, such as Canvas, Moodle or Blackboard. Edulexa can send grades to it.","see":"results-credentials-lms"},{"key":"mentoring","term":"mentoring","means":"Advice from someone with more experience, often a graduate of your school, over a few conversations. It's free.","see":"mentoring"},{"key":"proctored","term":"proctored","means":"Watched for fairness while it's taken. Edulexa records events such as switching tabs or pasting text, for a person to review. There's no face or gaze detection.","see":"recruiter-results-and-proctoring"},{"key":"resume-book","term":"résumé book","means":"A school's collection of student résumés that approved employers can look through. Students choose whether to be in it.","see":"resume-book"},{"key":"roster","term":"roster","means":"The list of students in a class, with their e-mail addresses. Students sign in with the e-mail address on the roster.","see":"classes-and-rosters"},{"key":"rubric","term":"rubric","means":"The list of what the work is judged on, with the points for each part. Students can see it before they start.","see":"rubric-and-viva"},{"key":"skill-passport","term":"skill passport","means":"A page with your checked skills and a link you can share, for example with employers. You control what it shows.","see":"credentials-and-passport"},{"key":"streak","term":"streak","means":"The number of days in a row you have practiced on Edulexa. A streak freeze, earned by practicing 7 days in a row, covers one missed day.","see":"daily-practice"},{"key":"two-step-sign-in","term":"two-step sign-in","means":"Signing in with your password and also a code from an app on your phone. Staff accounts need it, because they can see students' information.","see":"sign-in"},{"key":"viva","term":"viva","means":"A short spoken conversation about your own work, where you explain what you did and why. Your teacher listens to it later.","see":"the-viva"},{"key":"voice-defense","term":"voice defense","means":"A short spoken conversation with an AI interviewer about code you wrote, such as why you made your choices and what you would change. It is graded, and passing can earn a credential.","see":"exams-and-challenges"},{"key":"voice-minutes","term":"voice minutes","means":"The time available for spoken conversations with the AI, such as voice vivas. When they run out, students answer in writing instead.","see":"billing-and-voice-minutes"},{"key":"wallet","term":"wallet","means":"The place in your account where your credentials are kept. You decide which ones to share.","see":"credentials-and-passport"},{"key":"work-trial","term":"work trial","means":"A private coding task made from a small part of a company's own code, with bugs put there on purpose for the candidate to find and fix.","see":"recruiter-send-an-assessment"}]};

